/// A boundary route is calculated before any author callback. Each step keeps
/// the exact document and translated physical sample selected by that route.
struct PointerBoundaryStep {
    context: AutomationRealmSnapshot,
    input: oryn_js::v8_bindings::NativePointerInput,
    target: Option<NodeId>,
}

pub(crate) type CaptureDocumentIdentity = (RealmId, NodeId, u64, u64, u64);

struct StationaryPointerRoute {
    boundaries: Vec<(
        AutomationRealmSnapshot,
        oryn_js::v8_bindings::NativePointerBoundary,
    )>,
    next: usize,
    retry_at: Option<std::time::Instant>,
}
impl StationaryPointerRoute {
    fn delay(&self) -> Option<Duration> {
        let Some((_, receipt)) = self.boundaries.get(self.next) else {
            return Some(Duration::ZERO);
        };
        // Revoked ownership must wake cleanup even if the old document is parked.
        if !receipt.retry_safe() {
            return Some(Duration::ZERO);
        }
        if receipt.owner().execution_suspended() {
            return None;
        }
        Some(self.retry_at.map_or(Duration::ZERO, |deadline| {
            deadline.saturating_duration_since(std::time::Instant::now())
        }))
    }
}

/// The Actions operation owns both cross-document boundary phases and the
/// selected document's ordinary dispatch until its complete default suffix.
pub(crate) struct PointerDispatchRoute {
    selected: AutomationRealmSnapshot,
    input: oryn_js::v8_bindings::NativePointerInput,
    action: oryn_js::v8_bindings::NativePointerAction,
    boundaries: Vec<(
        AutomationRealmSnapshot,
        oryn_js::v8_bindings::NativePointerBoundary,
    )>,
    next: usize,
    phase: u8,
    boundary_target: Option<AutomationRealmSnapshot>,
    dispatch: Option<(
        AutomationRealmSnapshot,
        oryn_js::v8_bindings::NativePointerDispatch,
    )>,
    result: Option<(NodeId, bool)>,
    canceled: bool,
}
impl PointerDispatchRoute {
    pub(crate) fn retry_safe(&self) -> bool {
        !self.canceled
            && self.result.is_none()
            && self.boundaries.get(self.next).map_or_else(
                || {
                    self.dispatch
                        .as_ref()
                        .is_some_and(|(_, receipt)| receipt.retry_safe())
                },
                |(_, receipt)| receipt.retry_safe(),
            )
    }
    fn cancel(&mut self) {
        for (_, receipt) in &mut self.boundaries {
            receipt.cancel();
        }
        if let Some((_, receipt)) = &mut self.dispatch {
            receipt.cancel();
        }
        self.boundaries.clear();
        self.boundary_target = None;
        self.dispatch = None;
        self.canceled = true;
    }
}
impl Drop for PointerDispatchRoute {
    fn drop(&mut self) {
        if self.result.is_none() {
            self.cancel();
        }
    }
}

