fn populate_validation_states_for_root(
    dom: &DomRuntime,
    input: &mut oryn_layout::LayoutInput,
    root: NodeId,
) -> Result<(), DomError> {
    input.control_states.clear();
    input.temporal_pickers.clear();
    input.permission_prompts.clear();
    input.top_layer = dom
        .top_layer()
        .filter_map(|entry| {
            let node_id = (u64::from(entry.node.generation) << 32) | u64::from(entry.node.slot);
            input.nodes.iter().any(|node| node.id == node_id).then_some(
                oryn_common::v4::TopLayerEntry {
                    anchor_source: entry
                        .source
                        .map(|node| (u64::from(node.generation) << 32) | u64::from(node.slot)),
                    picker: (entry.kind == oryn_dom::TopLayerKind::SelectPicker).then(|| {
                        oryn_common::v4::SelectPickerState {
                            scroll: entry.picker_scroll,
                            active: entry.active_option.map(|node| {
                                (u64::from(node.generation) << 32) | u64::from(node.slot)
                            }),
                            reveal: entry.picker_reveal,
                        }
                    }),
                    node_id,
                    kind: match entry.kind {
                        oryn_dom::TopLayerKind::ModalDialog => {
                            oryn_common::v4::TopLayerKind::ModalDialog
                        }
                        oryn_dom::TopLayerKind::Popover => oryn_common::v4::TopLayerKind::Popover,
                        oryn_dom::TopLayerKind::SelectPicker => {
                            oryn_common::v4::TopLayerKind::SelectPicker
                        }
                        oryn_dom::TopLayerKind::TemporalPicker => {
                            oryn_common::v4::TopLayerKind::TemporalPicker
                        }
                        oryn_dom::TopLayerKind::PermissionPrompt => {
                            oryn_common::v4::TopLayerKind::PermissionPrompt
                        }
                        oryn_dom::TopLayerKind::Fullscreen => {
                            oryn_common::v4::TopLayerKind::Fullscreen
                        }
                    },
                },
            )
        })
        .collect();
    input.selector_states.clear();
    let hovered = dom.pointer_hover_snapshot(root)?;
    let target = dom.document_target(root)?;
    for node in &mut input.nodes {
        let id = NodeId {
            slot: node.id as u32,
            generation: (node.id >> 32) as u32,
        };
        let mut scope = id;
        let mut ancestry = std::collections::BTreeSet::new();
        while let Some(parent) = dom.parent(scope)? {
            if !ancestry.insert(scope) {
                return Err(DomError::Cycle);
            }
            scope = parent;
        }
        node.tree_scope = Some((u64::from(scope.generation) << 32) | u64::from(scope.slot));
        node.document_url = dom
            .arena()
            .get(root)?
            .document_metadata
            .as_ref()
            .and_then(|metadata| metadata.url.clone());
        input.selector_states.insert(
            node.id,
            oryn_layout::LayoutSelectorState {
                hovered: hovered.contains(&id),
                fullscreen: dom.is_fullscreen(id),
                media_state: dom.media_selector_state(id)?,
                interest_source: dom.element_interest_source(id)?,
                interest_target: dom.element_interest_target(id)?,
                interest_invoker: dom.interest_invoker_target(id)?.is_some(),
                inline_style_blocked: !dom.arena().get(id)?.style_attribute_policy_allowed,
                permission_granted: dom.element_permission_granted(id)?,
                user_validity: dom.element_user_validity(id)?,
                default_control: dom.element_default_state(id)?,
                in_range: dom.element_range_state(id)?,
                required: dom.element_required_state(id)?,
                defined: dom.element_defined(id)?,
                placeholder_shown: dom.element_placeholder_shown(id)?,
                read_write: dom.element_read_write(id)?,
                target: target == Some(id),
            },
        );
        if let Some(picker) = dom.temporal_picker_snapshot(id)? {
            input.temporal_pickers.insert(node.id, picker);
        }
        if let Some(prompt) = dom.permission_prompt_snapshot(id)? {
            input.permission_prompts.insert(node.id, prompt);
        }
        node.validity = dom.validation_selector_state(id)?;
        let disableable = node.namespace == "http://www.w3.org/1999/xhtml"
            && (matches!(
                node.tag.as_str(),
                "button" | "input" | "select" | "textarea" | "fieldset" | "optgroup" | "option"
            ) || dom.is_form_associated_custom_element(id));
        node.disabled = if disableable {
            Some(dom.control_disabled(id)?)
        } else {
            None
        };
        if node.namespace == "http://www.w3.org/1999/xhtml" && node.tag == "input" {
            node.checked = Some(dom.checked(id)?);
            node.indeterminate = dom.is_indeterminate(id)?;
        }
        if node.namespace == "http://www.w3.org/1999/xhtml" && node.tag == "option" {
            node.checked = Some(dom.option_selected(id)?);
        }
        let mut native = node.clone();
        if node.tag == "input"
            && node
                .attributes
                .get("type")
                .is_some_and(|kind| matches!(kind.to_ascii_lowercase().as_str(), "range" | "color"))
        {
            native
                .attributes
                .insert("value".into(), dom.control_value(id)?);
        }
        if let Some(mut control) = oryn_layout::control_paint_state(&native) {
            if let oryn_common::v4::PaintControl::Range { ticks, .. } = &mut control {
                *ticks = dom.range_datalist_fractions(id)?;
            }
            if let oryn_common::v4::PaintControl::Select {
                active_option,
                open,
                selected,
                label,
                display_size,
                ..
            } = &mut control
            {
                *active_option = dom
                    .select_picker_active(id)?
                    .map(|node| (u64::from(node.generation) << 32) | u64::from(node.slot));
                *open = dom.top_layer().any(|entry| {
                    entry.node == id && entry.kind == oryn_dom::TopLayerKind::SelectPicker
                });
                let options = dom.select_options(id)?;
                let chosen = options
                    .into_iter()
                    .filter(|option| dom.option_selected(*option).unwrap_or(false))
                    .collect::<Vec<_>>();
                *selected = chosen
                    .iter()
                    .map(|node| (u64::from(node.generation) << 32) | u64::from(node.slot))
                    .collect();
                *label = chosen
                    .first()
                    .map(|node| dom.option_label(*node))
                    .transpose()?
                    .unwrap_or_default();
                *display_size = dom.select_display_size(id)?;
            }
            input.control_states.insert(node.id, control);
        }
    }
    let pack = |id: NodeId| (u64::from(id.generation) << 32) | u64::from(id.slot);
    // Manual/default assignment is authoritative only in the live runtime.
    input.shadow_trees.assigned_slots.clear();
    for node in &input.nodes {
        let id = NodeId {
            slot: node.id as u32,
            generation: (node.id >> 32) as u32,
        };
        if let Some(slot) = dom.assigned_slot(id, false)? {
            input
                .shadow_trees
                .assigned_slots
                .insert(node.id, pack(slot));
        }
        for child in &dom.arena().get(id)?.children {
            if matches!(dom.arena().get(*child)?.kind, NodeKind::Text { .. })
                && let Some(slot) = dom.assigned_slot(*child, false)?
            {
                input
                    .shadow_trees
                    .assigned_slots
                    .insert(pack(*child), pack(slot));
            }
        }
    }
    let mut rendered = BTreeMap::new();
    for (id, _) in dom.flat_tree_elements(root)? {
        let mut content = Vec::new();
        let textarea = dom.is_element(id, "http://www.w3.org/1999/xhtml", "textarea");
        let input_control = dom.is_element(id, "http://www.w3.org/1999/xhtml", "input");
        let control_type = dom
            .attribute(id, "type")?
            .unwrap_or("text")
            .to_ascii_lowercase();
        let text_input = input_control && dom.is_editable_text_control(id);
        if textarea || text_input {
            let value = dom.control_edit_value(id)?;
            // A mask code unit for every source UTF-16 code unit keeps native
            // selection offsets stable while never exposing password plaintext.
            let text = if text_input && control_type == "password" {
                "•".repeat(value.encode_utf16().count())
            } else {
                value
            };
            content.push(oryn_layout::LayoutContent::Text {
                node_id: pack(id),
                text,
            });
            rendered.insert(pack(id), content);
            continue;
        }
        for child in dom.flat_tree_children(id)? {
            match &dom.arena().get(child)?.kind {
                NodeKind::Element { .. } => {
                    content.push(oryn_layout::LayoutContent::Element(pack(child)))
                }
                NodeKind::Text { data } => content.push(oryn_layout::LayoutContent::Text {
                    node_id: pack(child),
                    text: data.clone(),
                }),
                _ => {}
            }
        }
        rendered.insert(pack(id), content);
    }
    input.rendered_tree = Some(rendered);
    Ok(())
}

pub(crate) fn initial_layout_provider(
    dom: SharedDomRuntime,
    document: NodeId,
) -> Rc<dyn BindingLayoutProvider> {
    Rc::new(LiveLayoutProvider {
        style_lock: oryn_layout::cssom::new_native_style_lock(),
        retained_stylesheets: Rc::new(RefCell::new(RetainedStylesheets::default())),
        native_css_handles: Rc::new(RefCell::new(NativeCssHandleRegistry::default())),
        stylesheet_graph_revision: Cell::new(0),
        native_document_identity: Cell::new(None),
        shared_retained_admission: RefCell::new(None),
        native_retained_allocation: RefCell::new(None),
        retained_admission: RefCell::new(None),
        retained_cascade_key: RefCell::new(None),
        retained_cascade_key_charge: RefCell::new(None),
        retained_revision_key: RefCell::new(None),
        retained_revision_key_charge: RefCell::new(None),
        style_engine: RefCell::new(Default::default()),
        animation_time: Cell::new(0.),
        animation_revision: Cell::new(0),
        font_revision: Cell::new(0),
        layout_generation: Cell::new(0),
        layout_environment: RefCell::new(None),
        owner_thread: std::thread::current().id(),
        paint_inventory: RefCell::new(None),
        fonts: RefCell::new(Vec::new()),
        public_fonts:RefCell::new(Vec::new()),
        public_font_capacity:RefCell::new(None),
        implicit_font_backing:RefCell::new(None),
        dom,
        document,
        viewport: Cell::new(oryn_common::v4::ViewportState::default()),
        scrollbar_width: Cell::new(0.),
        native_media: Cell::new((false, false)),
    })
}

impl LiveLayoutProvider {
    fn sample_layout_with_style(
        &self,
        input: &oryn_layout::LayoutInput,
        limits: &oryn_layout::LayoutLimits,
    ) -> Result<
        (
            oryn_layout::LayoutOutput,
            oryn_layout::svg_instances::StyleSample,
        ),
        oryn_layout::LayoutError,
    > {
        self.sample_layout_with_style_controlled(input, limits, None)
    }

    fn sample_layout_with_style_controlled(
        &self,
        input: &oryn_layout::LayoutInput,
        limits: &oryn_layout::LayoutLimits,
        cancelled: Option<Arc<dyn Fn() -> bool + Send + Sync>>,
    ) -> Result<
        (
            oryn_layout::LayoutOutput,
            oryn_layout::svg_instances::StyleSample,
        ),
        oryn_layout::LayoutError,
    > {
        #[cfg(test)]
        if let Some(directory) = std::env::var_os("ORYN_DEEP_INPUT_DIRECTORY") {
            use std::io::Write;
            use std::sync::atomic::{AtomicUsize, Ordering};
            static CAPTURES: AtomicUsize = AtomicUsize::new(0);
            let sequence = CAPTURES.fetch_add(1, Ordering::Relaxed);
            if sequence < 8 {
                let directory = std::path::PathBuf::from(directory);
                assert!(
                    directory.is_absolute(),
                    "capture directory must be absolute"
                );
                let path = directory.join(format!("style-input-{sequence}.json"));
                let mut options = std::fs::OpenOptions::new();
                options.write(true).create_new(true);
                #[cfg(unix)]
                {
                    use std::os::unix::fs::OpenOptionsExt;
                    options
                        .mode(0o600)
                        .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC);
                }
                let mut file = options
                    .open(path)
                    .expect("fresh coordinator input artifact");
                serde_json::to_writer(&mut file, input).expect("exact native LayoutInput capture");
                file.write_all(b"\n").expect("input artifact completion");
                eprintln!(
                    "deep_style_input_capture sequence={sequence} nodes={} roots={} sheets={} rendered={} viewport={}x{}",
                    input.nodes.len(),
                    input.shadow_trees.roots.len(),
                    input.stylesheets.len(),
                    input.rendered_tree.is_some(),
                    input.viewport.width,
                    input.viewport.height
                );
            }
        }
        let _profile = crate::native_timing::stage("deep.live_style_compute");
        let mut engine = self.style_engine.borrow_mut();
        // Known iterative slot projection storage uses the same freshly
        // entered owning receipt as native retained allocations. Opaque Stylo
        // allocations remain governed by their existing separate contract.
        let slot_admission = self.shared_retained_admission.try_borrow()
            .map_err(|_| oryn_layout::LayoutError::StyleTraversal("slot admission borrow conflict".into()))?
            .clone();
        engine.set_slot_projection_admission(slot_admission);
        let active = engine.has_active_animations();
        let mut output = engine.compute_at_controlled(
            input,
            limits,
            self.animation_time.get() / 1000.,
            cancelled.clone(),
        )?;
        let sample = engine.instance_style_sample().ok_or_else(|| {
            oryn_layout::LayoutError::StyleTraversal(
                "successful layout lacks native style sample".into(),
            )
        })?;
        drop(engine);
        crate::svg_capture::publish_instance_fonts_with_sample(
            &self.dom.borrow(),
            input,
            limits,
            &mut output,
            Some(&sample),
        )?;
        if cancelled.as_ref().is_some_and(|check| check()) {
            return Err(oryn_layout::LayoutError::Cancelled);
        }
        if active {
            self.animation_revision
                .set(self.animation_revision.get().wrapping_add(1));
        }
        Ok((output, sample))
    }
    fn native_layout(
        &self,
        document: Option<NodeId>,
        custom_states: &BTreeMap<NodeId, BTreeSet<String>>,
        scroll: (f64, f64),
        element_scrolls: &BTreeMap<NodeId, (f64, f64)>,
    ) -> Result<oryn_layout::LayoutOutput, String> {
        self.native_layout_with_input(document, custom_states, scroll, element_scrolls)
            .map(|(_, output, _)| output)
    }
    fn native_layout_with_input(
        &self,
        document: Option<NodeId>,
        custom_states: &BTreeMap<NodeId, BTreeSet<String>>,
        scroll: (f64, f64),
        element_scrolls: &BTreeMap<NodeId, (f64, f64)>,
    ) -> Result<(PublicFontProjection,oryn_layout::LayoutOutput,oryn_layout::svg_instances::StyleSample),String> {
        let input=self.capture_layout_input(document,custom_states,scroll,element_scrolls)?;
        // Geometry is an optional capability and must never be able to tear
        // down the page worker. Stylo/Blitz can reject a transient DOM shape
        // while parser re-entry is replacing nested documents; translate an
        // upstream panic into the same explicit unavailable result as a
        // normal layout error.
        let (output,sample)=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{
            self.sample_layout_with_style(&input.input,&oryn_layout::LayoutLimits::default())
        })).map_err(|_|"synchronous layout flush panicked on a transient DOM shape".to_owned())?
            .map_err(|error|format!("synchronous layout flush failed: {error}"))?;
        Ok((input,output,sample))
    }
    fn capture_layout_input(
        &self,
        document: Option<NodeId>,
        custom_states: &BTreeMap<NodeId, BTreeSet<String>>,
        scroll: (f64, f64),
        element_scrolls: &BTreeMap<NodeId, (f64, f64)>,
    ) -> Result<PublicFontProjection,String> {
        let _profile = crate::native_timing::stage("deep.live_binding_layout");
        let document = document.unwrap_or(self.document);
        let mut input = {
            let dom = self.dom.borrow();
            crate::runtime::layout_input_from_dom(
                dom.arena(),
                document,
                self.viewport.get(),
                oryn_common::v4::ScrollState {
                    x: scroll.0,
                    y: scroll.1,
                    ..Default::default()
                },
                if self.native_media.get().0 {
                    oryn_common::v4::PreferredColorScheme::Dark
                } else {
                    oryn_common::v4::PreferredColorScheme::Light
                },
                if self.native_media.get().1 {
                    oryn_common::v4::ReducedMotion::Reduce
                } else {
                    oryn_common::v4::ReducedMotion::NoPreference
                },
                &[],
            )
        };
        {
            let dom = self.dom.borrow();
            let mut fonts = self.fonts.borrow_mut();
            fonts.retain(|(document, owner, revision, _, _, epoch)| {
                dom.node_document(*owner).ok().flatten() == Some(*document)
                    && dom.is_connected(*owner).unwrap_or(false)
                    && dom.arena().stylesheet_revision(*owner).ok() == Some(*revision)
                    && epoch.as_ref().is_none_or(dynamic_stylesheet_preparation::RetainedFontDemandEpoch::current)
            });
            let order = dom
                .arena()
                .descendants_inclusive(document)
                .map_err(|error| error.to_string())?
                .into_iter()
                .enumerate()
                .map(|(position, node)| (node, position))
                .collect::<BTreeMap<_, _>>();
            fonts.sort_by_key(|(_, owner, _, font, _, _)| {
                (order.get(owner).copied().unwrap_or(usize::MAX), font.order)
            });
            for (owner_document, owner, _, font, _, _) in fonts.iter() {
                if *owner_document != document
                    || dom
                        .arena()
                        .stylesheet_disabled(*owner)
                        .map_err(|error| error.to_string())?
                {
                    continue;
                }
                let media = dom
                    .arena()
                    .stylesheet_media(*owner)
                    .map_err(|error| error.to_string())?;
                if self.native_media_matches(&media, &input.document_base_url, false)? {
                    input.web_fonts.push(font.clone());
                }
            }
        }
        input.scrollbar_width = self.scrollbar_width.get();
        input.element_scrolls = element_scrolls
            .iter()
            .map(|(node, offset)| {
                (
                    ((u64::from(node.generation) << 32) | u64::from(node.slot)),
                    *offset,
                )
            })
            .collect();
        input.focused_node = self
            .dom
            .borrow()
            .focused()
            .map(|node| (u64::from(node.generation) << 32) | u64::from(node.slot));
        input.focus_visible = self.dom.borrow().focus_visible();
        populate_validation_states_for_root(&self.dom.borrow(), &mut input, document)
            .map_err(|error| error.to_string())?;
        {
            let dom = self.dom.borrow();
            for node in &mut input.nodes {
                let id = NodeId {
                    slot: node.id as u32,
                    generation: (node.id >> 32) as u32,
                };
                node.indeterminate = dom
                    .is_indeterminate(id)
                    .map_err(|error| error.to_string())?;
            }
        }
        input.custom_states = custom_states
            .iter()
            .map(|(node, values)| {
                (
                    (u64::from(node.generation) << 32) | u64::from(node.slot),
                    values.clone(),
                )
            })
            .collect();
        let admission = self
            .retained_admission
            .try_borrow()
            .map_err(|_| "retained layout admission borrow conflict")?
            .as_ref()
            .cloned();
        if let Some(admission) = admission
            && let Some(identity) = self.native_document_identity.get()
        {
            self.synchronize_retained_graph_revision()?;
            match self.synchronize_retained_cascade(&input, identity, admission.as_ref())? {
                RetainedCascadeSync::Ready => {}
                RetainedCascadeSync::Retry => {
                    return Err("retained cascade changed; recapture layout input".into());
                }
            }
        }
        let allocation=self.append_public_font_projection(&mut input,document)?;
        Ok(PublicFontProjection{input,_allocation:allocation})
    }
}
