pub(crate) type CssDependencies = Vec<(String, String, String, String)>;
pub(crate) struct CssDependencyBatch {
    pub node: NodeId,
    pub revision: u64,
    pub epoch: u64,
    pub dependencies: CssDependencies,
    pub _allocation: Option<Arc<dyn Send + Sync>>,
    pub _bytes: ScriptSourceReservation,
}
type StylesheetSource = (String, String, CssDependencies);
fn stylesheet_source_bytes(source: &StylesheetSource) -> usize {
    source.2.iter().fold(
        source.0.len().saturating_add(source.1.len()),
        |bytes, (base, initiator, policy, css)| {
            bytes
                .saturating_add(base.len())
                .saturating_add(initiator.len())
                .saturating_add(policy.len())
                .saturating_add(css.len())
        },
    )
}
fn collect_css_dependencies(
    dependencies: &mut CssDependencies,
    base: &str,
    initiator: &str,
    policy: &str,
    css: &str,
) -> Result<(), HostError> {
    if oryn_layout::cssom::resource_references(css)
        .iter()
        .all(|reference| reference.url.starts_with('#'))
        && !oryn_layout::cssom::stylesheet_has_font_sources(css, base)
            .map_err(HostError::Execution)?
    {
        return Ok(());
    }
    let size = dependencies.iter().fold(
        css.len()
            .saturating_add(base.len())
            .saturating_add(initiator.len())
            .saturating_add(policy.len()),
        |bytes, (base, initiator, policy, css)| {
            bytes
                .saturating_add(base.len())
                .saturating_add(initiator.len())
                .saturating_add(policy.len())
                .saturating_add(css.len())
        },
    );
    if dependencies.len() >= 256 || size > MAX_QUEUED_SCRIPT_SOURCE_BYTES {
        return Err(HostError::LimitExceeded {
            resource: "stylesheet dependency metadata".into(),
        });
    }
    dependencies.push((base.into(), initiator.into(), policy.into(), css.into()));
    Ok(())
}
