impl FrameNavigationContext {
    fn saved_request_state(
        &self,
    ) -> Option<oryn_common::navigation_request::NavigationRequestState> {
        let session = self.session.as_ref()?;
        let destination = self.destination.as_ref().or_else(|| {
            self.reload
                .then(|| session.update.entries.get(session.update.current))
                .flatten()
        })?;
        if !self.reload
            && !session
                .update
                .entries
                .iter()
                .any(|entry| entry.id == destination.id)
        {
            return None;
        }
        session
            .requests
            .get(&destination.document_id)?
            .request_state
            .clone()
    }
    fn fetch_navigation_flags(&self) -> oryn_js::platform::NavigationRequestFlags {
        oryn_js::platform::NavigationRequestFlags {
            reload: self.reload,
            history: !self.reload
                && self.destination.as_ref().is_some_and(|destination| {
                    self.history.as_ref().is_some_and(|history| {
                        history
                            .entries
                            .iter()
                            .any(|entry| entry.id == destination.id)
                    })
                }),
        }
    }
}

// Recovery slots are empty while the unique host executes. They are never
// borrowed by callbacks and do not permit concurrent access to the isolate.
struct ConstructionHost<'a> {
    host: Option<RawV8Host>,
    recovery: Option<&'a mut Option<RawV8Host>>,
}
impl ConstructionHost<'_> {
    fn restore_owned_host(&mut self, host: RawV8Host) {
        self.host = Some(host);
    }
}
impl std::ops::Deref for ConstructionHost<'_> {
    type Target = RawV8Host;
    fn deref(&self) -> &RawV8Host {
        self.host.as_ref().expect("construction host")
    }
}
impl std::ops::DerefMut for ConstructionHost<'_> {
    fn deref_mut(&mut self) -> &mut RawV8Host {
        self.host.as_mut().expect("construction host")
    }
}
impl Drop for ConstructionHost<'_> {
    fn drop(&mut self) {
        if let Some(slot) = self.recovery.as_deref_mut() {
            *slot = self.host.take();
        }
    }
}
// The retained page/parser assembly frame starts only after the V8 host
// has finished initial realm compilation; it must not burden that stack.
#[inline(never)]
fn finish_document_construction<T>(finish: impl FnOnce() -> T) -> T {
    finish()
}
struct ConstructionPage<'a> {
    page: Option<Box<RustExecutableDocument>>,
    recovery: Option<&'a mut Option<RawV8Host>>,
}
impl ConstructionPage<'_> {
    fn finish(mut self) -> RustExecutableDocument {
        self.recovery.take();
        *self.page.take().expect("constructed page")
    }
}
impl std::ops::Deref for ConstructionPage<'_> {
    type Target = RustExecutableDocument;
    fn deref(&self) -> &RustExecutableDocument {
        self.page.as_ref().expect("constructed page")
    }
}
impl std::ops::DerefMut for ConstructionPage<'_> {
    fn deref_mut(&mut self) -> &mut RustExecutableDocument {
        self.page.as_mut().expect("constructed page")
    }
}
impl Drop for ConstructionPage<'_> {
    fn drop(&mut self) {
        if let (Some(slot), Some(page)) = (self.recovery.as_deref_mut(), self.page.as_mut()) {
            *slot = page.take_agent_host().ok();
        }
    }
}

