    pub fn admit_native_navigation(
        &mut self,
        url: &str,
        replace: bool,
        reload: bool,
    ) -> Result<oryn_js::navigation_api::NativeNavigationAdmission, HostError> {
        self.agent.host.activate_realm(self.top_realm)?;
        let admission =
            self.agent
                .host
                .admit_native_navigation(url, replace, reload, Default::default())?;
        self.checkpoint()?;
        // Keep the already-produced admission; do not enter another host operation.
        if self.terminal_retired() {
            return Ok(admission);
        }
        if let oryn_js::navigation_api::NativeNavigationAdmission::Proceed {
            operation: Some(operation),
            ..
        } = &admission
        {
            self.agent.host.activate_realm(self.top_realm)?;
            if !self.agent.host.native_navigation_matches(operation) {
                return Ok(oryn_js::navigation_api::NativeNavigationAdmission::Handled);
            }
        }
        Ok(admission)
    }

