    pub(crate) fn current_automation_scope(&self) -> Option<AutomationRealmSnapshot> {
        self.automation_scope.clone()
    }
    pub(crate) fn set_automation_scope(
        &mut self,
        scope: Option<AutomationRealmSnapshot>,
    ) -> Result<(), HostError> {
        if let Some(selected) = &scope {
            self.validate_automation_scope(selected)?;
        }
        self.automation_scope = scope;
        {
            let realm = self.automation_realm();
            self.agent.host.activate_realm(realm)
        }
    }
    fn validate_automation_scope(
        &self,
        selected: &AutomationRealmSnapshot,
    ) -> Result<(), HostError> {
        if self
            .automation_realms()
            .iter()
            .any(|entry| entry.same_document_as(selected))
        {
            Ok(())
        } else {
            Err(HostError::Execution(
                "selected frame document retired".into(),
            ))
        }
    }
    fn activate_selected_script_realm(&mut self) -> Result<(), HostError> {
        // Parser and related-root turns share the host. Its last active realm
        // is not authority to select the recipient of a new page command.
        if let Some(selected) = &self.automation_scope {
            self.validate_automation_scope(selected)?;
        }
        let realm = self.automation_realm();
        self.agent.host.activate_realm(realm)
    }

    fn automation_realm(&self) -> RealmId {
        self.automation_scope
            .as_ref()
            .map(|entry| entry.realm)
            .unwrap_or(self.top_realm)
    }
    fn selected_dom(&self) -> Result<SharedDomRuntime, HostError> {
        if let Some(scope) = &self.automation_scope {
            self.validate_automation_scope(scope)?;
        }
        self.agent
            .host
            .automation_dom(self.automation_realm())
            .ok_or_else(|| HostError::Execution("selected DOM retired".into()))
    }
    pub(crate) fn semantic_snapshot(&self) -> Result<ParsedDocument, HostError> {
        let owner = self.page_terminal_control.clone();
        let mut checkpoint = || {
            if crate::page_terminal_control::retired(owner.as_deref()) {
                Err(oryn_dom::DomError::ProjectionCancelled)
            } else {
                Ok(())
            }
        };
        checkpoint().map_err(|error| HostError::Execution(error.to_string()))?;
        let Some(scope) = &self.automation_scope else {
            // Native navigation admission can run author handlers without a
            // full executable checkpoint. Pair the mutation journal and live
            // control projection with the current arena, not the last cached
            // checkpoint (whose nodes may already have been removed).
            let selected_dom = self.selected_dom()?;
            let selected_dom = selected_dom.borrow();
            let document = selected_dom.document();
            let dom = selected_dom
                .arena()
                .snapshot_live_document_tree_with_checkpoint(document, &mut checkpoint)
                .map_err(|error| HostError::Execution(error.to_string()))?;
            return Ok(ParsedDocument {
                dom,
                document,
                errors: self.document.errors.clone(),
                quirks_mode: self.document.quirks_mode,
                events: self.document.events.clone(),
            });
        };
        self.validate_automation_scope(scope)?;
        let dom = self.selected_dom()?;
        let dom = dom
            .borrow()
            .arena()
            .snapshot_document_scope_with_checkpoint(scope.document_root, &mut checkpoint)
            .map_err(|error| HostError::Execution(error.to_string()))?;
        Ok(ParsedDocument {
            dom,
            document: scope.document_root,
            errors: Vec::new(),
            quirks_mode: self.document.quirks_mode,
            events: Vec::new(),
        })
    }

    pub fn focus_automation_window(
        &mut self,
        selected: &AutomationRealmSnapshot,
    ) -> Result<(), HostError> {
        self.validate_automation_scope(selected)?;
        self.agent.host.focus_automation_window(selected.realm)?;
        self.validate_automation_scope(selected)
    }
    pub fn navigate_service_window(
        &mut self,
        selected: &AutomationRealmSnapshot,
        url: String,
        authority: oryn_js::navigation::ServiceNavigationAdmission,
    ) -> Result<(), HostError> {
        self.validate_automation_scope(selected)?;
        #[cfg(unix)]
        if let Some((client, page_id, _)) = &self.context {
            let target = authority.target.clone();
            let response = client
                .request(
                    crate::context_service::ContextServiceRequest::ServiceNavigationToScript {
                        page_id: *page_id,
                        admission: authority,
                        url: url.clone(),
                    },
                )
                .map_err(|error| HostError::Execution(error.to_string()))?;
            let crate::context_service::ContextServiceResponse::ScriptNavigationAuthority {
                authority,
            } = response
            else {
                return Err(HostError::Execution(
                    "invalid service navigation conversion".into(),
                ));
            };
            return self.navigate_related_window(
                selected,
                url,
                false,
                oryn_js::navigation::ScriptNavigationAdmission { authority, target },
                None,
            );
        }
        Err(HostError::Execution(
            "service Window navigation requires native parent".into(),
        ))
    }

    pub fn navigate_related_window(
        &mut self,
        selected: &AutomationRealmSnapshot,
        url: String,
        replace: bool,
        authority: oryn_js::navigation::ScriptNavigationAdmission,
        execution_observer: Option<oryn_js::navigation::NavigationExecutionObserver>,
    ) -> Result<(), HostError> {
        self.navigate_related_window_with_involvement(
            selected,
            url,
            replace,
            authority,
            false,
            execution_observer,
        )
    }

    pub fn navigate_document_window(
        &mut self,
        selected: &AutomationRealmSnapshot,
        url: String,
        source: oryn_dom::DocumentProvenance,
        referrer_policy: Option<String>,
        user_initiated: bool,
        execution_observer: Option<oryn_js::navigation::NavigationExecutionObserver>,
    ) -> Result<(), HostError> {
        self.validate_automation_scope(selected)?;
        let target = self.agent.host.native_creator_for_realm(selected.realm)?;
        #[cfg(unix)]
        if let Some((client, page_id, _)) = &self.context {
            let response=client.request(crate::context_service::ContextServiceRequest::IssueDocumentScriptNavigationAuthority{page_id:*page_id,source,target:target.clone(),url:url.clone(),referrer_policy})
                .map_err(|error|HostError::Execution(error.to_string()))?;
            let crate::context_service::ContextServiceResponse::ScriptNavigationAuthority {
                authority,
            } = response
            else {
                return Err(HostError::Execution(
                    "invalid selected document authority response".into(),
                ));
            };
            return self.navigate_related_window_with_involvement(
                selected,
                url,
                false,
                oryn_js::navigation::ScriptNavigationAdmission { authority, target },
                user_initiated,
                execution_observer,
            );
        }
        Err(HostError::Execution(
            "selected document navigation requires parent authority".into(),
        ))
    }

    fn navigate_related_window_with_involvement(
        &mut self,
        selected: &AutomationRealmSnapshot,
        url: String,
        replace: bool,
        authority: oryn_js::navigation::ScriptNavigationAdmission,
        user_initiated: bool,
        execution_observer: Option<oryn_js::navigation::NavigationExecutionObserver>,
    ) -> Result<(), HostError> {
        self.validate_automation_scope(selected).map_err(|error| {
            HostError::Execution(format!("related navigation target snapshot: {error}"))
        })?;
        if self
            .agent
            .host
            .native_creator_for_realm(selected.realm)
            .map_err(|error| {
                HostError::Execution(format!(
                    "related navigation creator for realm {:?}: {error}",
                    selected.realm
                ))
            })?
            != authority.target
        {
            return Err(HostError::Execution(
                "remote navigation target retired".into(),
            ));
        }
        let mut navigation_source = oryn_js::navigation_api::NativeNavigationSource {
            execution_observer: execution_observer.clone(),
            user_initiated,
            ..Default::default()
        };
        #[cfg(unix)]
        if let Some((client, page_id, _)) = &self.context {
            match client
                .request(
                    crate::context_service::ContextServiceRequest::ReadScriptNavigationSource {
                        page_id: *page_id,
                        target: authority.target.clone(),
                        url: url.clone(),
                        authority: authority.authority.clone(),
                    },
                )
                .map_err(|error| HostError::Execution(error.to_string()))?
            {
                crate::context_service::ContextServiceResponse::ScriptNavigationSource {
                    source,
                } => {
                    navigation_source.source_origin_key = Some(source.origin_key);
                    navigation_source.source_domain_key = source.source_domain_key;
                }
                _ => {
                    return Err(HostError::Execution(
                        "remote source authority denied".into(),
                    ));
                }
            }
        } else {
            return Err(HostError::Execution(
                "remote navigation requires parent authority".into(),
            ));
        }
        self.agent.host.activate_realm(selected.realm)?;
        let result = (|| {
            let admission = self
                .agent
                .host
                .admit_native_navigation(&url, replace, false, navigation_source)
                .map_err(|error| {
                    HostError::Execution(format!(
                        "related navigation event admission for realm {:?}: {error}",
                        selected.realm
                    ))
                })?;
            let oryn_js::navigation_api::NativeNavigationAdmission::Proceed {
                operation,
                destination,
            } = admission
            else {
                return Ok(());
            };
            if let Some(observer) = &execution_observer {
                observer.loader_owned();
            }
            self.agent
                .host
                .schedule_navigation(oryn_js::v8_bindings::LocationNavigation {
                    execution_observer: execution_observer.clone(),
                    navigation_operation: operation,
                    navigation_destination: destination.map(|entry| *entry),
                    script_authority: Some(authority),
                    form_authority: None,
                    url,
                    replace,
                    reload: false,
                    post: None,
                    referrer_policy: None,
                    download: None,
                })
        })();
        let restored = self.agent.host.activate_realm(self.top_realm);
        let result = result.and(restored);
        if let (Err(error), Some(observer)) = (&result, &execution_observer) {
            observer.complete(oryn_js::navigation::NavigationExecutionOutcome::Failed {
                message: error.to_string(),
            });
        }
        result
    }

    pub fn navigate_automation_frame(
        &mut self,
        selected: &AutomationRealmSnapshot,
        url: String,
        initiator_url: String,
        referrer_policy: String,
    ) -> Result<(), HostError> {
        self.navigate_automation_frame_resource(
            selected,
            url,
            Some(initiator_url),
            Some(referrer_policy),
            None,
            None,
        )
    }
    pub fn navigate_automation_frame_resource(
        &mut self,
        selected: &AutomationRealmSnapshot,
        url: String,
        initiator_url: Option<String>,
        referrer_policy: Option<String>,
        post: Option<oryn_js::navigation::PostResource>,
        authority: Option<oryn_js::navigation::FormNavigationAuthority>,
    ) -> Result<(), HostError> {
        self.validate_automation_scope(selected)?;
        if !self.dispatch_frame_before_unload(selected.realm)? {
            return Err(HostError::Execution(
                "frame navigation cancelled by beforeunload".into(),
            ));
        }
        self.validate_automation_scope(selected)?;
        let owner = self.frame_realms.get(&selected.realm).ok_or_else(|| {
            HostError::Execution("root navigation uses native page navigation".into())
        })?;
        let (parent, frame) = (owner.parent_realm, owner.frame);
        let target = Url::parse(&url).map_err(|error| HostError::Execution(error.to_string()))?;
        if !matches!(target.scheme(), "http" | "https") {
            return Err(HostError::Execution(
                "service client navigation requires HTTP(S)".into(),
            ));
        }
        self.agent.host.activate_realm(parent)?;
        let dom = self
            .agent
            .host
            .active_dom()
            .ok_or_else(|| HostError::Execution("frame navigation parent retired".into()))?;
        {
            let mut dom = dom.borrow_mut();
            dom.remove_attribute(frame, "srcdoc")
                .map_err(|error| HostError::Execution(error.to_string()))?;
            {
                let attribute = dom
                    .embedded_content_kind(frame)
                    .map_or("src", |kind| kind.source_attribute());
                dom.set_attribute(frame, attribute, &url)
            }
            .map_err(|error| HostError::Execution(error.to_string()))?;
        }
        self.pending_frame_navigations.insert(
            (parent, frame),
            FrameNavigationContext {
                execution_observer: None,
                download: None,
                session: None,
                archived_source: None,
                destination: None,
                history: None,
                replace: false,
                reload: false,
                script_authority: None,
                form_authority: authority,
                initiator_url,
                referrer_policy,
                post,
            },
        );
        self.agent.host.reschedule_dynamic_frame(frame)?;
        self.agent.host.activate_realm(self.top_realm)?;
        Ok(())
    }

    pub fn named_navigation_inventory(
        &self,
    ) -> Result<Vec<(String, AutomationRealmSnapshot)>, HostError> {
        let inventory = self.automation_realms();
        let mut result = Vec::new();
        let mut pending = vec![self.top_realm];
        let mut seen = BTreeSet::new();
        let mut bytes = 0usize;
        while let Some(realm) = pending.pop() {
            if !seen.insert(realm) {
                continue;
            }
            let Some(snapshot) = inventory
                .iter()
                .find(|entry| entry.realm == realm && entry.live)
            else {
                continue;
            };
            let name = self
                .agent
                .host
                .native_window_target_name(realm)
                .unwrap_or_default();
            bytes = bytes
                .saturating_add(name.len())
                .saturating_add(snapshot.url.len())
                .saturating_add(snapshot.frame_token.as_ref().map_or(0, String::len))
                .saturating_add(256);
            if bytes > 1024 * 1024 {
                return Err(HostError::LimitExceeded {
                    resource: "native named target inventory".into(),
                });
            }
            result.push((name, snapshot.clone()));
            let children = self
                .agent
                .host
                .automation_frame_order(realm)?
                .into_iter()
                .filter_map(|frame| {
                    inventory
                        .iter()
                        .find(|entry| {
                            entry.live
                                && entry.parent_realm == Some(realm)
                                && entry.frame == Some(frame)
                        })
                        .map(|entry| entry.realm)
                })
                .collect::<Vec<_>>();
            pending.extend(children.into_iter().rev());
        }
        Ok(result)
    }

    pub fn automation_realms(&self) -> Vec<AutomationRealmSnapshot> {
        std::iter::once(self.top_realm)
            .chain(self.frame_realms.keys().copied())
            .filter_map(|realm| {
                let (root, generation, epoch, live) =
                    self.agent.host.automation_realm_identity(realm)?;
                let frame = self.frame_realms.get(&realm);
                Some(AutomationRealmSnapshot {
                    realm,
                    parent_realm: frame.map(|entry| entry.parent_realm),
                    frame: frame.map(|entry| entry.frame),
                    frame_token: frame.and_then(|entry| {
                        self.agent
                            .host
                            .automation_frame_token(entry.parent_realm, entry.frame)
                    }),
                    frame_generation: frame.and_then(|entry| {
                        self.agent
                            .host
                            .automation_frame_generation(entry.parent_realm, entry.frame)
                    }),
                    document_root: root,
                    document_generation: generation,
                    stream_epoch: epoch,
                    document_authority_epoch: self.agent.host.document_authority_epoch(realm)?,
                    url: self
                        .agent
                        .host
                        .automation_document_url(realm)
                        .unwrap_or_else(|| {
                            frame
                                .map(|entry| entry.committed_url.clone())
                                .unwrap_or_else(|| {
                                    self.base_url
                                        .as_ref()
                                        .map(Url::to_string)
                                        .unwrap_or_default()
                                })
                        }),
                    live: live
                        && frame.is_none_or(|entry| {
                            self.agent.host.automation_frame_child_live(
                                entry.parent_realm,
                                entry.frame,
                                realm,
                            )
                        }),
                })
            })
            .collect()
    }

    pub fn webdriver_element_command(
        &mut self,
        current: Option<&AutomationRealmSnapshot>,
        command: crate::host::webdriver_script::ElementCommand,
    ) -> Result<
        crate::host::webdriver_script::ScriptValue,
        crate::host::webdriver_script::ScriptError,
    > {
        use crate::host::webdriver_script::ScriptError;
        let inventory = self.automation_realms();
        let selected = match current {
            Some(current) => inventory
                .iter()
                .find(|entry| entry.same_document_as(current)),
            None => inventory
                .iter()
                .find(|entry| entry.live && entry.parent_realm.is_none()),
        }
        .ok_or_else(|| ScriptError {
            code: "no such frame".into(),
            message: "selected automation document retired".into(),
        })?;
        let realm = selected.realm;
        let result = self.agent.host.webdriver_element_command(realm, command);
        let restored = self
            .agent
            .host
            .activate_realm(self.top_realm)
            .map_err(ScriptError::from);
        match result {
            Ok(value) => {
                restored?;
                Ok(value)
            }
            Err(error) => Err(error),
        }
    }

    pub fn select_webdriver_frame(
        &self,
        current: &AutomationRealmSnapshot,
        target: crate::host::webdriver_script::WebDriverFrameTarget,
    ) -> Result<AutomationRealmSnapshot, crate::host::webdriver_script::ScriptError> {
        use crate::host::webdriver_script::{ScriptError, WebDriverFrameTarget};
        let inventory = self.automation_realms();
        let failure = || ScriptError {
            code: "no such frame".into(),
            message: "selected frame is missing or retired".into(),
        };
        // Switching to the top-level context is the recovery operation after a
        // selected child was detached; it only requires a live top document.
        if matches!(target, WebDriverFrameTarget::Top) {
            return inventory
                .into_iter()
                .find(|entry| entry.parent_realm.is_none() && entry.live)
                .ok_or_else(failure);
        }
        let selected = inventory
            .iter()
            .find(|entry| entry.same_document_as(current))
            .ok_or_else(failure)?;
        if matches!(target, WebDriverFrameTarget::Parent) {
            let parent = selected.parent_realm.unwrap_or(selected.realm);
            return inventory
                .iter()
                .find(|entry| entry.realm == parent && entry.live)
                .cloned()
                .ok_or_else(failure);
        }
        let frame = match target {
            WebDriverFrameTarget::ElementNode(node) => {
                if !self.agent.host.automation_frame_live(selected.realm, node) {
                    return Err(failure());
                }
                node
            }
            WebDriverFrameTarget::ElementReference(reference) => self
                .agent
                .host
                .webdriver_frame_element(selected.realm, &reference)?,
            WebDriverFrameTarget::Index(index) => {
                if index > u16::MAX as u32 {
                    return Err(ScriptError::invalid("frame index exceeds 65535"));
                }
                let order = self.agent.host.automation_frame_order(selected.realm)?;
                order
                    .into_iter()
                    .filter(|frame| {
                        inventory.iter().any(|entry| {
                            entry.parent_realm == Some(selected.realm)
                                && entry.frame == Some(*frame)
                                && entry.live
                        })
                    })
                    .nth(index as usize)
                    .ok_or_else(failure)?
            }
            _ => unreachable!(),
        };
        inventory
            .iter()
            .find(|entry| {
                entry.parent_realm == Some(selected.realm)
                    && entry.frame == Some(frame)
                    && entry.live
            })
            .cloned()
            .ok_or_else(failure)
    }

    pub fn set_webdriver_window_handles(
        &mut self,
        bindings: Vec<crate::host::webdriver_script::WindowHandleBinding>,
    ) -> Result<(), crate::host::webdriver_script::ScriptError> {
        use crate::host::webdriver_script::ScriptError;
        if bindings.len() > 4096 {
            return Err(ScriptError::invalid("window handle limit"));
        }
        let inventory = self.automation_realms();
        let mut live_bindings = Vec::with_capacity(bindings.len());
        for binding in bindings {
            if inventory.iter().any(|entry| {
                entry.live
                    && entry.realm == binding.realm
                    && entry.document_generation == binding.document_generation
                    && entry.stream_epoch == binding.stream_epoch
                    && entry.parent_realm.is_none() == binding.top_level
            }) {
                live_bindings.push(binding);
            } else if binding.top_level {
                return Err(ScriptError::retired());
            }
            // Inventory and execution are separate actor turns. A retired
            // incidental frame must not reject a script in its live parent.
            // Omit its handle; selected frames and actual reference arguments
            // still undergo their own document-lifetime checks at execution.
        }
        self.agent.host.set_webdriver_window_handles(live_bindings)
    }

    pub fn begin_webdriver_script(
        &mut self,
        request: crate::host::webdriver_script::ScriptRequest,
    ) -> Result<crate::host::webdriver_script::ScriptId, crate::host::webdriver_script::ScriptError>
    {
        self.begin_webdriver_script_in_realm(self.top_realm, request)
    }

