    /// Input has its own native membership: a live initial Document may be
    /// interactive before its resource has an executable loader owner. Keep
    /// generic automation selection and its exact committed-document fence.
    fn pointer_realms(&self) -> Vec<AutomationRealmSnapshot> {
        let installed = self
            .automation_realms()
            .into_iter()
            .filter(|entry| entry.live)
            .map(|entry| (entry.realm, entry))
            .collect::<BTreeMap<_, _>>();
        let Some(root) = installed
            .get(&self.top_realm)
            .filter(|entry| entry.parent_realm.is_none())
        else {
            return Vec::new();
        };
        let candidates = self
            .agent
            .host
            .native_pointer_frame_snapshots(self.top_realm)
            .into_iter()
            .filter(|(entry, initial)| {
                *initial
                    || installed
                        .get(&entry.realm)
                        .is_some_and(|owner| owner.same_document_as(entry))
            })
            .map(|(entry, _)| (entry.realm, entry))
            .collect::<BTreeMap<_, _>>();
        let mut result = vec![root.clone()];
        for entry in candidates.values() {
            let mut current = entry;
            let mut seen = BTreeSet::new();
            while seen.len() < 32 && seen.insert(current.realm) {
                match current.parent_realm {
                    Some(parent) if parent == root.realm => {
                        result.push(entry.clone());
                        break;
                    }
                    Some(parent) => match candidates.get(&parent) {
                        Some(ancestor) => current = ancestor,
                        None => break,
                    },
                    None => break,
                }
            }
        }
        result
    }

    fn validate_pointer_context(
        &self,
        selected: &AutomationRealmSnapshot,
    ) -> Result<(), crate::host::webdriver_script::ScriptError> {
        if self
            .pointer_realms()
            .iter()
            .any(|entry| entry.same_document_as(selected))
        {
            Ok(())
        } else {
            Err(crate::host::webdriver_script::ScriptError {
                code: "no such frame".into(),
                message: "selected input document changed".into(),
            })
        }
    }

    fn pointer_hit_matches(
        entry: &AutomationRealmSnapshot,
        hit: &oryn_js::v8_bindings::NativeFramePointerTarget,
    ) -> bool {
        entry.frame == Some(hit.frame)
            && entry.realm == hit.identity.realm
            && entry.document_root == hit.identity.document
            && entry.document_generation == hit.identity.generation
            && entry.stream_epoch == hit.identity.stream_epoch
            && entry.document_authority_epoch == hit.identity.authority_epoch
    }

    fn pointer_frame_mismatch(
        &self,
        parent: &AutomationRealmSnapshot,
        hit: &oryn_js::v8_bindings::NativeFramePointerTarget,
    ) -> crate::host::webdriver_script::ScriptError {
        let installed = self
            .automation_realms()
            .iter()
            .filter(|entry| {
                entry.parent_realm == Some(parent.realm) && entry.frame == Some(hit.frame)
            })
            .count();
        let initial = self
            .agent
            .host
            .native_pointer_frame_diagnostic(parent.realm, hit.frame);
        crate::host::webdriver_script::ScriptError {
            code: "no such frame".into(),
            message: format!(
                "pointer frame document changed: parent={} frame={:?} hit={:?} installed={} resources={} ready={} {initial}",
                parent.realm.0,
                hit.frame,
                hit.identity,
                installed,
                self.frame_resource_preparations
                    .contains_key(&(parent.realm, hit.frame)),
                self.ready_frame_jobs.len(),
            ),
        }
    }

    fn webdriver_pointer_context(
        &mut self,
        selected: &AutomationRealmSnapshot,
        id: Option<i32>,
        mut x: f64,
        mut y: f64,
        mut movement_x: f64,
        mut movement_y: f64,
    ) -> Result<
        (AutomationRealmSnapshot, f64, f64, f64, f64),
        crate::host::webdriver_script::ScriptError,
    > {
        self.validate_pointer_context(selected)?;
        if let Some(id) = id {
            let inventory = self.pointer_realms();
            let mut best: Option<Vec<AutomationRealmSnapshot>> = None;
            for target in inventory.iter().filter(|entry| {
                entry.live
                    && self
                        .agent
                        .host
                        .automation_pointer_owns_routing(entry.realm, id)
            }) {
                let mut path = Vec::new();
                let mut current = target;
                let mut seen = BTreeSet::new();
                let mut valid = true;
                while current.realm != selected.realm {
                    if !seen.insert(current.realm) || path.len() >= 32 {
                        valid = false;
                        break;
                    }
                    let (Some(parent), Some(frame)) = (current.parent_realm, current.frame) else {
                        valid = false;
                        break;
                    };
                    if !self
                        .agent
                        .host
                        .automation_frame_child_live(parent, frame, current.realm)
                    {
                        valid = false;
                        break;
                    }
                    path.push(current.clone());
                    let Some(ancestor) = inventory
                        .iter()
                        .find(|entry| entry.live && entry.realm == parent)
                    else {
                        valid = false;
                        break;
                    };
                    current = ancestor;
                }
                if valid && best.as_ref().is_none_or(|best| path.len() < best.len()) {
                    best = Some(path);
                }
            }
            if let Some(path) = best {
                let mut current = selected.clone();
                for child in path.into_iter().rev() {
                    let frame = child
                        .frame
                        .ok_or_else(crate::host::webdriver_script::ScriptError::retired)?;
                    let mapped = self
                        .agent
                        .host
                        .automation_pointer_frame_coordinates(
                            current.realm,
                            frame,
                            x,
                            y,
                            movement_x,
                            movement_y,
                        )?
                        .filter(|mapped| Self::pointer_hit_matches(&child, mapped))
                        .ok_or_else(crate::host::webdriver_script::ScriptError::retired)?;
                    current = child;
                    x = mapped.x;
                    y = mapped.y;
                    movement_x = mapped.movement_x;
                    movement_y = mapped.movement_y;
                }
                return Ok((current, x, y, movement_x, movement_y));
            }
        }
        let mut current = selected.clone();
        let mut seen = BTreeSet::new();
        loop {
            if !seen.insert(current.realm) || seen.len() > 32 {
                return Err(crate::host::webdriver_script::ScriptError::javascript(
                    "native pointer frame depth exceeded",
                ));
            }
            let Some(hit) = self.agent.host.automation_pointer_frame_target(
                current.realm,
                id,
                x,
                y,
                movement_x,
                movement_y,
            )?
            else {
                break;
            };
            let child = self
                .pointer_realms()
                .into_iter()
                .find(|entry| {
                    entry.live
                        && entry.parent_realm == Some(current.realm)
                        && entry.frame == Some(hit.frame)
                        && Self::pointer_hit_matches(entry, &hit)
                })
                .ok_or_else(|| self.pointer_frame_mismatch(&current, &hit))?;
            if !self
                .agent
                .host
                .automation_frame_child_live(current.realm, hit.frame, child.realm)
            {
                return Err(crate::host::webdriver_script::ScriptError::retired());
            }
            current = child;
            x = hit.x;
            y = hit.y;
            movement_x = hit.movement_x;
            movement_y = hit.movement_y;
        }
        Ok((current, x, y, movement_x, movement_y))
    }

    pub(crate) fn take_drag_feedback(&self) -> Vec<oryn_js::drag_image::Feedback> {
        self.agent.host.take_drag_feedback()
    }
    fn pointer_input_in_realm(
        &mut self,
        selected: &AutomationRealmSnapshot,
        target: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativePointerInput,
    ) -> Result<oryn_js::v8_bindings::NativePointerInput, crate::host::webdriver_script::ScriptError>
    {
        use crate::host::webdriver_script::ScriptError;
        self.validate_pointer_context(selected)?;
        self.validate_pointer_context(target)?;
        let inventory = self.pointer_realms();
        let mut coordinates = BTreeMap::from([(selected.realm, input.clone())]);
        let mut current = selected;
        let mut seen = BTreeSet::new();
        while let Some(parent_realm) = current.parent_realm {
            if !seen.insert(current.realm) || seen.len() > 32 {
                return Err(ScriptError::retired());
            }
            let frame = current.frame.ok_or_else(ScriptError::retired)?;
            let parent = inventory
                .iter()
                .find(|entry| entry.live && entry.realm == parent_realm)
                .ok_or_else(ScriptError::retired)?;
            if !self
                .agent
                .host
                .automation_frame_child_live(parent.realm, frame, current.realm)
            {
                return Err(ScriptError::retired());
            }
            let local = &coordinates[&current.realm];
            let mapped = self
                .agent
                .host
                .automation_pointer_parent_coordinates(
                    parent.realm,
                    frame,
                    local.x,
                    local.y,
                    local.movement_x,
                    local.movement_y,
                )?
                .filter(|mapped| Self::pointer_hit_matches(current, mapped))
                .ok_or_else(ScriptError::retired)?;
            coordinates.insert(
                parent.realm,
                oryn_js::v8_bindings::NativePointerInput {
                    x: mapped.x,
                    y: mapped.y,
                    movement_x: mapped.movement_x,
                    movement_y: mapped.movement_y,
                    ..input.clone()
                },
            );
            current = parent;
        }
        let mut path = Vec::new();
        let mut current = target;
        let mut seen = BTreeSet::new();
        while !coordinates.contains_key(&current.realm) {
            if !seen.insert(current.realm) || seen.len() > 32 {
                return Err(ScriptError::retired());
            }
            path.push(current.clone());
            let parent = current.parent_realm.ok_or_else(ScriptError::retired)?;
            current = inventory
                .iter()
                .find(|entry| entry.live && entry.realm == parent)
                .ok_or_else(ScriptError::retired)?;
        }
        let mut local = coordinates[&current.realm].clone();
        let mut parent = current.realm;
        for child in path.into_iter().rev() {
            let frame = child.frame.ok_or_else(ScriptError::retired)?;
            if !self
                .agent
                .host
                .automation_frame_child_live(parent, frame, child.realm)
            {
                return Err(ScriptError::retired());
            }
            let mapped = self
                .agent
                .host
                .automation_pointer_frame_coordinates(
                    parent,
                    frame,
                    local.x,
                    local.y,
                    local.movement_x,
                    local.movement_y,
                )?
                .filter(|mapped| Self::pointer_hit_matches(&child, mapped))
                .ok_or_else(ScriptError::retired)?;
            local.x = mapped.x;
            local.y = mapped.y;
            local.movement_x = mapped.movement_x;
            local.movement_y = mapped.movement_y;
            parent = child.realm;
        }
        Ok(local)
    }

    pub(crate) fn begin_pointer_drag_admission_in_context(
        &mut self,
        selected: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativePointerInput,
        action: oryn_js::v8_bindings::NativePointerAction,
    ) -> Result<
        Option<(
            AutomationRealmSnapshot,
            oryn_js::v8_bindings::NativePointerDragAdmission,
        )>,
        crate::host::webdriver_script::ScriptError,
    > {
        self.validate_pointer_context(selected)?;
        if action != oryn_js::v8_bindings::NativePointerAction::Move {
            return Ok(None);
        }
        let sources = self
            .pointer_realms()
            .into_iter()
            .filter(|entry| {
                entry.live
                    && self
                        .agent
                        .host
                        .automation_pointer_drag_source(entry.realm, input.id, true)
            })
            .collect::<Vec<_>>();
        if sources.len() > 1 {
            return Err(crate::host::webdriver_script::ScriptError::javascript(
                "ambiguous native pointer drag owner",
            ));
        }
        let Some(source) = sources.into_iter().next() else {
            return Ok(None);
        };
        let event = self.pointer_input_in_realm(selected, &source, input)?;
        let receipt = self.agent.host.begin_pointer_drag_admission(
            source.realm,
            source.document_generation,
            source.stream_epoch,
            &event,
        )?;
        Ok(Some((source, receipt)))
    }

    pub(crate) fn poll_pointer_drag_admission_in_context(
        &mut self,
        source: &AutomationRealmSnapshot,
        receipt: &mut oryn_js::v8_bindings::NativePointerDragAdmission,
    ) -> Result<Option<bool>, crate::host::webdriver_script::ScriptError> {
        if let Err(error) = self.validate_pointer_context(source) {
            receipt.cancel();
            return Err(error);
        }
        self.agent.host.poll_pointer_drag_admission(receipt)
    }

    pub(crate) fn begin_pointer_drag_transport(
        &mut self,
        selected: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativePointerInput,
        action: oryn_js::v8_bindings::NativePointerAction,
    ) -> Result<
        Option<(
            AutomationRealmSnapshot,
            oryn_js::v8_bindings::NativePointerInput,
            bool,
            oryn_js::v8_bindings::NativeCrossFrameDrag,
        )>,
        crate::host::webdriver_script::ScriptError,
    > {
        use crate::host::webdriver_script::ScriptError;
        use oryn_js::v8_bindings::{NativeCrossFrameDragAction, NativePointerAction};
        self.validate_pointer_context(selected)?;
        let sources = self
            .pointer_realms()
            .into_iter()
            .filter(|entry| {
                entry.live
                    && self
                        .agent
                        .host
                        .automation_pointer_drag_source(entry.realm, input.id, false)
            })
            .collect::<Vec<_>>();
        if sources.len() > 1 {
            return Err(ScriptError::javascript(
                "ambiguous native pointer drag owner",
            ));
        }
        let Some(source) = sources.into_iter().next() else {
            return Ok(None);
        };
        let source_input = self.pointer_input_in_realm(selected, &source, input)?;
        let previous_input = if let Some((realm, document, generation, epoch)) =
            self.agent.host.pointer_drag_target_identity(source.realm)
        {
            self.pointer_realms()
                .into_iter()
                .find(|entry| {
                    entry.live
                        && entry.realm == realm
                        && entry.document_root == document
                        && entry.document_generation == generation
                        && entry.stream_epoch == epoch
                })
                .map(|previous| self.pointer_input_in_realm(selected, &previous, input))
                .transpose()?
        } else {
            None
        };
        let operation = match action {
            NativePointerAction::Cancel => NativeCrossFrameDragAction::Cancel,
            NativePointerAction::Up => NativeCrossFrameDragAction::Drop,
            _ => NativeCrossFrameDragAction::Advance,
        };
        let terminal = matches!(
            action,
            NativePointerAction::Cancel | NativePointerAction::Up
        );
        let (target, target_input) = if action == NativePointerAction::Cancel {
            (None, source_input.clone())
        } else {
            let (target, x, y, dx, dy) = self.webdriver_pointer_context(
                selected,
                None,
                input.x,
                input.y,
                input.movement_x,
                input.movement_y,
            )?;
            let hit = self.agent.host.automation_pointer_physical_target(
                target.realm,
                target.document_generation,
                target.stream_epoch,
                x,
                y,
            )?;
            (
                hit.map(|node| {
                    (
                        (
                            target.realm,
                            target.document_generation,
                            target.stream_epoch,
                        ),
                        node,
                    )
                }),
                oryn_js::v8_bindings::NativePointerInput {
                    x,
                    y,
                    movement_x: dx,
                    movement_y: dy,
                    ..input.clone()
                },
            )
        };
        let receipt = self.agent.host.begin_drag_between_realms(
            (
                source.realm,
                source.document_generation,
                source.stream_epoch,
            ),
            target,
            operation,
            &source_input,
            &target_input,
            previous_input.as_ref(),
        )?;
        Ok(Some((source, source_input, terminal, receipt)))
    }

    pub(crate) fn poll_pointer_drag_transport(
        &mut self,
        source: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativePointerInput,
        terminal: bool,
        receipt: &mut oryn_js::v8_bindings::NativeCrossFrameDrag,
    ) -> Result<bool, crate::host::webdriver_script::ScriptError> {
        if let Err(error) = self.validate_pointer_context(source) {
            receipt.cancel();
            return Err(error);
        }
        self.agent
            .host
            .poll_drag_between_realms(receipt, input, terminal)
    }

    fn dispatch_pointer_drag(
        &mut self,
        selected: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativePointerInput,
        action: oryn_js::v8_bindings::NativePointerAction,
    ) -> Result<Option<(NodeId, bool)>, crate::host::webdriver_script::ScriptError> {
        use crate::host::webdriver_script::ScriptError;
        use oryn_js::v8_bindings::{NativeCrossFrameDragAction, NativePointerAction};
        let sources = self
            .pointer_realms()
            .into_iter()
            .filter(|entry| {
                entry.live
                    && self.agent.host.automation_pointer_drag_source(
                        entry.realm,
                        input.id,
                        action == NativePointerAction::Move,
                    )
            })
            .collect::<Vec<_>>();
        if sources.len() > 1 {
            return Err(ScriptError::javascript(
                "ambiguous native pointer drag owner",
            ));
        }
        let Some(source) = sources.first() else {
            return Ok(None);
        };
        let source_input = self.pointer_input_in_realm(selected, source, input)?;
        if action == NativePointerAction::Move {
            self.agent.host.prepare_pointer_drag(
                source.realm,
                source.document_generation,
                source.stream_epoch,
                &source_input,
            )?;
            if let Err(error) = self.validate_pointer_context(source) {
                self.agent.host.abandon_pointer_drag(source.realm, input.id);
                return Err(error);
            }
        }
        if !self
            .agent
            .host
            .automation_pointer_drag_source(source.realm, input.id, false)
        {
            return Ok(None);
        }
        let previous_input = if let Some((realm, document, generation, epoch)) =
            self.agent.host.pointer_drag_target_identity(source.realm)
        {
            self.pointer_realms()
                .into_iter()
                .find(|entry| {
                    entry.live
                        && entry.realm == realm
                        && entry.document_root == document
                        && entry.document_generation == generation
                        && entry.stream_epoch == epoch
                })
                .map(|previous| self.pointer_input_in_realm(selected, &previous, input))
                .transpose()?
        } else {
            None
        };
        let operation = match action {
            NativePointerAction::Cancel => NativeCrossFrameDragAction::Cancel,
            NativePointerAction::Up => NativeCrossFrameDragAction::Drop,
            _ => NativeCrossFrameDragAction::Advance,
        };
        if action == NativePointerAction::Cancel {
            self.agent.host.dispatch_drag_between_realms(
                (
                    source.realm,
                    source.document_generation,
                    source.stream_epoch,
                ),
                None,
                operation,
                &source_input,
                &source_input,
                previous_input.as_ref(),
            )?;
            return Ok(Some((source.document_root, true)));
        }
        let (target, x, y, dx, dy) = self.webdriver_pointer_context(
            selected,
            None,
            input.x,
            input.y,
            input.movement_x,
            input.movement_y,
        )?;
        let target_input = oryn_js::v8_bindings::NativePointerInput {
            x,
            y,
            movement_x: dx,
            movement_y: dy,
            ..input.clone()
        };
        let hit = if action == NativePointerAction::Cancel {
            None
        } else {
            self.agent.host.automation_pointer_physical_target(
                target.realm,
                target.document_generation,
                target.stream_epoch,
                x,
                y,
            )?
        };
        self.agent.host.dispatch_drag_between_realms(
            (
                source.realm,
                source.document_generation,
                source.stream_epoch,
            ),
            hit.map(|node| {
                (
                    (
                        target.realm,
                        target.document_generation,
                        target.stream_epoch,
                    ),
                    node,
                )
            }),
            operation,
            &source_input,
            &target_input,
            previous_input.as_ref(),
        )?;
        Ok(Some((hit.unwrap_or(source.document_root), true)))
    }

    fn prepare_pointer_boundaries(
        &mut self,
        target: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativePointerInput,
    ) -> Result<Vec<PointerBoundaryStep>, crate::host::webdriver_script::ScriptError> {
        use crate::host::webdriver_script::ScriptError;
        let owned = self
            .agent
            .host
            .automation_pointer_owns_routing(target.realm, input.id);
        let inventory = self.pointer_realms();
        let mut coordinates = BTreeMap::from([(target.realm, input.clone())]);
        let mut ancestors = Vec::new();
        let mut current = target.clone();
        let mut seen = BTreeSet::new();
        while let Some(parent_realm) = current.parent_realm {
            if !seen.insert(current.realm) || seen.len() > 32 {
                return Err(ScriptError::retired());
            }
            let frame = current.frame.ok_or_else(ScriptError::retired)?;
            let parent = inventory
                .iter()
                .find(|entry| entry.live && entry.realm == parent_realm)
                .cloned()
                .ok_or_else(ScriptError::retired)?;
            if !self
                .agent
                .host
                .automation_frame_child_live(parent.realm, frame, current.realm)
            {
                return Err(ScriptError::retired());
            }
            let child_input = &coordinates[&current.realm];
            let mapped = self
                .agent
                .host
                .automation_pointer_parent_coordinates(
                    parent.realm,
                    frame,
                    child_input.x,
                    child_input.y,
                    child_input.movement_x,
                    child_input.movement_y,
                )?
                .filter(|mapped| Self::pointer_hit_matches(&current, mapped))
                .ok_or_else(ScriptError::retired)?;
            coordinates.insert(
                parent.realm,
                oryn_js::v8_bindings::NativePointerInput {
                    x: mapped.x,
                    y: mapped.y,
                    movement_x: mapped.movement_x,
                    movement_y: mapped.movement_y,
                    ..input.clone()
                },
            );
            ancestors.push((parent.clone(), frame));
            current = parent;
        }
        let mut exits = Vec::new();
        for old in &inventory {
            // End the immutable hover eligibility borrow before admitting
            // mutable provider work for this occurrence. Preserve scan order.
            if owned || !old.live || old.realm == target.realm
                || coordinates.contains_key(&old.realm)
                || !self.agent.host.automation_pointer_has_hover(old.realm, input.id)
            {
                continue;
            }
            let mut path = Vec::new();
            let mut current = old;
            let mut seen = BTreeSet::new();
            while !coordinates.contains_key(&current.realm) {
                if !seen.insert(current.realm) || seen.len() > 32 {
                    return Err(ScriptError::retired());
                }
                path.push(current.clone());
                let Some(parent) = current.parent_realm else {
                    break;
                };
                current = inventory
                    .iter()
                    .find(|entry| entry.live && entry.realm == parent)
                    .ok_or_else(ScriptError::retired)?;
            }
            let Some(mut local) = coordinates.get(&current.realm).cloned() else {
                continue;
            };
            let depth = path.len();
            let mut parent = current.realm;
            for child in path.into_iter().rev() {
                let frame = child.frame.ok_or_else(ScriptError::retired)?;
                if !self
                    .agent
                    .host
                    .automation_frame_child_live(parent, frame, child.realm)
                {
                    return Err(ScriptError::retired());
                }
                let mapped = self
                    .agent
                    .host
                    .automation_pointer_frame_coordinates(
                        parent,
                        frame,
                        local.x,
                        local.y,
                        local.movement_x,
                        local.movement_y,
                    )?
                    .filter(|mapped| Self::pointer_hit_matches(&child, mapped))
                    .ok_or_else(ScriptError::retired)?;
                local.x = mapped.x;
                local.y = mapped.y;
                local.movement_x = mapped.movement_x;
                local.movement_y = mapped.movement_y;
                parent = child.realm;
            }
            exits.push((depth, old.clone(), local));
        }
        // Leave deepest old documents before entering their replacement path.
        exits.sort_by_key(|entry| std::cmp::Reverse(entry.0));
        let mut route = Vec::with_capacity(exits.len() + ancestors.len());
        for (_, old, local) in exits {
            self.validate_pointer_context(&old)?;
            route.push(PointerBoundaryStep {
                context: old,
                input: local,
                target: None,
            });
        }
        // Capture fixes the child route, but its embedding documents still
        // consume the physical sample so released buttons cannot remain down.
        // Unchanged ancestor targets publish no additional boundary events.
        for (parent, frame) in ancestors.into_iter().rev() {
            self.validate_pointer_context(&parent)?;
            let local = coordinates[&parent.realm].clone();
            route.push(PointerBoundaryStep {
                context: parent,
                input: local,
                target: Some(frame),
            });
        }
        self.validate_pointer_context(target)?;
        Ok(route)
    }

    fn prepare_stationary_pointer_boundaries(
        &mut self,
    ) -> Result<Vec<PointerBoundaryStep>, crate::host::webdriver_script::ScriptError> {
        let mut steps = Vec::new();
        if let Some(root) = self
            .pointer_realms()
            .into_iter()
            .find(|entry| entry.live && entry.realm == self.top_realm)
        {
            for sample in self.agent.host.native_pointer_hover_inputs(root.realm) {
                let (target, x, y, _, _) = self.webdriver_pointer_context(
                    &root,
                    Some(sample.id),
                    sample.x,
                    sample.y,
                    0.,
                    0.,
                )?;
                let local = oryn_js::v8_bindings::NativePointerInput {
                    x,
                    y,
                    movement_x: 0.,
                    movement_y: 0.,
                    ..sample
                };
                steps.extend(self.prepare_pointer_boundaries(&target, &local)?);
                let hit = self.agent.host.automation_pointer_physical_target(
                    target.realm,
                    target.document_generation,
                    target.stream_epoch,
                    x,
                    y,
                )?;
                steps.push(PointerBoundaryStep {
                    context: target,
                    input: local,
                    target: hit,
                });
            }
        }
        Ok(steps)
    }

    fn poll_stationary_pointer_boundaries(
        &mut self,
    ) -> Result<(), crate::host::webdriver_script::ScriptError> {
        use crate::host::webdriver_script::ScriptError;
        if self
            .stationary_pointer_route
            .as_ref()
            .is_some_and(|route| route.delay().is_none_or(|delay| !delay.is_zero()))
        {
            return Ok(());
        }
        let mut route = if let Some(route) = self.stationary_pointer_route.take() {
            route
        } else {
            let steps = self.prepare_stationary_pointer_boundaries()?;
            StationaryPointerRoute {
                boundaries: self.admit_pointer_boundaries(steps)?,
                next: 0,
                retry_at: None,
            }
        };
        while let Some((context, receipt)) = route.boundaries.get_mut(route.next) {
            self.validate_pointer_context(context)?;
            match self.agent.host.poll_pointer_boundary(receipt) {
                Ok(true) => {
                    if receipt.canceled() {
                        return Err(ScriptError::retired());
                    }
                    route.next += 1;
                }
                Ok(false) => {
                    self.stationary_pointer_route = Some(route);
                    return Ok(());
                }
                Err(error) => {
                    if receipt.retry_safe() {
                        route.retry_at =
                            Some(std::time::Instant::now() + Duration::from_millis(25));
                        self.stationary_pointer_route = Some(route);
                    }
                    return Err(error);
                }
            }
        }
        Ok(())
    }

    fn admit_pointer_boundaries(
        &self,
        steps: Vec<PointerBoundaryStep>,
    ) -> Result<
        Vec<(
            AutomationRealmSnapshot,
            oryn_js::v8_bindings::NativePointerBoundary,
        )>,
        crate::host::webdriver_script::ScriptError,
    > {
        steps
            .into_iter()
            .map(|step| {
                self.validate_pointer_context(&step.context)?;
                let receipt = self.agent.host.begin_pointer_boundary(
                    step.context.realm,
                    step.context.document_generation,
                    step.context.stream_epoch,
                    &step.input,
                    step.target,
                )?;
                Ok((step.context, receipt))
            })
            .collect()
    }

    pub(crate) fn begin_pointer_dispatch_in_context(
        &mut self,
        selected: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativePointerInput,
        action: oryn_js::v8_bindings::NativePointerAction,
    ) -> Result<PointerDispatchRoute, crate::host::webdriver_script::ScriptError> {
        self.validate_pointer_context(selected)?;
        // Existing idle publications transfer their cursor into this sample;
        // they cannot be reconstructed from a newly sampled hover inventory.
        let steps = self.prepare_stationary_pointer_boundaries()?;
        let newly_admitted = self.admit_pointer_boundaries(steps)?;
        let (mut boundaries, next) = self
            .stationary_pointer_route
            .take()
            .map(|route| (route.boundaries, route.next))
            .unwrap_or_default();
        boundaries.extend(newly_admitted);
        Ok(PointerDispatchRoute {
            selected: selected.clone(),
            input: input.clone(),
            action,
            boundaries,
            next,
            phase: 0,
            boundary_target: None,
            dispatch: None,
            result: None,
            canceled: false,
        })
    }

    pub(crate) fn poll_pointer_dispatch_in_context(
        &mut self,
        route: &mut PointerDispatchRoute,
    ) -> Result<Option<(NodeId, bool)>, crate::host::webdriver_script::ScriptError> {
        use crate::host::webdriver_script::ScriptError;
        if route.canceled {
            return Err(ScriptError::retired());
        }
        if route.result.is_some() {
            return Ok(route.result);
        }
        if let Err(error) = self.validate_pointer_context(&route.selected) {
            route.cancel();
            return Err(error);
        }
        loop {
            if let Some(target) = &route.boundary_target
                && let Err(error) = self.validate_pointer_context(target)
            {
                route.cancel();
                return Err(error);
            }
            while let Some((context, receipt)) = route.boundaries.get_mut(route.next) {
                if let Err(error) = self.validate_pointer_context(context) {
                    route.cancel();
                    return Err(error);
                }
                if !self.agent.host.poll_pointer_boundary(receipt)? {
                    return Ok(None);
                }
                if receipt.canceled() {
                    route.cancel();
                    return Err(ScriptError::retired());
                }
                if let Some(target) = &route.boundary_target
                    && let Err(error) = self.validate_pointer_context(target)
                {
                    route.cancel();
                    return Err(error);
                }
                route.next += 1;
            }
            route.boundaries.clear();
            route.next = 0;
            if route.phase == 0 {
                let input = &route.input;
                let (target, x, y, movement_x, movement_y) = self.webdriver_pointer_context(
                    &route.selected,
                    Some(input.id),
                    input.x,
                    input.y,
                    input.movement_x,
                    input.movement_y,
                )?;
                // Cancel still releases the physical button sample in each
                // ancestor of an owned child, without changing its hover path.
                let steps = if (route.action != oryn_js::v8_bindings::NativePointerAction::Cancel
                    || self
                        .agent
                        .host
                        .automation_pointer_owns_routing(target.realm, input.id))
                    && !(input.device == oryn_js::v8_bindings::NativePointerDevice::Touch
                        && route.action == oryn_js::v8_bindings::NativePointerAction::Move
                        && input.buttons == 0)
                {
                    let local = oryn_js::v8_bindings::NativePointerInput {
                        x,
                        y,
                        movement_x,
                        movement_y,
                        ..input.clone()
                    };
                    self.prepare_pointer_boundaries(&target, &local)?
                } else {
                    Vec::new()
                };
                route.boundaries = self.admit_pointer_boundaries(steps)?;
                route.boundary_target = Some(target);
                route.phase = 1;
                continue;
            }
            if route.dispatch.is_none() {
                // Boundary callbacks may change capture, but they cannot
                // replace or remove the admitted child and redirect its sample.
                // Its identity was checked after each boundary publication.
                let input = &route.input;
                let (target, x, y, movement_x, movement_y) = self.webdriver_pointer_context(
                    &route.selected,
                    Some(input.id),
                    input.x,
                    input.y,
                    input.movement_x,
                    input.movement_y,
                )?;
                let local = oryn_js::v8_bindings::NativePointerInput {
                    x,
                    y,
                    movement_x,
                    movement_y,
                    ..input.clone()
                };
                let receipt = self.agent.host.begin_pointer_dispatch(
                    target.realm,
                    target.document_generation,
                    target.stream_epoch,
                    &local,
                    route.action,
                )?;
                route.dispatch = Some((target, receipt));
            }
            let (target, receipt) = route.dispatch.as_mut().unwrap();
            if let Err(error) = self.validate_pointer_context(target) {
                route.cancel();
                return Err(error);
            }
            route.result = self.agent.host.poll_pointer_dispatch(receipt)?;
            if route.result.is_some() {
                route.dispatch = None;
            }
            return Ok(route.result);
        }
    }

    pub(crate) fn dispatch_webdriver_pointer_in_context(
        &mut self,
        selected: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativePointerInput,
        action: oryn_js::v8_bindings::NativePointerAction,
    ) -> Result<(NodeId, bool), crate::host::webdriver_script::ScriptError> {
        self.validate_pointer_context(selected)?;
        if let Some(result) = self.dispatch_pointer_drag(selected, input, action)? {
            return Ok(result);
        }
        let mut receipt = self.begin_pointer_dispatch_in_context(selected, input, action)?;
        self.poll_pointer_dispatch_in_context(&mut receipt)?
            .ok_or_else(|| {
                crate::host::webdriver_script::ScriptError::javascript("pointer dispatch suspended")
            })
    }

    #[cfg(test)]
    pub(crate) fn dispatch_webdriver_wheel_in_context(
        &mut self,
        selected: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativeWheelInput,
    ) -> Result<bool, crate::host::webdriver_script::ScriptError> {
        self.dispatch_webdriver_wheel_transaction_in_context(selected, input, &mut None)
    }
    pub(crate) fn dispatch_webdriver_wheel_transaction_in_context(
        &mut self,
        selected: &AutomationRealmSnapshot,
        input: &oryn_js::v8_bindings::NativeWheelInput,
        route: &mut Option<AutomationRealmSnapshot>,
    ) -> Result<bool, crate::host::webdriver_script::ScriptError> {
        self.validate_pointer_context(selected)?;
        let cached = route
            .as_ref()
            .filter(|target| self.validate_pointer_context(target).is_ok())
            .and_then(|target| {
                self.pointer_input_in_realm(
                    selected,
                    target,
                    &oryn_js::v8_bindings::NativePointerInput {
                        x: input.x,
                        y: input.y,
                        ..Default::default()
                    },
                )
                .ok()
                .map(|local| (target.clone(), local.x, local.y))
            });
        let (target, x, y) = if let Some(cached) = cached {
            cached
        } else {
            if route.is_some()
                && let Some(transaction) = &input.transaction
            {
                transaction.clear();
            }
            let (target, x, y, _, _) =
                self.webdriver_pointer_context(selected, None, input.x, input.y, 0., 0.)?;
            (target, x, y)
        };
        *route = Some(target.clone());
        let input = oryn_js::v8_bindings::NativeWheelInput {
            x,
            y,
            ..input.clone()
        };
        let result = self.agent.host.dispatch_webdriver_wheel(
            target.realm,
            target.document_generation,
            target.stream_epoch,
            &input,
        )?;
        let mut remaining = result.remaining;
        let mut current = target;
        let mut seen = BTreeSet::new();
        while remaining != (0., 0.) && current.parent_realm.is_some() {
            if !seen.insert(current.realm) || seen.len() > 32 {
                return Err(crate::host::webdriver_script::ScriptError::retired());
            }
            self.validate_pointer_context(&current)?;
            let (Some(parent_realm), Some(frame)) = (current.parent_realm, current.frame) else {
                return Err(crate::host::webdriver_script::ScriptError::retired());
            };
            let parent = self
                .pointer_realms()
                .into_iter()
                .find(|entry| entry.live && entry.realm == parent_realm)
                .ok_or_else(crate::host::webdriver_script::ScriptError::retired)?;
            if !self
                .agent
                .host
                .automation_frame_child_live(parent_realm, frame, current.realm)
            {
                return Err(crate::host::webdriver_script::ScriptError::retired());
            }
            remaining = self.agent.host.apply_webdriver_wheel_remainder(
                parent.realm,
                parent.document_generation,
                parent.stream_epoch,
                frame,
                remaining,
            )?;
            current = parent;
        }
        Ok(result.allowed)
    }
    pub(crate) fn validate_action_context(
        &self,
        selected: &AutomationRealmSnapshot,
    ) -> Result<(), crate::host::webdriver_script::ScriptError> {
        if self
            .automation_realms()
            .iter()
            .any(|entry| entry.same_document_as(selected))
        {
            Ok(())
        } else {
            Err(crate::host::webdriver_script::ScriptError {
                code: "no such frame".into(),
                message: "selected input document changed".into(),
            })
        }
    }
