    pub fn begin_webdriver_script_in_context(
        &mut self,
        selected: &AutomationRealmSnapshot,
        request: crate::host::webdriver_script::ScriptRequest,
    ) -> Result<crate::host::webdriver_script::ScriptId, crate::host::webdriver_script::ScriptError>
    {
        if !self
            .automation_realms()
            .iter()
            .any(|entry| entry.same_document_as(selected))
        {
            return Err(crate::host::webdriver_script::ScriptError {
                code: "no such frame".into(),
                message: "selected frame document changed".into(),
            });
        }
        self.begin_webdriver_script_in_realm(selected.realm, request)
    }

    pub fn begin_webdriver_script_in_realm(
        &mut self,
        realm: RealmId,
        request: crate::host::webdriver_script::ScriptRequest,
    ) -> Result<crate::host::webdriver_script::ScriptId, crate::host::webdriver_script::ScriptError>
    {
        use crate::host::webdriver_script::ScriptError;
        if !self
            .automation_realms()
            .iter()
            .any(|entry| entry.realm == realm && entry.live)
        {
            return Err(ScriptError::retired());
        }
        let previous = self.agent.host.active_realm();
        self.agent.host.activate_realm(realm)?;
        let result = self.agent.host.begin_webdriver_script(request);
        if self.agent.host.realm_execution_live(previous) {
            self.agent.host.activate_realm(previous)?;
        }
        result
    }

