    /// Snapshot recipients before dispatch: newly-created documents do not receive
    /// half of this lifecycle event, and retired descendants are never entered.
    pub(crate) fn prepare_print_lifecycle(
        &mut self,
        event_type: &str,
    ) -> Result<crate::host::NativePageTransition, HostError> {
        if !matches!(event_type, "beforeprint" | "afterprint") {
            return Err(HostError::Execution("invalid print lifecycle event".into()));
        }
        let root = if let Some(selected) = &self.automation_scope {
            self.validate_action_context(selected)
                .map_err(|error| HostError::Execution(error.to_string()))?;
            selected.realm
        } else {
            self.top_realm
        };
        self.agent
            .host
            .prepare_native_page_transition(root, event_type, false)
    }
    pub(crate) fn poll_print_lifecycle(
        &mut self,
        receipt: &mut crate::host::NativePageTransition,
    ) -> Result<bool, HostError> {
        let complete = self.agent.host.resume_native_page_transition(receipt)?;
        self.agent.host.activate_realm(self.top_realm)?;
        if complete {
            self.checkpoint()?;
        }
        Ok(complete)
    }

    pub fn dispatch_print_lifecycle(&mut self, event_type: &str) -> Result<(), HostError> {
        let mut receipt = self.prepare_print_lifecycle(event_type)?;
        if self.poll_print_lifecycle(&mut receipt)? {
            Ok(())
        } else {
            Err(HostError::Execution(
                "print lifecycle publication pending".into(),
            ))
        }
    }

