    pub(crate) fn retire_owned_cached_document(&mut self) -> Result<(), HostError> {
        if self.standalone_shared_root {
            return self.agent.host.retire_standalone_root(self.top_realm);
        }
        self.agent.host.resume_page_isolate();
        #[cfg(unix)]
        let result = self.agent.host.retire_agent_root(self.top_realm);
        #[cfg(not(unix))]
        let result = self.agent.host.retire_standalone_root(self.top_realm);
        if result.is_err() {
            self.agent.host.suspend_page_isolate();
        }
        result
    }

    pub fn suspend_for_back_forward_cache(&mut self) -> Result<(), HostError> {
        if self.standalone_shared_root {
            return self.agent.host.park_standalone_root(self.top_realm);
        }
        #[cfg(unix)]
        self.agent.host.park_document_authority(self.top_realm)?;
        #[cfg(unix)]
        if self.context.is_some() {
            return Ok(());
        }
        self.agent.host.suspend_page_isolate();
        Ok(())
    }

    /// Parent origin/security commit precedes this; no author script runs here.
    /// Call finish_cached_authority_restore after native installation commits.
    pub fn restore_cached_authority(&mut self) -> Result<(), HostError> {
        if self.standalone_shared_root {
            return self.agent.host.restore_standalone_root(self.top_realm);
        }
        #[cfg(unix)]
        if self.context.is_some() {
            self.agent
                .host
                .restore_document_authority_suspended(self.top_realm)?;
            self.agent
                .host
                .restore_navigation_root_proxy(self.top_realm)?;
        }
        // Independent standalone isolates retain their original global and have
        // no parent proxy or authority token. resume_from_back_forward_cache
        // resumes that isolate only after the actor has installed the document.
        Ok(())
    }

    pub(crate) fn finish_cached_authority_restore(&mut self) -> Result<(), HostError> {
        #[cfg(unix)]
        if self.context.is_some() {
            return self.agent.host.resume_restored_document(self.top_realm);
        }
        Ok(())
    }

    pub(crate) fn uses_shared_agent_host(&self) -> bool {
        if self.standalone_shared_root {
            return true;
        }
        #[cfg(unix)]
        {
            self.context.is_some()
        }
        #[cfg(not(unix))]
        {
            false
        }
    }

    pub(crate) fn restore_standalone_cached_window_name(
        &self,
        name: String,
    ) -> Result<(), HostError> {
        #[cfg(unix)]
        if self.context.is_some() {
            return Err(HostError::Execution(
                "parent-owned cached name requires native authority".into(),
            ));
        }
        self.agent
            .host
            .restore_standalone_cached_window_name(self.top_realm, name)
    }

