    #[test]
    fn parser_snapshot_uses_trusted_source_without_rewriting_dom() {
        let mut page = RustExecutableDocument::load(
            "<body><script id='candidate' type='text/author'>original</script></body>",
        )
        .unwrap();
        page.agent
            .host
            .configure_trusted_types(
                oryn_js::trusted_types::TrustedTypesConfig {
                    require_script: true,
                    allow_any_policy: true,
                    ..Default::default()
                },
                true,
            )
            .unwrap();
        let dom = page.agent.dom.clone();
        let document = dom.borrow().document();
        let script = dom.borrow().find_by_id("candidate").unwrap();
        // Native mutation represents an author changing child Text, which is
        // deliberately not itself a Trusted Types sink.
        dom.borrow_mut()
            .set_text_content(script, "changed")
            .unwrap();
        assert!(
            collect_prepared_scripts(&mut page.agent.host, &dom, document)
                .unwrap()
                .is_empty()
        );
        assert!(!dom.borrow().script_already_started(script).unwrap());
        page.evaluate(r#"globalThis.conversions=0;trustedTypes.createPolicy('default',{createScript(source,kind,sink){
            conversions++;if(source!=='changed'||kind!=='TrustedScript'||sink!=='HTMLScriptElement text')throw Error('wrong sink');
            document.getElementById('candidate').type='text/javascript';return 'globalThis.accepted=42';
        }});'ok'"#).unwrap();
        let records = collect_prepared_scripts(&mut page.agent.host, &dom, document).unwrap();
        assert_eq!(records.len(), 1);
        assert_eq!(records[0].3.as_source().raw(), "globalThis.accepted=42");
        assert!(
            records[0]
                .2
                .as_deref()
                .is_some_and(html::is_javascript_mime_type)
        );
        assert_eq!(
            dom.borrow()
                .arena()
                .child_text_source(script, 1024)
                .unwrap(),
            "changed"
        );
        assert_eq!(page.evaluate("String(conversions)").unwrap(), "1");
        // The admitted record retains the accepted source across later edits;
        // its execution must not reread or reconvert mutable child text.
        dom.borrow_mut().set_text_content(script, "later").unwrap();
        assert_eq!(records[0].3.as_source().raw(), "globalThis.accepted=42");
    }

