    #[test]
    fn custom_state_iterator_prototype_uses_original_realm_intrinsics() {
        let mut page = RustExecutableDocument::load("<div></div>").unwrap();
        let result = page.evaluate(r#"(() => {
            customElements.define('x-state-prototype',class extends HTMLElement {});
            const states=document.createElement('x-state-prototype').attachInternals().states;
            const original=Object.getPrototypeOf(Object.getPrototypeOf([][Symbol.iterator]()));
            const saved=Array.prototype.values;
            Array.prototype.values=function(){throw Error('poisoned values')};
            const first=states.values(),second=states.entries(),prototype=Object.getPrototypeOf(first);
            Array.prototype.values=saved;
            const next=Object.getOwnPropertyDescriptor(prototype,'next');
            const tag=Object.getOwnPropertyDescriptor(prototype,Symbol.toStringTag);
            const checks=[Object.getPrototypeOf(second)===prototype,Object.getPrototypeOf(prototype)===original,
                !Object.hasOwn(first,'next'),!Object.hasOwn(first,Symbol.iterator),
                next.writable,next.configurable,!next.enumerable,next.value.name==='next',next.value.length===0,
                tag.value==='CustomStateSet Iterator',!tag.writable,tag.configurable,!tag.enumerable,
                Object.prototype.toString.call(first)==='[object CustomStateSet Iterator]'];
            let rejected=false;try{new next.value()}catch(e){rejected=e instanceof TypeError}checks.push(rejected);
            return JSON.stringify([checks.length,checks.every(Boolean)]);
        })()"#).unwrap();
        assert_eq!(result, "[15,true]");
    }

    #[test]
    fn custom_state_iterators_track_mutation_and_remain_exhausted() {
        let mut page = RustExecutableDocument::load("<div></div>").unwrap();
        let result = page.evaluate(r#"(() => {
            customElements.define('x-state-iterator',class extends HTMLElement {});
            const states=document.createElement('x-state-iterator').attachInternals().states;
            states.add('b');states.add('a');
            const iterator=states.values(),checks=[states.keys===states.values,states[Symbol.iterator]===states.values,
                iterator[Symbol.iterator]()===iterator,iterator.next().value==='b'];
            states.delete('a');states.add('c');checks.push(iterator.next().value==='c');
            states.clear();states.add('d');checks.push(iterator.next().value==='d',iterator.next().done);
            states.add('e');checks.push(iterator.next().done);
            checks.push(JSON.stringify([...states])==='["d","e"]',
                JSON.stringify([...states.entries()])==='[["d","d"],["e","e"]]');
            let rejected=false;try{iterator.next.call({})}catch(e){rejected=e instanceof TypeError}
            checks.push(rejected);
            return JSON.stringify([checks.length,checks.every(Boolean)]);
        })()"#).unwrap();
        assert_eq!(result, "[11,true]");
    }

    #[test]
    fn custom_states_accept_dom_strings_and_foreach_observes_live_insertion_order() {
        let mut page = RustExecutableDocument::load("<div></div>").unwrap();
        let result = page
            .evaluate(
                r#"(() => {
            customElements.define('x-state-order',class extends HTMLElement {});
            const states=document.createElement('x-state-order').attachInternals().states;
            const checks=[],seen=[],receiver={};
            states.add('z');states.add('');states.add('with spaces');states.add('z');
            checks.push(states.size===3,states.has(''),states.has('with spaces'));
            states.forEach(function(value,key,set){
                checks.push(this===receiver,value===key,set===states);seen.push(value);
                if(value==='z'){states.delete('');states.add('tail')}
            },receiver);
            checks.push(seen.join('|')==='z|with spaces|tail');
            const cleared=[];states.forEach(value=>{
                cleared.push(value);if(value==='z'){states.clear();states.add('after-clear')}
            });
            checks.push(cleared.join('|')==='z|after-clear',states.size===1);
            const sentinel={};let exact=false;
            try{states.forEach(()=>{throw sentinel})}catch(e){exact=e===sentinel}
            checks.push(exact);
            let rejected=false;try{states.forEach(null)}catch(e){rejected=e instanceof TypeError}
            checks.push(rejected);
            return JSON.stringify([checks.length,checks.every(Boolean)]);
        })()"#,
            )
            .unwrap();
        assert_eq!(result, "[17,true]");
    }

    #[test]
    fn mouse_family_related_targets_share_shadow_dispatch_rules() {
        let mut page =
            RustExecutableDocument::load("<div id=host></div><button id=outside>Outside</button>")
                .unwrap();
        let result = page.evaluate(r#"(() => {
            const host=document.getElementById('host'),root=host.attachShadow({mode:'closed'});
            root.innerHTML='<button id="a">A</button><button id="b">B</button>';
            const a=root.querySelector('#a'),b=root.querySelector('#b'),outside=document.getElementById('outside'),checks=[];
            for(const [index,Constructor] of [MouseEvent,PointerEvent,WheelEvent].entries()) {
                const type='internal-mouse-'+index;let escaped=0,inside=false;
                host.addEventListener(type,()=>escaped++);
                root.addEventListener(type,e=>inside=e.target===b&&e.relatedTarget===a&&e.composedPath().at(-1)===root);
                const event=new Constructor(type,{bubbles:true,composed:true,relatedTarget:a});b.dispatchEvent(event);
                checks.push(inside,escaped===0,event.target===null,event.relatedTarget===null);
                const external='external-mouse-'+index;
                outside.addEventListener(external,e=>checks.push(e.relatedTarget===host));
                const outer=new Constructor(external,{bubbles:true,composed:true,relatedTarget:a});outside.dispatchEvent(outer);
                checks.push(outer.relatedTarget===host);
            }
            return JSON.stringify([checks.length,checks.every(Boolean)]);
        })()"#).unwrap();
        assert_eq!(result, "[18,true]");
    }

    #[test]
    fn focus_transitions_inside_a_shadow_tree_do_not_escape_as_host_transitions() {
        let mut page = RustExecutableDocument::load("<div id=host></div>").unwrap();
        let result = page.evaluate(r#"(() => {
            const host=document.getElementById('host'),root=host.attachShadow({mode:'closed'});
            root.innerHTML='<input id="from"><input id="to">';
            const from=root.querySelector('#from'),to=root.querySelector('#to'),checks=[];let outside=0;
            for(const target of [host,document,window])target.addEventListener('internal-focus',()=>outside++,true);
            root.addEventListener('internal-focus',e=>{
                const path=e.composedPath();
                checks.push(e.target===to,e.relatedTarget===from,path[0]===to,path[path.length-1]===root,!path.includes(host));
            });
            const event=new FocusEvent('internal-focus',{bubbles:true,composed:true,relatedTarget:from});
            to.dispatchEvent(event);
            checks.push(outside===0,event.target===null,event.relatedTarget===null);
            return JSON.stringify([checks.length,checks.every(Boolean)]);
        })()"#).unwrap();
        assert_eq!(result, "[8,true]");
    }

