    #[test]
    fn element_internals_requires_definition_and_one_attachment() {
        let mut page =
            RustExecutableDocument::load("<x-upgrade-internals></x-upgrade-internals>").unwrap();
        let result = page.evaluate(r#"(() => {
            const checks=[];
            for(const node of [document.createElement('div'),document.createElement('x-undefined-internals')]) {
                let rejected=false;try{node.attachInternals()}catch(e){rejected=e.name==='NotSupportedError'}
                checks.push(rejected);
            }
            class Disabled extends HTMLElement {static disabledFeatures=['internals']}
            customElements.define('x-disabled-internals',Disabled);
            const disabled=document.createElement('x-disabled-internals');
            let rejected=false;try{disabled.attachInternals()}catch(e){rejected=e.name==='NotSupportedError'}
            checks.push(rejected,disabled.attachShadow({mode:'open'}).mode==='open');
            class Enabled extends HTMLElement {}
            customElements.define('x-enabled-internals',Enabled);
            const enabled=document.createElement('x-enabled-internals'),internals=enabled.attachInternals();
            checks.push(internals instanceof ElementInternals);
            let duplicate=false;try{enabled.attachInternals()}catch(e){duplicate=e.name==='NotSupportedError'}
            checks.push(duplicate,internals.states===internals.states);
            class Upgrade extends HTMLElement {constructor(){super();this.savedInternals=this.attachInternals()}}
            customElements.define('x-upgrade-internals',Upgrade);
            const upgraded=document.querySelector('x-upgrade-internals');customElements.upgrade(upgraded);
            checks.push(upgraded.savedInternals instanceof ElementInternals);
            let repeated=false;try{upgraded.attachInternals()}catch(e){repeated=e.name==='NotSupportedError'}
            checks.push(repeated);
            return JSON.stringify([checks.length,checks.every(Boolean)]);
        })()"#).unwrap();
        assert_eq!(result, "[9,true]");
    }

