    #[test]
    fn slotchange_coalesces_transient_assignment_after_mutation_observers() {
        let mut page = RustExecutableDocument::load("<div id=host></div>").unwrap();
        page.evaluate(
            r#"
            globalThis.slotLog=[];
            const host=document.getElementById('host'),root=host.attachShadow({mode:'open'});
            root.innerHTML='<slot name="x"></slot>';const slot=root.querySelector('slot');
            new MutationObserver(()=>slotLog.push('observer')).observe(host,{childList:true});
            slot.addEventListener('slotchange',e=>slotLog.push([
                'slot',e.isTrusted,e.bubbles,e.composed,e.cancelable,e.target===slot,
                slot.assignedNodes().length].join('|')));
            host.addEventListener('slotchange',()=>slotLog.push('escaped'));
            const child=document.createElement('i');child.setAttribute('slot','x');
            host.appendChild(child);child.remove();
            slotLog.push('sync');
        "#,
        )
        .unwrap();
        assert_eq!(
            page.evaluate("JSON.stringify(slotLog)").unwrap(),
            r#"["sync","observer","slot|true|true|false|false|true|0"]"#
        );
    }

