    #[test]
    fn slotted_noncomposed_events_cross_closed_tree_without_exposing_internals() {
        let mut page = RustExecutableDocument::load("<div id=host></div>").unwrap();
        let result = page.evaluate(r#"(() => {
            const host=document.getElementById('host'),root=host.attachShadow({mode:'closed'});
            root.innerHTML='<section><slot name="item"></slot></section>';
            const section=root.querySelector('section'),slot=root.querySelector('slot');
            const target=document.createElement('button');target.setAttribute('slot','item');host.appendChild(target);
            const checks=[],visits=[];
            const event=new Event('slotted',{bubbles:true,composed:false});
            addEventListener('slotted',e=>{
                visits.push('window-capture');
                const path=e.composedPath();
                checks.push(e.target===target,path[0]===target,path[1]===host,
                    !path.includes(slot),!path.includes(section),!path.includes(root));
                target.setAttribute('slot','unassigned');
            },true);
            target.addEventListener('slotted',e=>{
                visits.push('target');checks.push(e.composedPath()[1]===host);
            });
            slot.addEventListener('slotted',e=>{
                visits.push('slot');const path=e.composedPath();
                checks.push(e.target===target,e.eventPhase===3,path[0]===target,path[1]===slot,
                    path[2]===section,path[3]===root,path[4]===host);
            });
            root.addEventListener('slotted',()=>visits.push('root'));
            host.addEventListener('slotted',e=>{
                visits.push('host');checks.push(e.target===target,e.eventPhase===3,
                    e.composedPath()[1]===host);
            });
            target.dispatchEvent(event);
            checks.push(event.target===target,event.composedPath().length===0);
            return JSON.stringify([checks.length,checks.every(Boolean),visits]);
        })()"#).unwrap();
        assert_eq!(
            result,
            r#"[19,true,["window-capture","target","slot","root","host"]]"#
        );
    }

