    #[test]
    fn native_slot_assignment_tracks_names_order_and_closed_roots() {
        let mut page = RustExecutableDocument::load("<div id=host></div>").unwrap();
        let result = page.evaluate(r#"(() => {
            const host=document.getElementById('host'),root=host.attachShadow({mode:'open'});
            root.innerHTML='<slot name="named"></slot><slot name="named"></slot><slot></slot>';
            const slots=root.querySelectorAll('slot'),first=slots[0],duplicate=slots[1],normal=slots[2];
            const element=document.createElement('span'),text=document.createTextNode('text');
            element.setAttribute('slot','named');host.appendChild(element);host.appendChild(text);
            host.appendChild(document.createComment('not slottable'));
            const checks=[element.assignedSlot===first,text.assignedSlot===normal,
                first.assignedNodes().length===1,first.assignedElements()[0]===element,
                duplicate.assignedNodes().length===0,normal.assignedNodes()[0]===text,
                normal.assignedElements().length===0];
            const snapshot=first.assignedNodes();snapshot.length=0;
            checks.push(first.assignedNodes().length===1);
            first.remove();checks.push(element.assignedSlot===duplicate);
            element.setAttribute('slot','missing');checks.push(element.assignedSlot===null);
            element.removeAttribute('slot');checks.push(element.assignedSlot===normal,
                normal.assignedNodes()[0]===element,normal.assignedNodes()[1]===text);
            const closedHost=document.createElement('div');host.appendChild(closedHost);
            const closed=closedHost.attachShadow({mode:'closed'});closed.innerHTML='<slot></slot>';
            const hiddenSlot=closed.querySelector('slot'),child=document.createElement('i');
            closedHost.appendChild(child);
            checks.push(child.assignedSlot===null,hiddenSlot.assignedNodes()[0]===child);
            return JSON.stringify([checks.length,checks.every(Boolean)]);
        })()"#).unwrap();
        assert_eq!(result, "[15,true]");
    }

    #[test]
    fn slot_flattening_uses_fallback_and_converts_options_before_reading_dom() {
        let mut page = RustExecutableDocument::load("<div id=host></div>").unwrap();
        let result = page.evaluate(r#"(() => {
            const host=document.getElementById('host'),root=host.attachShadow({mode:'open'});
            root.innerHTML='<slot name="outer"><slot name="inner"><b>Fallback</b>text</slot></slot>';
            const outer=root.querySelector('slot'),inner=outer.querySelector('slot'),fallback=inner.querySelector('b');
            const checks=[outer.assignedNodes().length===0,outer.assignedNodes({flatten:true})[0]===fallback,
                outer.assignedNodes({flatten:true}).length===2,outer.assignedElements({flatten:true}).length===1];
            const item=document.createElement('i');item.setAttribute('slot','inner');
            let conversions=0;
            const nodes=outer.assignedNodes({get flatten(){conversions++;host.appendChild(item);return true;}});
            checks.push(conversions===1,nodes.length===1,nodes[0]===item);
            const error=new Error('options');let caught=false;
            try{outer.assignedNodes({get flatten(){throw error;}})}catch(e){caught=e===error}
            checks.push(caught);
            const detached=document.createElement('slot');detached.innerHTML='<b>Detached</b>';
            checks.push(detached.assignedNodes({flatten:true}).length===0);
            return JSON.stringify([checks.length,checks.every(Boolean)]);
        })()"#).unwrap();
        assert_eq!(result, "[9,true]");
    }

    #[test]
    fn nested_shadow_dispatch_retargets_and_hides_closed_paths_after_mutation() {
        let mut page = RustExecutableDocument::load("<div id=host></div>").unwrap();
        let result = page.evaluate(r#"(() => {
            const outer=document.getElementById('host');
            const outerRoot=outer.attachShadow({mode:'closed'});
            const inner=document.createElement('section');outerRoot.appendChild(inner);
            const innerRoot=inner.attachShadow({mode:'open'});
            const button=document.createElement('button');innerRoot.appendChild(button);
            const checks=[];
            const event=new Event('nested',{composed:true,bubbles:true});
            addEventListener('nested',e=>{
                checks.push(e.target===outer,e.composedPath()[0]===outer,
                    !e.composedPath().includes(button),!e.composedPath().includes(outerRoot));
                inner.remove();
            },{capture:true});
            outer.addEventListener('nested',e=>checks.push(e.target===outer,e.eventPhase===2));
            outerRoot.addEventListener('nested',e=>checks.push(e.target===inner,
                e.composedPath()[0]===button,e.composedPath().includes(outerRoot)));
            inner.addEventListener('nested',e=>checks.push(e.target===inner,e.eventPhase===2));
            innerRoot.addEventListener('nested',e=>checks.push(e.target===button));
            button.addEventListener('nested',e=>checks.push(e.target===button,e.eventPhase===2));
            button.dispatchEvent(event);
            checks.push(event.target===outer,event.currentTarget===null,event.composedPath().length===0);
            return JSON.stringify([checks.length,checks.every(Boolean)]);
        })()"#).unwrap();
        assert_eq!(result, "[17,true]");
    }

