    #[test]
    fn event_path_is_captured_before_mutation_and_released_after_dispatch() {
        let mut page = RustExecutableDocument::load(
            "<section id=container><button id=target>Target</button></section>",
        )
        .unwrap();
        let result = page.evaluate(r#"(() => {
            const container=document.getElementById('container'),target=document.getElementById('target');
            const event=new Event('path',{bubbles:true});
            const checks=[];
            addEventListener('path',e=>{
              const path=e.composedPath();
              checks.push(path[0]===target,path[1]===container,path.at(-1)===window);
              path.length=0;
              container.remove();
            },true);
            target.addEventListener('path',e=>{
              const path=e.composedPath();
              checks.push(path[0]===target,path[1]===container,path.includes(document),path.at(-1)===window);
            });
            container.addEventListener('path',e=>checks.push(e.composedPath()[1]===container));
            target.dispatchEvent(event);
            checks.push(event.composedPath().length===0,event.currentTarget===null,event.target===target);
            const globalEvent=new Event('global-path');
            addEventListener('global-path',e=>checks.push(e.composedPath().length===1,e.composedPath()[0]===window));
            dispatchEvent(globalEvent);
            checks.push(globalEvent.composedPath().length===0);
            return String(checks.every(Boolean));
        })()"#).unwrap();
        assert_eq!(result, "true");
    }

    #[test]
    fn foreign_event_keeps_its_owner_while_dispatching_through_target_document() {
        let mut page = RustExecutableDocument::load("<button id=target>Target</button>").unwrap();
        let result = page
            .evaluate(
                r#"(() => {
            const frame=document.createElement('iframe');document.body.append(frame);
            const foreign=frame.contentWindow;
            const target=document.getElementById('target');
            const event=new foreign.Event('probe',{bubbles:true,cancelable:true});
            const unrelated=new Event('unrelated',{cancelable:true});
            const log=[];
            foreign.addEventListener('probe',()=>log.push('wrong-window'));
            addEventListener('probe',e=>log.push('capture:'+String(e.target===target)),true);
            target.addEventListener('probe',e=>{
              log.push('target:'+String(e.currentTarget===target));e.preventDefault();
            });
            addEventListener('probe',e=>log.push('bubble:'+String(e.currentTarget===window)));
            const accepted=target.dispatchEvent(event);
            return JSON.stringify([accepted,event.defaultPrevented,unrelated.defaultPrevented,
              event.target===target,event.currentTarget===null,event instanceof foreign.Event,log]);
        })()"#,
            )
            .unwrap();
        assert_eq!(
            result,
            r#"[false,true,false,true,true,true,["capture:true","target:true","bubble:true"]]"#
        );
    }

