    #[test]
    fn buffered_publication_rejects_late_invalid_sources_without_allocating() {
        for malformed_event in [false, true] {
            let dom = Rc::new(RefCell::new(
                html::parse("<body><p id=retained>original</p></body>")
                    .into_runtime()
                    .unwrap(),
            ));
            let root = dom.borrow().document();
            let retained = dom.borrow().find_by_id("retained").unwrap();
            let before = dom.borrow().arena().iter().count();
            let mut parsed = oryn_dom::xml::parse_navigation(
                "<replacement><child/></replacement>",
                Some("application/xml"),
                "https://example.test/",
            );
            if malformed_event {
                let foreign = parsed.dom.insert(oryn_dom::NodeKind::Text {
                    data: "unattached".into(),
                });
                parsed
                    .events
                    .push(html::ParserEvent::InlineStyleReady { node: foreign });
            } else {
                // Valid first root, then a duplicate edge: no first-root import
                // may occur before rejection of the later malformed entry.
                let first = parsed.dom.get(parsed.document).unwrap().children[0];
                parsed
                    .dom
                    .get_mut(parsed.document)
                    .unwrap()
                    .children
                    .push(first);
            }
            assert!(publish_buffered_navigation_document(&dom, parsed).is_err());
            let target = dom.borrow();
            assert_eq!(target.arena().iter().count(), before);
            assert_eq!(target.document(), root);
            assert_eq!(target.find_by_id("retained"), Some(retained));
            assert!(target.is_connected(retained).unwrap());
        }
    }

    #[test]
    fn buffered_navigation_limit_releases_source_and_input_at_overflow() {
        struct Input {
            chunks: std::collections::VecDeque<String>,
            dropped: Rc<Cell<bool>>,
        }
        impl crate::host::DocumentInput for Input {
            fn poll_next(&mut self) -> std::task::Poll<Option<Result<String, HostError>>> {
                std::task::Poll::Ready(self.chunks.pop_front().map(Ok))
            }
        }
        impl Drop for Input {
            fn drop(&mut self) {
                self.dropped.set(true);
            }
        }
        let dropped = Rc::new(Cell::new(false));
        let stream = crate::host::DocumentStream {
            content_language: None,
            chunks: Box::new(Input {
                chunks: vec!["<root>".into(), "oversized".into()].into(),
                dropped: dropped.clone(),
            }),
            content_type: Some("application/xml".into()),
            encoding: Default::default(),
        };
        let mut input = BufferedNavigationInput::new(stream, "https://example.test/".into(), 8);
        assert!(input.poll().is_pending());
        assert_eq!(input.source.len(), 6);
        assert!(matches!(
            input.poll(),
            std::task::Poll::Ready(Err(HostError::LimitExceeded { .. }))
        ));
        assert!(dropped.get());
        assert!(input.stream.is_none());
        assert_eq!(input.source.capacity(), 0);
        assert!(matches!(
            input.poll(),
            std::task::Poll::Ready(Err(HostError::Execution(_)))
        ));
    }

    #[test]
    fn scheduled_xml_preserves_document_and_retained_node_wrappers_across_publication() {
        struct Input {
            ready: Rc<Cell<bool>>,
            polls: Rc<Cell<usize>>,
            sent: bool,
        }
        impl crate::host::DocumentInput for Input {
            fn poll_next(&mut self) -> std::task::Poll<Option<Result<String, HostError>>> {
                self.polls.set(self.polls.get() + 1);
                if !self.ready.get() {
                    return std::task::Poll::Pending;
                }
                if self.sent {
                    return std::task::Poll::Ready(None);
                }
                self.sent = true;
                std::task::Poll::Ready(Some(Ok(
                    "<root xmlns='urn:fixture'><item>value</item></root>".into(),
                )))
            }
        }
        let ready = Rc::new(Cell::new(false));
        let polls = Rc::new(Cell::new(0));
        let stream = crate::host::DocumentStream {
            content_language: None,
            chunks: Box::new(Input {
                ready: ready.clone(),
                polls: polls.clone(),
                sent: false,
            }),
            content_type: Some("application/xml".into()),
            encoding: Default::default(),
        };
        let mut page = RustExecutableDocument::load_stream_with_limits(
            stream,
            &BTreeMap::new(),
            None,
            Some(Url::parse("https://example.test/document.xml").unwrap()),
            256 * 1024 * 1024,
            true,
        )
        .unwrap();
        assert_eq!(polls.get(), 0);
        assert!(page.parser_pending());
        page.execute("globalThis.savedDocument=document;globalThis.retained=document.createElement('retained');document.appendChild(retained)").unwrap();
        page.poll_context_events().unwrap();
        assert!(page.parser_pending());
        ready.set(true);
        page.poll_context_events().unwrap();
        assert!(page.parser_pending());
        assert_eq!(
            page.evaluate("document.documentElement===retained")
                .unwrap(),
            "true"
        );
        for _ in 0..16 {
            page.poll_context_events().unwrap();
            if !page.parser_pending() {
                break;
            }
        }
        assert!(!page.parser_pending());
        assert_eq!(page.evaluate("savedDocument===document&&retained.nodeName==='retained'&&!retained.isConnected&&document.documentElement.namespaceURI==='urn:fixture'&&document.documentElement.localName==='root'").unwrap(),"true");
        assert_eq!(
            page.evaluate("document.contentType").unwrap(),
            "application/xml"
        );
        assert_eq!(
            page.evaluate("document.URL").unwrap(),
            "https://example.test/document.xml"
        );
        assert!(page.document_load_complete());
    }

    #[test]
    fn buffered_xml_event_slices_yield_to_page_work_and_stop() {
        for stopped in [false, true] {
            let mut source = String::from("<root>");
            for _ in 0..600 {
                source.push_str("<item>value</item>");
            }
            source.push_str("</root>");
            let stream = crate::host::DocumentStream {
                content_language: None,
                chunks: Box::new(crate::host::ReadyDocumentInput(std::iter::once(Ok(source)))),
                content_type: Some("application/xml".into()),
                encoding: Default::default(),
            };
            let mut page = RustExecutableDocument::load_stream_with_limits(
                stream,
                &BTreeMap::new(),
                None,
                Some(Url::parse("https://example.test/sliced.xml").unwrap()),
                256 * 1024 * 1024,
                true,
            )
            .unwrap();
            for _ in 0..4 {
                page.resume_pending_parser().unwrap();
            }
            assert!(page.has_runnable_page_work());
            assert!(
                page.frame_script_preparations
                    .iter()
                    .any(|owner| owner.root_parser_pending())
            );
            page.execute("globalThis.betweenXmlSlices=42").unwrap();
            assert_eq!(page.evaluate("betweenXmlSlices").unwrap(), "42");
            if stopped {
                let count = {
                    let dom = page.agent.dom.borrow();
                    dom.query_selector_all(dom.document(), "item")
                        .unwrap()
                        .len()
                };
                page.stop_pending_document_load().unwrap();
                assert!(page.pending_buffered.is_none());
                assert!(
                    !page
                        .frame_script_preparations
                        .iter()
                        .any(|owner| owner.root_parser_pending())
                );
                assert!(!page.document_load_complete());
                page.poll_frame_script_preparations().unwrap();
                let dom = page.agent.dom.borrow();
                assert_eq!(
                    dom.query_selector_all(dom.document(), "item")
                        .unwrap()
                        .len(),
                    count,
                    "stop preserves published prefix and prevents suffix publication"
                );
            } else {
                for _ in 0..32 {
                    if !page.parser_pending() {
                        break;
                    }
                    page.resume_pending_parser().unwrap();
                }
                assert!(!page.parser_pending());
                assert!(page.document_load_complete());
                let dom = page.agent.dom.borrow();
                assert_eq!(
                    dom.query_selector_all(dom.document(), "item")
                        .unwrap()
                        .len(),
                    600
                );
            }
        }
    }

    #[test]
    fn buffered_import_remaps_parser_events_without_reusing_existing_nodes() {
        let page = RustExecutableDocument::load("<p id=old>old</p>").unwrap();
        let dom = page.agent.dom.clone();
        let old = dom.borrow().find_by_id("old").unwrap();
        let root = dom.borrow().document();
        let parsed = html::parse(
            "<style id=sheet>body{color:green}</style><script id=script>void 0</script><iframe id=frame src='/child'></iframe>",
        );
        let published = publish_buffered_navigation_document(&dom, parsed).unwrap();
        assert_eq!(published.document, root);
        assert!(!dom.borrow().is_connected(old).unwrap());
        assert_eq!(dom.borrow().arena().text_content(old).unwrap(), "old");
        let mut scripts = 0;
        let mut frames = 0;
        for event in published.events {
            match event {
                html::ParserEvent::ScriptReady { node, .. } => {
                    scripts += 1;
                    assert_eq!(dom.borrow().find_by_id("script"), Some(node));
                    assert_ne!(node, old);
                }
                html::ParserEvent::FrameDiscovered { node, .. } => {
                    frames += 1;
                    assert_eq!(dom.borrow().find_by_id("frame"), Some(node));
                    assert_ne!(node, old);
                }
                _ => {}
            }
        }
        assert_eq!(scripts, 1);
        assert_eq!(frames, 1);
    }

