    #[test]
    #[cfg(unix)]
    fn parser_worker_replies_keep_preparations_on_the_isolate() {
        fn assert_send<T: Send>() {}
        assert_send::<ParserResourceCompletion<u64>>();
        let page =
            RustExecutableDocument::load("<script id=pending type=application/json>{}</script>")
                .unwrap();
        let node = page.node_by_id("pending").unwrap();
        let dom = page.agent.dom.clone();
        let record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
        let identity = record.7.unwrap();
        let target = Rc::downgrade(record.8.target.as_ref().unwrap());
        let mut scheduler = ParserResourceScheduler::new();
        let first = scheduler.retain_preparation(record.clone()).unwrap();
        let retry = scheduler.retain_preparation(record).unwrap();
        assert_ne!(first, retry);
        scheduler.pending = 2;
        let reply = move |ticket| ParserResourceCompletion::Script {
            realm: identity.realm,
            stream_epoch: identity.stream_epoch,
            document_generation: identity.document_generation,
            document: identity.document,
            order: 7,
            record: ticket,
            asynchronous: false,
            result: Err(ParserScriptFailure::Infrastructure(
                "test fetch failure".into(),
            )),
        };
        let sender = scheduler.sender.clone();
        // The real channel crosses a worker boundary; neither the target lease
        // nor its parser context is captured by this worker.
        let worker_reply = reply(first);
        assert!(
            std::thread::spawn(move || sender.send(worker_reply).is_ok())
                .join()
                .unwrap()
        );
        let completion = scheduler.try_next().unwrap();
        assert_eq!(scheduler.pending, 1);
        assert!(target.upgrade().is_some());
        drop(completion);
        scheduler.receive_reply(reply(first));
        assert!(scheduler.try_next().is_none());
        assert!(scheduler.preparations.contains_key(&retry));
        assert_eq!(scheduler.pending, 1);
        let sender = scheduler.sender.clone();
        drop(scheduler);
        assert!(
            target.upgrade().is_none(),
            "retirement releases isolate-owned preparations"
        );
        assert!(
            sender.send(reply(retry)).is_err(),
            "late replies cannot resurrect a retired owner"
        );
    }

    #[test]
    #[cfg(unix)]
    fn parser_scheduler_completion_and_drop_cancel_only_owned_script_leases() {
        use crate::context_service::{
            ContextServiceRequest, ContextServiceResponse, ContextTransport,
        };
        struct CancellationService(std::sync::mpsc::Sender<u64>);
        impl ContextTransport for CancellationService {
            fn request(
                &self,
                request: ContextServiceRequest,
            ) -> Result<ContextServiceResponse, crate::RuntimeError> {
                match request {
                    ContextServiceRequest::CancelScriptLoad { token, .. } => {
                        self.0.send(token).unwrap();
                        Ok(ContextServiceResponse::ScriptLoadCancelled)
                    }
                    _ => Err(crate::RuntimeError::ContextService(
                        "unexpected test request".into(),
                    )),
                }
            }
        }
        let (worker, parent) = std::os::unix::net::UnixStream::pair().unwrap();
        let shutdown = parent.try_clone().unwrap();
        let (sent, received) = std::sync::mpsc::channel();
        let server = std::thread::spawn(move || {
            crate::context_service::serve_context_transport(
                parent,
                std::sync::Arc::new(CancellationService(sent)),
            )
        });
        let client = crate::context_service::SharedContextClient::new(
            crate::context_service::IpcContextClient::new(worker),
        );
        let page =
            RustExecutableDocument::load("<script id=pending type=application/json>{}</script>")
                .unwrap();
        let node = page.node_by_id("pending").unwrap();
        let dom = page.agent.dom.clone();
        let record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
        let identity = record.7.unwrap();
        let mut scheduler = ParserResourceScheduler::new();
        for order in [11, 12] {
            scheduler.script_leases.insert(
                order,
                std::sync::Arc::new(std::sync::Mutex::new(Some(
                    crate::context_service::ContextScriptLoad::from_reserved(
                        client.clone(),
                        oryn_common::v3::PageId(1),
                        order,
                    ),
                ))),
            );
        }
        scheduler.pending = 2;
        assert!(scheduler.try_next().is_none());
        assert!(received.try_recv().is_err());
        let ticket = scheduler.retain_preparation(record).unwrap();
        scheduler
            .sender
            .send(ParserResourceCompletion::Script {
                realm: identity.realm,
                stream_epoch: identity.stream_epoch,
                document_generation: identity.document_generation,
                document: identity.document,
                order: 11,
                record: ticket,
                asynchronous: false,
                result: Err("fetch failed".into()),
            })
            .ok()
            .unwrap();
        assert!(scheduler.try_next().is_some());
        assert_eq!(
            received
                .recv_timeout(std::time::Duration::from_secs(5))
                .unwrap(),
            11
        );
        assert_eq!(scheduler.pending, 1);
        assert_eq!(
            scheduler.script_leases.keys().copied().collect::<Vec<_>>(),
            vec![12]
        );
        drop(scheduler);
        assert_eq!(
            received
                .recv_timeout(std::time::Duration::from_secs(5))
                .unwrap(),
            12
        );
        client.drain_script_cleanup(Duration::from_secs(5)).unwrap();
        shutdown.shutdown(std::net::Shutdown::Both).unwrap();
        let _ = server.join().unwrap();
    }

    #[test]
    #[cfg(unix)]
    fn standalone_parser_source_and_graph_tasks_preserve_order_and_aliases() {
        let resources = BTreeMap::from([
            ("classic.js".into(), "order.push('classic')".into()),
            ("oryn:module-alias:entry.js".into(), "entry-final.js".into()),
            (
                "entry-final.js".into(),
                "import {value} from './dependency.js';order.push(value)".into(),
            ),
            ("dependency.js".into(), "export const value='module'".into()),
        ]);
        let source = "<script>globalThis.order=['before']</script><script src=classic.js></script><script>order.push('after')</script><script type=module src=entry.js></script><script type=module>order.push('inline-module')</script>";
        for snapshot in [false, true] {
            let mut page = if snapshot {
                RustExecutableDocument::load_parsed_with_limits(
                    html::parse(source),
                    &resources,
                    None,
                    Some(Url::parse("https://example.test/page").unwrap()),
                    256 * 1024 * 1024,
                )
            } else {
                RustExecutableDocument::load_with_environment(
                    source,
                    &resources,
                    None,
                    Some(Url::parse("https://example.test/page").unwrap()),
                )
            }
            .unwrap();
            assert_eq!(
                page.agent.host.evaluate_string("order.join(',')").unwrap(),
                "before,classic,after,module,inline-module",
                "snapshot={snapshot}, diagnostics={:?}",
                page.diagnostics
            );
            assert!(page.diagnostics.is_empty(), "{:?}", page.diagnostics);
            assert!(!page.parser_pending());
        }
    }

    #[test]
    #[cfg(unix)]
    fn prepared_document_module_linking_cannot_fall_back_to_broker_io() {
        use std::sync::{
            Arc,
            atomic::{AtomicUsize, Ordering},
        };
        struct Forbidden(Arc<AtomicUsize>);
        impl crate::network::NetworkBroker for Forbidden {
            fn send(
                &self,
                request: crate::network::NetworkRequest,
            ) -> Result<crate::network::NetworkResponse, crate::network::NetworkError> {
                self.0.fetch_add(1, Ordering::AcqRel);
                Ok(crate::network::NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/javascript".into())],
                    body: b"globalThis.missedPreparationRan=true".to_vec(),
                })
            }
        }
        let calls = Arc::new(AtomicUsize::new(0));
        let mut page = RustExecutableDocument::load_with_environment(
            "<body>",
            &BTreeMap::new(),
            Some(SharedNetworkBroker::new(Forbidden(calls.clone()))),
            Some(Url::parse("https://example.test/").unwrap()),
        )
        .unwrap();
        let _ = page.agent.host.execute_module_script_for_request(
            "https://example.test/root.js",
            "import './missing.js'",
            &BTreeMap::new(),
            None,
        );
        assert_eq!(calls.load(Ordering::Acquire), 0);
        assert_eq!(
            page.agent
                .host
                .evaluate_string("typeof missedPreparationRan")
                .unwrap(),
            "undefined"
        );
        // The execution guard is scoped; a later queued import still uses its
        // normal retained loader rather than inheriting the completed guard.
        page.agent
            .host
            .execute("import('./later.js').catch(()=>{})")
            .unwrap();
        assert!(page.agent.host.has_pending_page_work());
    }

    #[test]
    #[cfg(unix)]
    fn standalone_scheduled_parser_yields_to_tasks_while_classic_headers_are_held() {
        use std::sync::{Mutex, mpsc};
        struct Held {
            started: mpsc::Sender<()>,
            release: Mutex<mpsc::Receiver<()>>,
        }
        impl crate::network::NetworkBroker for Held {
            fn send(
                &self,
                request: crate::network::NetworkRequest,
            ) -> Result<crate::network::NetworkResponse, crate::network::NetworkError> {
                self.started.send(()).unwrap();
                self.release.lock().unwrap().recv().unwrap();
                Ok(crate::network::NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/javascript".into())],
                    body: b"order.push('external')".to_vec(),
                })
            }
        }
        let (started, observed) = mpsc::channel();
        let (release, blocked) = mpsc::channel();
        let broker = SharedNetworkBroker::new(Held {
            started,
            release: Mutex::new(blocked),
        });
        let input=DocumentStream::html(Box::new(std::iter::once(Ok("<script>globalThis.order=['before']</script><script src=held.js></script><script>order.push('after')</script>".into()))));
        let mut page = RustExecutableDocument::load_stream_with_limits(
            input,
            &BTreeMap::new(),
            Some(broker),
            Some(Url::parse("https://example.test/").unwrap()),
            256 * 1024 * 1024,
            true,
        )
        .unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        loop {
            page.poll_context_events().unwrap();
            if observed.try_recv().is_ok() {
                break;
            }
            assert!(std::time::Instant::now() < deadline);
            std::thread::yield_now();
        }
        assert!(page.parser_pending());
        page.agent
            .host
            .execute("order.push('unrelated-task')")
            .unwrap();
        page.checkpoint().unwrap();
        assert_eq!(
            page.agent.host.evaluate_string("order.join(',')").unwrap(),
            "before,unrelated-task"
        );
        release.send(()).unwrap();
        while page.parser_pending() {
            page.checkpoint().unwrap();
            assert!(std::time::Instant::now() < deadline);
            std::thread::yield_now();
        }
        assert_eq!(
            page.agent.host.evaluate_string("order.join(',')").unwrap(),
            "before,unrelated-task,external,after"
        );
    }

    #[test]
    #[cfg(unix)]
    fn standalone_parser_source_cancellation_keeps_old_record_out_of_replacement() {
        use std::sync::{Mutex, mpsc};
        struct Held {
            started: mpsc::Sender<()>,
            release: Mutex<mpsc::Receiver<()>>,
        }
        impl crate::network::NetworkBroker for Held {
            fn send(
                &self,
                request: crate::network::NetworkRequest,
            ) -> Result<crate::network::NetworkResponse, crate::network::NetworkError> {
                self.started.send(()).unwrap();
                self.release.lock().unwrap().recv().unwrap();
                Ok(crate::network::NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/javascript".into())],
                    body: b"globalThis.staleExecuted=true".to_vec(),
                })
            }
        }
        let (started, observed) = mpsc::channel();
        let (release, blocked) = mpsc::channel();
        let mut page = RustExecutableDocument::load_with_environment(
            "<script id=pending type=application/json>{}</script>",
            &BTreeMap::new(),
            Some(SharedNetworkBroker::new(Held {
                started,
                release: Mutex::new(blocked),
            })),
            Some(Url::parse("https://example.test/").unwrap()),
        )
        .unwrap();
        let dom = page.agent.dom.clone();
        let node = page.node_by_id("pending").unwrap();
        let mut record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
        record.1 = Some("held.js".into());
        record.2 = None;
        let mut scheduler = ParserResourceScheduler::with_page_limits(&page.dynamic_scripts);
        let fetch = ParserFetchContext::capture(&page.agent.host, &dom, node).unwrap();
        scheduler
            .schedule_script_auto(None, 0, record, false, fetch, &mut page.agent.host)
            .unwrap();
        observed.recv_timeout(Duration::from_secs(5)).unwrap();
        let cancellation = scheduler.local_source_cancels.get(&0).unwrap().0.clone();
        page.agent
            .host
            .execute("document.open();document.write('<p id=new>replacement</p>');document.close()")
            .unwrap();
        drop(scheduler);
        assert!(cancellation.load(std::sync::atomic::Ordering::Acquire));
        release.send(()).unwrap();
        page.checkpoint().unwrap();
        assert_eq!(
            page.agent
                .host
                .evaluate_string(
                    "typeof staleExecuted+'|'+document.getElementById('new').textContent"
                )
                .unwrap(),
            "undefined|replacement"
        );
    }

    #[test]
    #[cfg(unix)]
    fn parser_auto_admission_rejects_missing_and_wrong_page_endpoints_before_queuing() {
        let mut page =
            RustExecutableDocument::load("<script id=pending type=application/json>{}</script>")
                .unwrap();
        let dom = page.agent.dom.clone();
        let node = page.node_by_id("pending").unwrap();
        use crate::context_service::{
            ContextServiceRequest as Q, ContextServiceResponse as R, ContextTransport,
        };
        struct RegistrationOnly(std::sync::Arc<std::sync::Mutex<Vec<String>>>);
        impl ContextTransport for RegistrationOnly {
            fn request(&self, request: Q) -> Result<R, crate::RuntimeError> {
                match request {
                    Q::MessageWire {
                        source_page_id: oryn_common::v3::PageId(2),
                        request:
                            oryn_js::message_wire::MessageRequest::RegisterRootDocument { .. }
                            | oryn_js::message_wire::MessageRequest::RetireRootDocument { .. },
                    } => Ok(R::MessageWire {
                        result: Ok(oryn_js::message_wire::MessageResponse::Done),
                    }),
                    unexpected => {
                        let message =
                            format!("unexpected admission fixture request: {unexpected:?}");
                        self.0.lock().unwrap().push(message.clone());
                        Err(crate::RuntimeError::ContextService(message))
                    }
                }
            }
        }
        let (worker, parent) = std::os::unix::net::UnixStream::pair().unwrap();
        struct ShutdownOnDrop(std::os::unix::net::UnixStream);
        impl Drop for ShutdownOnDrop {
            fn drop(&mut self) {
                let _ = self.0.shutdown(std::net::Shutdown::Both);
            }
        }
        let shutdown = ShutdownOnDrop(parent.try_clone().unwrap());
        let unexpected = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let observed = unexpected.clone();
        let server = std::thread::spawn(move || {
            crate::context_service::serve_context_transport(
                parent,
                std::sync::Arc::new(RegistrationOnly(observed)),
            )
        });
        let client = crate::context_service::SharedContextClient::new(
            crate::context_service::IpcContextClient::new(worker),
        );
        let context = (client.clone(), oryn_common::v3::PageId(1), None);
        let mut scheduler = ParserResourceScheduler::new();
        for install_wrong_page in [false, true] {
            if install_wrong_page {
                page.agent.host.install_test_resource_endpoint(
                    page.top_realm,
                    client.clone(),
                    oryn_common::v3::PageId(2),
                );
            }
            let mut record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
            record.1 = Some("https://example.test/pending.js".into());
            record.2 = None;
            let fetch = ParserFetchContext::capture(&page.agent.host, &dom, node).unwrap();
            assert!(
                scheduler
                    .schedule_script_auto(
                        Some(&context),
                        0,
                        record,
                        false,
                        fetch,
                        &mut page.agent.host
                    )
                    .is_err()
            );
            assert_eq!(scheduler.pending, 0);
            assert!(scheduler.script_leases.is_empty());
            assert!(scheduler.module_sources.is_empty());
            assert_eq!(client.resource_job_activity(), (0, None));
        }
        // Retire while the exact lifecycle responder is still serving.
        drop(page);
        drop(shutdown);
        server.join().unwrap().unwrap();
        let unexpected = unexpected.lock().unwrap();
        assert!(unexpected.is_empty(), "{unexpected:?}");
    }

    #[test]
    #[cfg(unix)]
    fn parser_module_roots_keep_independent_records_and_adopt_shared_response() {
        let mut page=RustExecutableDocument::load("<script id=a type=application/json>{}</script><script id=b type=application/json>{}</script>").unwrap();
        let dom = page.agent.dom.clone();
        let url = "https://example.test/shared.js";
        let (worker, parent) = std::os::unix::net::UnixStream::pair().unwrap();
        let client = crate::context_service::SharedContextClient::new(
            crate::context_service::IpcContextClient::new(worker),
        );
        let mut scheduler = ParserResourceScheduler::new();
        for (order, id) in [(0, "a"), (1, "b")] {
            let node = page.node_by_id(id).unwrap();
            let mut record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
            record.1 = Some(url.into());
            record.2 = Some("module".into());
            let fetch = ParserFetchContext::capture(&page.agent.host, &dom, node).unwrap();
            scheduler
                .schedule_script(ParserScriptScheduleInput {
                    client: client.clone(),
                    page_id: oryn_common::v3::PageId(1),
                    order,
                    record,
                    asynchronous: order == 1,
                    fetch,
                    host: &mut page.agent.host,
                })
                .unwrap();
        }
        assert_eq!(scheduler.module_sources.len(), 2);
        assert!(scheduler.script_leases.is_empty());
        // A graph/import consumer publishes the shared first response before
        // these parser sources get their next task; neither sends a new fetch.
        page.agent
            .host
            .retain_verified_module_fetch(url, url, "export const value=42")
            .unwrap();
        for order in 0..2 {
            let Some(ParserResourceCompletion::Script {
                order: actual,
                result: Ok(source),
                asynchronous,
                ..
            }) = scheduler.try_next_with_host(&mut page.agent.host)
            else {
                panic!("retained source completion")
            };
            assert_eq!(actual, order);
            assert_eq!(asynchronous, order == 1);
            assert_eq!(source.source, "export const value=42");
        }
        assert_eq!(scheduler.pending, 0);
        assert!(scheduler.module_sources.is_empty());
        parent.set_nonblocking(true).unwrap();
        assert_eq!(
            std::io::Read::read(&mut &parent, &mut [0])
                .unwrap_err()
                .kind(),
            std::io::ErrorKind::WouldBlock
        );
    }

    #[test]
    #[cfg(unix)]
    fn parser_dynamic_root_and_import_share_fetch_after_parser_cancellation() {
        use std::sync::{
            Arc, Mutex,
            atomic::{AtomicUsize, Ordering},
            mpsc,
        };
        struct Held {
            calls: Arc<AtomicUsize>,
            started: mpsc::Sender<()>,
            release: Mutex<mpsc::Receiver<()>>,
        }
        impl crate::network::NetworkBroker for Held {
            fn send(
                &self,
                request: crate::network::NetworkRequest,
            ) -> Result<crate::network::NetworkResponse, crate::network::NetworkError> {
                self.calls.fetch_add(1, Ordering::AcqRel);
                self.started
                    .send(())
                    .map_err(|error| crate::network::NetworkError::Transport(error.to_string()))?;
                self.release
                    .lock()
                    .map_err(|error| crate::network::NetworkError::Transport(error.to_string()))?
                    .recv_timeout(Duration::from_secs(5))
                    .map_err(|error| crate::network::NetworkError::Transport(error.to_string()))?;
                Ok(crate::network::NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/javascript".into())],
                    body:
                        b"globalThis.executions=(globalThis.executions||0)+1;export const value=42"
                            .to_vec(),
                })
            }
        }
        let calls = Arc::new(AtomicUsize::new(0));
        let (started, observed) = mpsc::channel();
        let (release, blocked) = mpsc::channel();
        let broker = SharedNetworkBroker::new(Held {
            calls: calls.clone(),
            started,
            release: Mutex::new(blocked),
        });
        let mut page = RustExecutableDocument::load_with_environment(
            "<body><script id=parser type=application/json>{}</script>",
            &BTreeMap::new(),
            Some(broker),
            Some(Url::parse("https://example.test/").unwrap()),
        )
        .unwrap();
        page.agent
            .host
            .execute("import('./shared.js').then(m=>globalThis.imported=m.value)")
            .unwrap();
        page.agent.host.drain_async_fetches(false).unwrap();
        observed.recv_timeout(Duration::from_secs(5)).unwrap();
        let dom = page.agent.dom.clone();
        let node = page.node_by_id("parser").unwrap();
        let mut record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
        record.1 = Some("https://example.test/shared.js".into());
        record.2 = Some("module".into());
        let fetch = ParserFetchContext::capture(&page.agent.host, &dom, node).unwrap();
        use crate::context_service::{
            ContextServiceRequest as Q, ContextServiceResponse as R, ContextTransport,
        };
        struct Admission {
            observed: mpsc::Sender<Q>,
            release: Mutex<mpsc::Receiver<()>>,
        }
        impl ContextTransport for Admission {
            fn request(&self, request: Q) -> Result<R, crate::RuntimeError> {
                let reserve = matches!(&request, Q::ReserveScriptLoad { .. });
                let cancel = matches!(&request, Q::CancelScriptLoad { .. });
                self.observed
                    .send(request)
                    .map_err(|error| crate::RuntimeError::ContextService(error.to_string()))?;
                if reserve {
                    self.release
                        .lock()
                        .map_err(|error| crate::RuntimeError::ContextService(error.to_string()))?
                        .recv_timeout(Duration::from_secs(5))
                        .map_err(|error| crate::RuntimeError::ContextService(error.to_string()))?;
                    Ok(R::ScriptLoadReserved { token: 73 })
                } else if cancel {
                    Ok(R::ScriptLoadCancelled)
                } else {
                    Err(crate::RuntimeError::ContextService(
                        "unexpected parser payload after canceled admission".into(),
                    ))
                }
            }
        }
        let (worker, parent) = std::os::unix::net::UnixStream::pair().unwrap();
        struct ShutdownOnDrop(std::os::unix::net::UnixStream);
        impl Drop for ShutdownOnDrop {
            fn drop(&mut self) {
                let _ = self.0.shutdown(std::net::Shutdown::Both);
            }
        }
        let shutdown = ShutdownOnDrop(parent.try_clone().unwrap());
        let (admitted, requests) = mpsc::channel();
        let (allow, wait) = mpsc::channel();
        let server = std::thread::spawn(move || {
            crate::context_service::serve_context_transport(
                parent,
                Arc::new(Admission {
                    observed: admitted,
                    release: Mutex::new(wait),
                }),
            )
        });
        let client = crate::context_service::SharedContextClient::new(
            crate::context_service::IpcContextClient::new(worker),
        );
        let mut parser = ParserResourceScheduler::with_page_limits(&page.dynamic_scripts);
        parser
            .schedule_script(ParserScriptScheduleInput {
                client: client.clone(),
                page_id: oryn_common::v3::PageId(1),
                order: 0,
                record,
                asynchronous: false,
                fetch,
                host: &mut page.agent.host,
            })
            .unwrap();
        assert!(parser.try_next_with_host(&mut page.agent.host).is_none());
        page.agent.host.execute("const s=document.createElement('script');s.type='module';s.src='./shared.js';s.onload=()=>globalThis.dynamicLoaded=true;document.body.append(s)").unwrap();
        page.drain_dynamic_scripts().unwrap();
        page.drain_dynamic_scripts().unwrap();
        // Parser CSP provenance requires a separate native admission even while
        // the non-parser import shares its one pending payload with dynamic script.
        match requests.recv_timeout(Duration::from_secs(5)).unwrap() {
            Q::ReserveScriptLoad { page_id, creator } => {
                assert_eq!(page_id, oryn_common::v3::PageId(1));
                assert_eq!(creator, page.agent.host.native_script_creator().unwrap());
            }
            unexpected => panic!("expected parser admission, received {unexpected:?}"),
        }
        assert_eq!(calls.load(Ordering::Acquire), 1);
        drop(parser);
        allow.send(()).unwrap();
        match requests.recv_timeout(Duration::from_secs(5)).unwrap() {
            Q::CancelScriptLoad { page_id, token } => {
                assert_eq!(page_id, oryn_common::v3::PageId(1));
                assert_eq!(token, 73);
            }
            unexpected => {
                panic!("late reservation must cancel without starting payload: {unexpected:?}")
            }
        }
        release.send(()).unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        loop {
            page.checkpoint().unwrap();
            if page
                .agent
                .host
                .evaluate_string(
                    "typeof imported!=='undefined'&&typeof dynamicLoaded!=='undefined'",
                )
                .unwrap()
                == "true"
            {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "shared module consumers did not complete"
            );
            std::thread::yield_now();
        }
        assert_eq!(
            page.agent
                .host
                .evaluate_string("imported+'|'+executions")
                .unwrap(),
            "42|1"
        );
        assert_eq!(calls.load(Ordering::Acquire), 1);
        client.drain_script_cleanup(Duration::from_secs(5)).unwrap();
        let (active, last_activity) = client.resource_job_activity();
        assert_eq!(active, 0, "canceled admission releases custody after ACK");
        assert!(
            last_activity.is_some_and(|changed| changed <= std::time::Instant::now()),
            "completed network custody retains a valid activity timestamp"
        );
        assert_eq!(
            client.resource_job_activity(),
            (active, last_activity),
            "inspection preserves the settled timestamp"
        );
        assert!(
            matches!(requests.try_recv(), Err(mpsc::TryRecvError::Empty)),
            "canceled parser must not send RunScriptLoad"
        );
        drop(shutdown);
        server.join().unwrap().unwrap();
    }

    #[test]
    #[cfg(unix)]
    fn parser_module_roots_reuse_cached_success_and_failure_without_broker_admission() {
        let (worker, parent) = std::os::unix::net::UnixStream::pair().unwrap();
        let client = crate::context_service::SharedContextClient::new(
            crate::context_service::IpcContextClient::new(worker),
        );
        let mut page =
            RustExecutableDocument::load("<script id=pending type=application/json>{}</script>")
                .unwrap();
        let node = page.node_by_id("pending").unwrap();
        let dom = page.agent.dom.clone();
        let requested = "https://example.test/root.js";
        let failed = "https://example.test/failed.js";
        page.agent
            .host
            .retain_verified_module_fetch(
                requested,
                "https://example.test/redirect/root.js",
                "export {};",
            )
            .unwrap();
        page.agent.host.set_module_referrer_policy(
            "https://example.test/redirect/root.js",
            "no-referrer",
            false,
        );
        page.agent.host.retain_failed_module_fetch(failed).unwrap();
        let mut scheduler = ParserResourceScheduler::new();
        for (order, url) in [(0, requested), (1, failed)] {
            let mut record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
            record.1 = Some(url.into());
            record.2 = Some("module".into());
            let fetch = ParserFetchContext::capture(&page.agent.host, &dom, node).unwrap();
            scheduler
                .schedule_script(ParserScriptScheduleInput {
                    client: client.clone(),
                    page_id: oryn_common::v3::PageId(1),
                    order,
                    record,
                    asynchronous: false,
                    fetch,
                    host: &mut page.agent.host,
                })
                .unwrap();
            assert!(scheduler.script_leases.is_empty());
            let ParserResourceCompletion::Script { result, .. } = scheduler.try_next().unwrap()
            else {
                panic!("wrong completion kind");
            };
            if order == 0 {
                let loaded = result.unwrap();
                assert_eq!(loaded.url, "https://example.test/redirect/root.js");
                assert_eq!(loaded.source, "export {};");
                assert_eq!(loaded.referrer_policy, "no-referrer");
            } else {
                assert!(result.is_err());
            }
            assert_eq!(scheduler.pending, 0);
        }
        assert_eq!(
            scheduler
                .source_bytes
                .load(std::sync::atomic::Ordering::Acquire),
            0
        );
        parent.set_nonblocking(true).unwrap();
        assert_eq!(
            std::io::Read::read(&mut &parent, &mut [0])
                .unwrap_err()
                .kind(),
            std::io::ErrorKind::WouldBlock
        );
    }

    #[test]
    #[cfg(unix)]
    fn parser_admission_returns_before_broker_reply_and_cancels_a_late_token() {
        use crate::context_service::{
            ContextServiceRequest, ContextServiceResponse, ContextTransport,
        };
        use std::sync::{
            Arc, Mutex,
            atomic::{AtomicUsize, Ordering},
            mpsc,
        };
        struct AdmissionService {
            entered: mpsc::Sender<()>,
            release: Mutex<mpsc::Receiver<()>>,
            cancelled: mpsc::Sender<u64>,
            runs: Arc<AtomicUsize>,
        }
        impl ContextTransport for AdmissionService {
            fn request(
                &self,
                request: ContextServiceRequest,
            ) -> Result<ContextServiceResponse, crate::RuntimeError> {
                match request {
                    ContextServiceRequest::ReserveScriptLoad { .. } => {
                        self.entered.send(()).unwrap();
                        self.release.lock().unwrap().recv().unwrap();
                        Ok(ContextServiceResponse::ScriptLoadReserved { token: 71 })
                    }
                    ContextServiceRequest::CancelScriptLoad { token, .. } => {
                        self.cancelled.send(token).unwrap();
                        Ok(ContextServiceResponse::ScriptLoadCancelled)
                    }
                    ContextServiceRequest::RunScriptLoad { .. } => {
                        self.runs.fetch_add(1, Ordering::AcqRel);
                        Err(crate::RuntimeError::ContextService(
                            "retired script ran".into(),
                        ))
                    }
                    _ => Err(crate::RuntimeError::ContextService(
                        "unexpected request".into(),
                    )),
                }
            }
        }
        let (worker, parent) = std::os::unix::net::UnixStream::pair().unwrap();
        let shutdown = parent.try_clone().unwrap();
        let (entered, started) = mpsc::channel();
        let (release, wait) = mpsc::channel();
        let (cancelled, cancellation) = mpsc::channel();
        let runs = Arc::new(AtomicUsize::new(0));
        let service = Arc::new(AdmissionService {
            entered,
            release: Mutex::new(wait),
            cancelled,
            runs: runs.clone(),
        });
        let server = std::thread::spawn(move || {
            crate::context_service::serve_context_transport(parent, service)
        });
        let client = crate::context_service::SharedContextClient::new(
            crate::context_service::IpcContextClient::new(worker),
        );
        let mut page =
            RustExecutableDocument::load("<script id=pending type=application/json>{}</script>")
                .unwrap();
        let node = page.node_by_id("pending").unwrap();
        let dom = page.agent.dom.clone();
        let mut record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
        record.1 = Some("https://example.test/script.js".into());
        record.2 = Some("text/javascript".into());
        let fetch = ParserFetchContext::capture(&page.agent.host, &dom, node).unwrap();
        let mut scheduler = ParserResourceScheduler::new();
        scheduler
            .schedule_script(ParserScriptScheduleInput {
                client: client.clone(),
                page_id: oryn_common::v3::PageId(1),
                order: 4,
                record,
                asynchronous: false,
                fetch,
                host: &mut page.agent.host,
            })
            .unwrap();
        started.recv_timeout(Duration::from_secs(5)).unwrap();
        assert_eq!(scheduler.pending, 1);
        assert!(scheduler.script_leases[&4].lock().unwrap().is_none());
        drop(scheduler);
        release.send(()).unwrap();
        assert_eq!(
            cancellation.recv_timeout(Duration::from_secs(5)).unwrap(),
            71
        );
        assert_eq!(runs.load(Ordering::Acquire), 0);
        client.drain_script_cleanup(Duration::from_secs(5)).unwrap();
        shutdown.shutdown(std::net::Shutdown::Both).unwrap();
        let _ = server.join().unwrap();
    }

    #[test]
    #[cfg(unix)]
    fn parser_resource_worker_delivers_failures_with_original_identity_and_releases_sources() {
        let page = RustExecutableDocument::load("<style id=sheet></style>").unwrap();
        let node = page.node_by_id("sheet").unwrap();
        let identity = ParserFetchContext::capture(&page.agent.host, &page.agent.dom, node)
            .unwrap()
            .identity();
        for panic_worker in [false, true] {
            let budget = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let reservation = ScriptSourceReservation::reserve(&budget, 128).unwrap();
            let (sender, receiver) = std::sync::mpsc::channel();
            let lifetime = std::sync::Arc::new(());
            spawn_parser_resource(
                sender,
                std::sync::Arc::downgrade(&lifetime),
                (),
                move || -> Result<StylesheetSource, String> {
                    let _reservation = reservation;
                    if panic_worker {
                        panic!("simulated resource producer panic");
                    }
                    Err("simulated resource fetch failure".into())
                },
                move |result| ParserResourceCompletion::Stylesheet {
                    identity,
                    node,
                    revision: 17,
                    result,
                },
            );
            let completion = receiver.recv_timeout(Duration::from_secs(5)).unwrap();
            let ParserResourceCompletion::Stylesheet {
                identity: actual,
                node: actual_node,
                revision,
                result,
            } = completion
            else {
                panic!("wrong resource completion kind");
            };
            assert_eq!(actual.realm, identity.realm);
            assert_eq!(actual.stream_epoch, identity.stream_epoch);
            assert_eq!(actual.document_generation, identity.document_generation);
            assert_eq!(actual.document, identity.document);
            assert_eq!(actual_node, node);
            assert_eq!(revision, 17);
            assert_eq!(
                result.unwrap_err(),
                if panic_worker {
                    "parser resource worker panicked"
                } else {
                    "simulated resource fetch failure"
                }
            );
            assert_eq!(budget.load(std::sync::atomic::Ordering::Acquire), 0);
            assert!(
                receiver.try_recv().is_err(),
                "one terminal completion per resource"
            );
        }
    }

    #[test]
    #[cfg(unix)]
    fn parser_resource_ownership_survives_fetch_until_completion_publication() {
        use std::sync::{Arc, mpsc};
        struct Ownership(mpsc::Sender<()>);
        impl Drop for Ownership {
            fn drop(&mut self) {
                let _ = self.0.send(());
            }
        }
        let page = RustExecutableDocument::load("<style id=sheet></style>").unwrap();
        let node = page.node_by_id("sheet").unwrap();
        let identity = ParserFetchContext::capture(&page.agent.host, &page.agent.dom, node)
            .unwrap()
            .identity();
        let lifetime = Arc::new(());
        let (sender, receiver) = mpsc::channel();
        let (entered, finishing) = mpsc::channel();
        let (release, wait) = mpsc::channel();
        let (released, dropped) = mpsc::channel();
        spawn_parser_resource(
            sender,
            Arc::downgrade(&lifetime),
            Ownership(released),
            || {
                Ok((
                    "https://example.test/sheet.css".into(),
                    "body{}".into(),
                    Vec::new(),
                ))
            },
            move |result| {
                entered.send(()).unwrap();
                wait.recv().unwrap();
                ParserResourceCompletion::Stylesheet {
                    identity,
                    node,
                    revision: 1,
                    result,
                }
            },
        );
        finishing.recv_timeout(Duration::from_secs(5)).unwrap();
        assert!(
            dropped.try_recv().is_err(),
            "fetch return must not release publication ownership"
        );
        assert!(receiver.try_recv().is_err());
        release.send(()).unwrap();
        assert!(matches!(
            receiver.recv_timeout(Duration::from_secs(5)).unwrap(),
            ParserResourceCompletion::Stylesheet { result: Ok(_), .. }
        ));
        dropped.recv_timeout(Duration::from_secs(5)).unwrap();
    }

    #[test]
    #[cfg(unix)]
    fn retired_parser_owner_skips_queued_network_work_and_releases_its_capture() {
        let page = RustExecutableDocument::load("<style id=sheet></style>").unwrap();
        let node = page.node_by_id("sheet").unwrap();
        let identity = ParserFetchContext::capture(&page.agent.host, &page.agent.dom, node)
            .unwrap()
            .identity();
        let lifetime = std::sync::Arc::new(());
        let retired = std::sync::Arc::downgrade(&lifetime);
        drop(lifetime);
        let captured = std::sync::Arc::new(());
        let work_capture = captured.clone();
        let (sender, receiver) = std::sync::mpsc::channel();
        spawn_parser_resource(
            sender,
            retired,
            (),
            move || -> Result<StylesheetSource, String> {
                drop(work_capture);
                panic!("retired owner must not start network work");
            },
            move |result| ParserResourceCompletion::Stylesheet {
                identity,
                node,
                revision: 3,
                result,
            },
        );
        let completion = receiver.recv_timeout(Duration::from_secs(5)).unwrap();
        let ParserResourceCompletion::Stylesheet { result, .. } = completion else {
            panic!("wrong completion kind");
        };
        assert_eq!(
            result.unwrap_err(),
            "parser resource owner retired before execution"
        );
        // Joining is not required for cancellation; the completion must release
        // any unexecuted work captures before publication.
        assert_eq!(std::sync::Arc::strong_count(&captured), 1);
    }

    #[test]
    #[cfg(unix)]
    fn deferred_module_response_is_published_before_execution_and_later_bodies_cannot_replace_it() {
        let mut page = RustExecutableDocument::load("<script id=a type=application/json>{}</script><script id=b type=application/json>{}</script>").unwrap();
        let dom = page.agent.dom.clone();
        let requested = "https://example.test/root.js";
        let final_url = "https://example.test/redirect/root.js";
        let first_source = "globalThis.moduleExecutions=1; export {};";
        let budget = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let mut deferred = BTreeMap::new();
        let mut resources = BTreeMap::new();
        let mut diagnostics = Vec::new();
        for (order, id, source, policy) in [
            (0, "a", first_source, "no-referrer"),
            (
                1,
                "b",
                "globalThis.moduleExecutions=2; export {};",
                "unsafe-url",
            ),
        ] {
            let node = page.node_by_id(id).unwrap();
            let mut record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
            record.1 = Some(requested.into());
            record.2 = Some("module".into());
            let identity = record.7.unwrap();
            let result = retain_parser_script_source(
                Ok((final_url.into(), source.into(), false, policy.into())),
                &budget,
            );
            apply_parser_resource_completion(
                ParserResourceCompletion::Script {
                    realm: identity.realm,
                    stream_epoch: identity.stream_epoch,
                    document_generation: identity.document_generation,
                    document: identity.document,
                    order,
                    record,
                    asynchronous: false,
                    result,
                },
                &dom,
                &mut page.agent.host,
                &mut resources,
                &mut deferred,
                &mut diagnostics,
                None,
            )
            .unwrap();
            assert_eq!(
                page.agent.host.retained_module_fetch(requested),
                Some(Some((final_url.into(), first_source.into())))
            );
            assert_eq!(
                deferred[&order].8.loaded.as_ref().unwrap().source,
                first_source
            );
            assert_eq!(
                deferred[&order].8.loaded.as_ref().unwrap().referrer_policy,
                "no-referrer"
            );
        }
        assert_eq!(
            page.agent
                .host
                .evaluate_string("typeof moduleExecutions")
                .unwrap(),
            "undefined"
        );
        assert_eq!(resources[final_url], first_source);
        assert!(diagnostics.is_empty());
        drop(deferred);
        assert_eq!(budget.load(std::sync::atomic::Ordering::Acquire), 0);
    }

    #[test]
    fn parser_script_encoding_is_frozen_from_attribute_or_native_document() {
        let mut page = RustExecutableDocument::load(
            "<script id=a type=application/json charset=windows-1251>{}</script>",
        )
        .unwrap();
        let dom = page.agent.dom.clone();
        let node = page.node_by_id("a").unwrap();
        let prepared = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
        page.execute("document.getElementById('a').charset='utf-8'")
            .unwrap();
        assert_eq!(
            prepared.8.fallback_encoding.as_deref(),
            Some("windows-1251")
        );
        page.execute("document.getElementById('a').charset='not-an-encoding'")
            .unwrap();
        let document = dom.borrow().document();
        dom.borrow_mut()
            .arena_mut()
            .get_mut(document)
            .unwrap()
            .document_metadata
            .as_mut()
            .unwrap()
            .encoding = "windows-1252".into();
        let inherited = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
        assert_eq!(
            inherited.8.fallback_encoding.as_deref(),
            Some("windows-1252")
        );
        dom.borrow_mut()
            .arena_mut()
            .get_mut(document)
            .unwrap()
            .document_metadata
            .as_mut()
            .unwrap()
            .encoding = "UTF-8".into();
        assert_eq!(
            inherited.8.fallback_encoding.as_deref(),
            Some("windows-1252")
        );
    }

    #[test]
    #[cfg(unix)]
    fn parser_module_publication_distinguishes_fetch_failure_from_local_failure() {
        let mut page =
            RustExecutableDocument::load("<script id=a type=application/json>{}</script>").unwrap();
        let dom = page.agent.dom.clone();
        let node = page.node_by_id("a").unwrap();
        let mut record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
        let requested = "https://example.test/failed.js";
        record.1 = Some(requested.into());
        record.2 = Some("module".into());
        let budget = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        for failure in [
            ParserScriptFailure::Capacity,
            ParserScriptFailure::Infrastructure("executor rejected job".into()),
            ParserScriptFailure::NativeTerminal("native retry deadline exceeded".into()),
        ] {
            assert!(
                adopt_parser_module_result(&mut page.agent.host, &record, Err(failure)).is_err()
            );
            assert_eq!(page.agent.host.retained_module_fetch(requested), None);
        }
        let failure = ParserScriptFailure::Fetch {
            message: "verified HTTP fetch failed".into(),
            source_bytes: budget.clone(),
        };
        assert!(adopt_parser_module_result(&mut page.agent.host, &record, Err(failure)).is_err());
        assert_eq!(page.agent.host.retained_module_fetch(requested), Some(None));
        let later = retain_parser_script_source(
            Ok((requested.into(), "export {};".into(), false, String::new())),
            &budget,
        );
        assert!(adopt_parser_module_result(&mut page.agent.host, &record, later).is_err());
        assert_eq!(page.agent.host.retained_module_fetch(requested), Some(None));
        assert_eq!(budget.load(std::sync::atomic::Ordering::Acquire), 0);
    }

    #[test]
    #[cfg(unix)]
    fn parser_late_fetch_failure_adopts_first_success_with_original_source_budget() {
        let mut page =
            RustExecutableDocument::load("<script id=a type=application/json>{}</script>").unwrap();
        let dom = page.agent.dom.clone();
        let node = page.node_by_id("a").unwrap();
        let mut record = capture_parser_script_node(&page.agent.host, &dom, node).unwrap();
        let requested = "https://example.test/request.js";
        let response = "https://example.test/final.js";
        let source = "export const first=1;";
        record.1 = Some(requested.into());
        record.2 = Some("module".into());
        page.agent
            .host
            .retain_verified_module_fetch(requested, response, source)
            .unwrap();
        page.agent
            .host
            .set_module_referrer_policy(response, "no-referrer", false);
        let budget = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let failure = || ParserScriptFailure::Fetch {
            message: "late fetch failed".into(),
            source_bytes: budget.clone(),
        };
        let loaded =
            adopt_parser_module_result(&mut page.agent.host, &record, Err(failure())).unwrap();
        assert_eq!(
            (&*loaded.url, &*loaded.source, &*loaded.referrer_policy),
            (response, source, "no-referrer")
        );
        assert_eq!(
            budget.load(std::sync::atomic::Ordering::Acquire),
            response.len() + source.len() + "no-referrer".len()
        );
        drop(loaded);
        let held =
            ScriptSourceReservation::reserve(&budget, MAX_QUEUED_SCRIPT_SOURCE_BYTES).unwrap();
        assert!(matches!(
            adopt_parser_module_result(&mut page.agent.host, &record, Err(failure())),
            Err(ParserScriptFailure::Capacity)
        ));
        assert_eq!(
            page.agent.host.retained_module_fetch(requested),
            Some(Some((response.into(), source.into())))
        );
        drop(held);
        assert_eq!(budget.load(std::sync::atomic::Ordering::Acquire), 0);
    }

