    #[test]
    fn parser_script_lease_keeps_detached_node_until_queue_release() {
        let dom = Rc::new(RefCell::new(
            html::parse("<script id=queued src='later.js'></script>")
                .into_runtime()
                .unwrap(),
        ));
        let script = dom.borrow().find_by_id("queued").unwrap();
        let lease = ParserScriptLease::new(&dom, script).unwrap();
        {
            let mut dom = dom.borrow_mut();
            dom.remove(script).unwrap();
            let mutations = dom.drain_mutations();
            dom.release_mutation_roots(&mutations).unwrap();
            assert!(dom.arena().get(script).is_ok());
        }
        drop(lease);
        assert!(
            dom.borrow().arena().get(script).is_err(),
            "drained queue must release its native root"
        );
    }

    #[test]
    fn parser_script_lease_cleanup_follows_cross_arena_adoption() {
        let source = Rc::new(RefCell::new(
            html::parse("<script id=queued src='later.js'></script>")
                .into_runtime()
                .unwrap(),
        ));
        let target = Rc::new(RefCell::new(
            html::parse("<body></body>").into_runtime().unwrap(),
        ));
        let script = source.borrow().find_by_id("queued").unwrap();
        let lease = ParserScriptLease::new(&source, script).unwrap();
        let document = target.borrow().document();
        let mut prepared =
            DomRuntime::prepare_subtree_migration(&source, &target, script, document).unwrap();
        let moved = DomRuntime::commit_subtree_migration(&source, &target, &mut prepared).unwrap();
        drop(prepared);
        oryn_dom::drain_node_migration_pins().unwrap();
        {
            let mut dom = source.borrow_mut();
            let mutations = dom.drain_mutations();
            dom.release_mutation_roots(&mutations).unwrap();
        }
        {
            let mut dom = target.borrow_mut();
            let mutations = dom.drain_mutations();
            dom.release_mutation_roots(&mutations).unwrap();
            assert!(dom.retained_by_native_root(moved.root).unwrap());
        }
        // Holding the destination borrow exercises deferred cleanup, not a
        // destructor panic or a release against the stale source allocation.
        {
            let _borrow = target.borrow_mut();
            drop(lease);
        }
        oryn_dom::drain_tracked_node_leases().unwrap();
        assert!(target.borrow().arena().get(moved.root).is_err());
    }

    #[test]
    fn removing_frame_during_script_bootstrap_stops_later_child_scripts() {
        let source = r#"<body><script>globalThis.order=[]</script>
            <iframe srcdoc="<script>parent.order.push('first');frameElement.remove()</script><script>parent.order.push('unexpected-later')</script>"></iframe>
            <script>order.push('parent')</script>
        "#;
        let mut live = RustExecutableDocument::load(source).unwrap();
        assert_eq!(
            live.evaluate("order.slice().sort().join(',')").unwrap(),
            "first,parent"
        );
        live.drain_tasks().unwrap();
        assert!(live.frame_script_preparations.iter().all(|pending| {
            pending.root_or_live_for_test(&live.agent.host)
        }), "removed children must not retain parser preparations");
        let mut dynamic =
            RustExecutableDocument::load("<body><script>globalThis.order=[]</script>").unwrap();
        dynamic
            .evaluate(
                r#"
            const frame=document.createElement('iframe');
            frame.srcdoc='<script>parent.order.push("first");frameElement.remove()</script>'+
                '<script>parent.order.push("unexpected-later")</script>';
            document.body.appendChild(frame);
        "#,
            )
            .unwrap();
        assert_eq!(dynamic.evaluate("order.join(',')").unwrap(), "first");
        dynamic.drain_tasks().unwrap();
        assert_eq!(dynamic.evaluate("order.join(',')").unwrap(), "first");
    }

