    #[test]
    fn dynamic_empty_script_src_queues_trusted_error_without_inline_fallback() {
        let mut page = RustExecutableDocument::load("<body></body>").unwrap();
        page.evaluate(r#"
            globalThis.order=[];
            for(const type of ['', 'module']) {
                const script=document.createElement('script');
                script.type=type;script.setAttribute('src','');
                script.textContent='order.push("unexpected-inline")';
                script.dispatchEvent=()=>{throw Error('author dispatch invoked')};
                script.addEventListener('load',()=>order.push('unexpected-load'));
                script.addEventListener('error',event=>order.push(
                    [type||'classic',event.isTrusted,event.bubbles,event.cancelable,event.target===script].join(':')));
                document.body.appendChild(script);order.push('inserted');
                script.remove();script.removeAttribute('src');document.body.appendChild(script);
            }
            order.push('synchronous-end');
        "#).unwrap();
        assert_eq!(
            page.evaluate("order.join(',')").unwrap(),
            "inserted,inserted,synchronous-end,classic:true:false:false:true,module:true:false:false:true"
        );
    }

