    #[test]
    fn html_writable_blocking_suffix_waits_for_native_execution_and_load_publication() {
        let mut page = RustExecutableDocument::load_with_environment(
            "<body></body>",
            &BTreeMap::new(),
            None,
            Some(Url::parse("https://example.test/").unwrap()),
        )
        .unwrap();
        page.agent.host.execute(r#"globalThis.trace=[];globalThis.done=false;globalThis.conversions=0;globalThis.writer=document.body.streamAppendHTMLUnsafe({runScripts:true}).getWriter();writer.write({toString(){conversions++;return '<script src="/slow.js" onload="trace.push(\'load\')"></script><b id="tail"></b><script>trace.push("suffix")</script>';}}).then(()=>done=true)"#).unwrap();
        let prepared = page
            .agent
            .host
            .take_pending_dynamic_scripts()
            .unwrap()
            .pop()
            .unwrap();
        let mut scheduler = DynamicScriptScheduler::default();
        scheduler.pending.insert(0, (page.top_realm, prepared));
        scheduler.dispatch.ready.push_back((
            0,
            Ok((
                "https://example.test/slow.js".into(),
                "trace.push(document.getElementById('tail')?'early':'body')".into(),
                false,
                String::new(),
            )),
        ));
        DYNAMIC_SCRIPT_AFTER_EXECUTION_FAILURE.with(|failure| failure.set(true));
        assert!(page.dispatch_ready_dynamic_scripts(&mut scheduler).is_err());
        page.agent.host.run_microtask_checkpoint().unwrap();
        assert_eq!(
            page.agent
                .host
                .evaluate_string(
                    "[trace.join(','),done,conversions,!!document.getElementById('tail')].join('|')"
                )
                .unwrap(),
            "body|false|1|false"
        );
        scheduler.execution_retry = None;
        page.dispatch_ready_dynamic_scripts(&mut scheduler).unwrap();
        assert!(scheduler.pending.is_empty());
        for _ in 0..4 {
            page.checkpoint().unwrap();
        }
        assert_eq!(
            page.agent
                .host
                .evaluate_string(
                    "[trace.join(','),done,conversions,!!document.getElementById('tail')].join('|')"
                )
                .unwrap(),
            "body,load,suffix|true|1|true"
        );
    }

    #[test]
    fn dynamic_script_completion_retry_does_not_repeat_body_or_lose_load() {
        let mut page = RustExecutableDocument::load_with_environment(
            "<body></body>",
            &BTreeMap::new(),
            None,
            Some(Url::parse("https://example.test/").unwrap()),
        )
        .unwrap();
        page.agent.host.execute("globalThis.trace=[];globalThis.script=document.createElement('script');script.src='/dynamic.js';script.onload=()=>trace.push('load');document.body.append(script)").unwrap();
        let prepared = page
            .agent
            .host
            .take_pending_dynamic_scripts()
            .unwrap()
            .pop()
            .unwrap();
        let mut scheduler = DynamicScriptScheduler::default();
        scheduler.pending.insert(0, (page.top_realm, prepared));
        scheduler.dispatch.ready.push_back((
            0,
            Ok((
                "https://example.test/dynamic.js".into(),
                "trace.push('body')".into(),
                false,
                String::new(),
            )),
        ));
        DYNAMIC_SCRIPT_AFTER_EXECUTION_FAILURE.with(|failure| failure.set(true));
        assert!(page.dispatch_ready_dynamic_scripts(&mut scheduler).is_err());
        assert_eq!(
            page.agent.host.evaluate_string("trace.join(',')").unwrap(),
            "body"
        );
        assert!(scheduler.executing.is_some());
        assert!(scheduler.pending.contains_key(&0));
        assert!(scheduler.execution_delay(&page.agent.host).is_some());
        scheduler.execution_retry = None;
        page.dispatch_ready_dynamic_scripts(&mut scheduler).unwrap();
        page.dispatch_ready_dynamic_scripts(&mut scheduler).unwrap();
        assert_eq!(
            page.agent.host.evaluate_string("trace.join(',')").unwrap(),
            "body,load"
        );
        assert!(scheduler.executing.is_none());
        assert!(scheduler.pending.is_empty());
    }

