    #[test]
    fn inline_modules_keep_independent_credentials_for_static_and_late_dynamic_imports() {
        use crate::network::{NetworkBroker, NetworkError, NetworkRequest, NetworkResponse};
        use std::sync::{Arc, Mutex};
        struct Scripts(Arc<Mutex<Vec<NetworkRequest>>>);
        impl NetworkBroker for Scripts {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                self.0.lock().unwrap().push(request.clone());
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![
                        ("content-type".into(), "text/javascript".into()),
                        (
                            "access-control-allow-origin".into(),
                            "https://example.test".into(),
                        ),
                        ("access-control-allow-credentials".into(), "true".into()),
                    ],
                    body: b"export const value=42;".to_vec(),
                })
            }
        }
        let seen = Arc::new(Mutex::new(Vec::new()));
        let mut page = RustExecutableDocument::load_with_environment(
            r#"
            <script type=module crossorigin=use-credentials>
                import 'https://cdn.test/credentialed-static.js';
                globalThis.loadCredentialed=()=>import('https://cdn.test/credentialed-late.js');
            </script>
            <script type=module crossorigin=anonymous>
                import 'https://cdn.test/anonymous-static.js';
                globalThis.loadAnonymous=()=>import('https://cdn.test/anonymous-late.js');
            </script>
        "#,
            &BTreeMap::new(),
            Some(SharedNetworkBroker::new(Scripts(seen.clone()))),
            Some(Url::parse("https://example.test/page").unwrap()),
        )
        .unwrap();
        page.evaluate("globalThis.values=[];loadCredentialed().then(m=>values.push(m.value));loadAnonymous().then(m=>values.push(m.value));").unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while page
            .agent
            .host
            .evaluate_string("String(values.length===2)")
            .unwrap()
            != "true"
        {
            page.poll_context_events().unwrap();
            assert!(
                std::time::Instant::now() < deadline,
                "asynchronous loading completion: {:?}",
                page.diagnostics
            );
            std::thread::yield_now();
        }
        assert_eq!(page.evaluate("values.join(',')").unwrap(), "42,42");
        let seen = seen.lock().unwrap();
        assert_eq!(seen.len(), 4);
        for request in seen.iter() {
            assert_eq!(
                request.credentials,
                request.url.contains("credentialed-"),
                "{}",
                request.url
            );
            assert!(
                request
                    .headers
                    .contains(&("origin".into(), "https://example.test".into()))
            );
        }
    }

