    #[test]
    fn dynamic_script_base_url_does_not_change_cors_origin_or_error_taint() {
        use crate::network::{NetworkBroker, NetworkError, NetworkRequest, NetworkResponse};
        use std::sync::{Arc, Mutex};
        struct Scripts(Arc<Mutex<Vec<NetworkRequest>>>);
        impl NetworkBroker for Scripts {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                self.0.lock().unwrap().push(request.clone());
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![
                        ("content-type".into(), "text/javascript".into()),
                        (
                            "access-control-allow-origin".into(),
                            "https://example.test".into(),
                        ),
                    ],
                    body: b"throw {secret:42}".to_vec(),
                })
            }
        }
        let seen = Arc::new(Mutex::new(Vec::new()));
        let mut page = RustExecutableDocument::load_with_environment(
            r#"<base href='https://cdn.test/assets/'><script>globalThis.errors=[];onerror=(m,f,l,c,e)=>{errors.push([f,e]);return true}</script>"#,
            &BTreeMap::new(), Some(SharedNetworkBroker::new(Scripts(seen.clone()))),
            Some(Url::parse("https://example.test/page").unwrap())).unwrap();
        page.evaluate("for(const mode of [false,true]){const s=document.createElement('script');s.async=false;s.src=mode?'cors.js':'opaque.js';if(mode)s.crossOrigin='anonymous';document.head.appendChild(s);}").unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while page
            .agent
            .host
            .evaluate_string("String(errors.length===2)")
            .unwrap()
            != "true"
        {
            page.poll_context_events().unwrap();
            assert!(
                std::time::Instant::now() < deadline,
                "asynchronous loading completion: {:?}",
                page.diagnostics
            );
            std::thread::yield_now();
        }
        assert_eq!(
            page.evaluate("JSON.stringify(errors)").unwrap(),
            r#"[["",null],["https://cdn.test/assets/cors.js",{"secret":42}]]"#
        );
        let seen = seen.lock().unwrap();
        let cors = seen
            .iter()
            .find(|request| request.url.ends_with("cors.js"))
            .unwrap();
        assert!(!cors.credentials);
        assert!(
            cors.headers
                .contains(&("origin".into(), "https://example.test".into()))
        );
        assert_eq!(
            cors.security.initiator_url.as_deref(),
            Some("https://example.test/page")
        );
    }

    #[test]
    fn module_graph_inherits_credentials_and_uses_document_origin_for_cdn_dependencies() {
        use crate::network::{NetworkBroker, NetworkError, NetworkRequest, NetworkResponse};
        use std::sync::{Arc, Mutex};
        struct Scripts(Arc<Mutex<Vec<NetworkRequest>>>);
        impl NetworkBroker for Scripts {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                self.0.lock().unwrap().push(request.clone());
                let path = Url::parse(&request.url).unwrap().path().to_owned();
                let source = match path.as_str() {
                    "/root.js" => "import {value} from './child.js';globalThis.graphValue=value;",
                    "/child.js" => "export {value} from './leaf.js';",
                    _ => "export const value=42;",
                };
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![
                        ("content-type".into(), "text/javascript".into()),
                        (
                            "access-control-allow-origin".into(),
                            "https://example.test".into(),
                        ),
                        ("access-control-allow-credentials".into(), "true".into()),
                    ],
                    body: source.as_bytes().to_vec(),
                })
            }
        }
        for (mode, include) in [("anonymous", false), ("use-credentials", true)] {
            let seen = Arc::new(Mutex::new(Vec::new()));
            let html = format!(
                "<script type=module crossorigin='{mode}' src='https://cdn.test/root.js'></script>"
            );
            let mut page = RustExecutableDocument::load_with_environment(
                &html,
                &BTreeMap::new(),
                Some(SharedNetworkBroker::new(Scripts(seen.clone()))),
                Some(Url::parse("https://example.test/").unwrap()),
            )
            .unwrap();
            assert!(page.diagnostics.is_empty(), "{:?}", page.diagnostics);
            assert_eq!(page.evaluate("String(graphValue)").unwrap(), "42");
            let seen = seen.lock().unwrap();
            assert!(seen.iter().any(|request| request.url.ends_with("leaf.js")));
            for request in seen.iter() {
                assert_eq!(request.credentials, include, "{}", request.url);
                let parent = if request.url.ends_with("child.js") {
                    Some("https://cdn.test/root.js")
                } else if request.url.ends_with("leaf.js") {
                    Some("https://cdn.test/child.js")
                } else {
                    None
                };
                if let Some(parent) = parent {
                    assert!(
                        request.headers.contains(&("referer".into(), parent.into())),
                        "{}",
                        request.url
                    );
                }
                assert!(
                    request
                        .headers
                        .contains(&("origin".into(), "https://example.test".into())),
                    "{}",
                    request.url
                );
            }
        }
    }

    #[test]
    fn parser_script_integrity_verifies_network_bytes_before_using_cached_source() {
        use crate::network::{NetworkBroker, NetworkError, NetworkRequest, NetworkResponse};
        use base64::Engine;
        use sha2::Digest;
        const SOURCE: &str =
            "globalThis.parserIntegrityExecutions=(globalThis.parserIntegrityExecutions||0)+1;";
        struct Scripts;
        impl NetworkBroker for Scripts {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/javascript".into())],
                    body: SOURCE.as_bytes().to_vec(),
                })
            }
        }
        let hash = format!(
            "sha256-{}",
            base64::engine::general_purpose::STANDARD
                .encode(sha2::Sha256::digest(SOURCE.as_bytes()))
        );
        let wrong = format!(
            "sha256-{}",
            base64::engine::general_purpose::STANDARD.encode([0u8; 32])
        );
        let resources = BTreeMap::from([(
            "https://example.test/good.js".into(),
            "globalThis.poisonedParser=true;".into(),
        )]);
        let html = format!(
            "<script src='/good.js' integrity='{hash}'></script><script src='/bad.js' integrity='{wrong}'></script>"
        );
        let mut page = RustExecutableDocument::load_with_environment(
            &html,
            &resources,
            Some(SharedNetworkBroker::new(Scripts)),
            Some(Url::parse("https://example.test/").unwrap()),
        )
        .unwrap();
        assert_eq!(
            page.evaluate("parserIntegrityExecutions+'|'+typeof poisonedParser")
                .unwrap(),
            "1|undefined"
        );
        assert_eq!(page.diagnostics.len(), 1);
    }

    #[test]
    fn dynamic_script_integrity_checks_bytes_and_does_not_trust_decoded_resources() {
        use crate::network::{NetworkBroker, NetworkError, NetworkRequest, NetworkResponse};
        use base64::Engine;
        use sha2::Digest;
        const BODY: &[u8] = b"//\xe9\nglobalThis.integrityLoaded=true;";
        struct Scripts;
        impl NetworkBroker for Scripts {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![
                        (
                            "content-type".into(),
                            "text/javascript;charset=windows-1252".into(),
                        ),
                        ("access-control-allow-origin".into(), "*".into()),
                    ],
                    body: BODY.to_vec(),
                })
            }
        }
        let resources = BTreeMap::from([(
            "https://example.test/script.js".into(),
            "poisonedCachedSource()".into(),
        )]);
        let mut page = RustExecutableDocument::load_with_environment(
            "<body></body>",
            &resources,
            Some(SharedNetworkBroker::new(Scripts)),
            Some(Url::parse("https://example.test/").unwrap()),
        )
        .unwrap();
        let hash = format!(
            "sha256-{}",
            base64::engine::general_purpose::STANDARD.encode(sha2::Sha256::digest(BODY))
        );
        let wrong = format!(
            "sha256-{}",
            base64::engine::general_purpose::STANDARD.encode([0u8; 32])
        );
        let (_, source, _, _) = page
            .agent
            .host
            .load_parser_script_source("script.js", false, Some(&hash), None, None, None)
            .unwrap();
        assert_eq!(source, "//é\nglobalThis.integrityLoaded=true;");
        assert!(
            page.agent
                .host
                .load_parser_script_source("script.js", false, Some(&wrong), None, None, None)
                .is_err()
        );
        assert!(
            page.agent
                .host
                .load_parser_script_source(
                    "https://cdn.test/script.js",
                    false,
                    Some(&hash),
                    None,
                    None,
                    None
                )
                .is_err()
        );
        assert!(
            page.agent
                .host
                .load_parser_script_source(
                    "https://cdn.test/script.js",
                    true,
                    Some(&hash),
                    None,
                    None,
                    None
                )
                .is_ok()
        );
    }

    #[test]
    fn import_map_integrity_verifies_static_dynamic_and_cached_source_candidates() {
        use crate::network::{NetworkBroker, NetworkError, NetworkRequest, NetworkResponse};
        use base64::Engine;
        use sha2::Digest;
        const SOURCE: &str = "globalThis.integrityInitializations=(globalThis.integrityInitializations||0)+1;export const value=42;";
        struct Scripts;
        impl NetworkBroker for Scripts {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![
                        ("content-type".into(), "text/javascript".into()),
                        ("access-control-allow-origin".into(), "*".into()),
                    ],
                    body: SOURCE.as_bytes().to_vec(),
                })
            }
        }
        let hash = format!(
            "sha256-{}",
            base64::engine::general_purpose::STANDARD
                .encode(sha2::Sha256::digest(SOURCE.as_bytes()))
        );
        let wrong = format!(
            "sha512-{}",
            base64::engine::general_purpose::STANDARD.encode([0u8; 64])
        );
        let imports = serde_json::json!({"imports":{"good":"./good.js","bad":"./bad.js","cross":"https://cdn.test/good.js"},
            "integrity":{"./good.js":hash.clone(),"./bad.js":wrong,"https://cdn.test/good.js":hash}});
        let html = format!(
            r#"<script type=importmap>{imports}</script>
            <script type=module>import {{value}} from 'good';globalThis.staticValue=value;
            Promise.allSettled([
                import('good').then(m=>globalThis.dynamicValue=m.value),
                import('cross').then(m=>globalThis.crossValue=m.value),
                import('bad').then(()=>globalThis.badExecuted=true,e=>{{globalThis.badRejected=e instanceof TypeError;throw e;}})
            ]).then(results=>{{
                globalThis.integrityImportOutcomes=results.map(result=>result.status);
                globalThis.integrityImportErrors=results.map(result=>result.status==='rejected'?String(result.reason):null);
                globalThis.integrityImportsDone=true;
            }});</script>"#
        );
        let resources = BTreeMap::from([(
            "https://example.test/good.js".into(),
            "globalThis.poisonedCache=true;export const value=-1;".into(),
        )]);
        let mut page = RustExecutableDocument::load_with_environment(
            &html,
            &resources,
            Some(SharedNetworkBroker::new(Scripts)),
            Some(Url::parse("https://example.test/").unwrap()),
        )
        .unwrap();
        assert!(page.diagnostics.is_empty(), "{:?}", page.diagnostics);
        // Loading services ready work; broker-backed dynamic imports can still
        // be pending. Await all three outcomes through native page turns before
        // reading their values, without making document loading block on them.
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while page
            .evaluate("String(globalThis.integrityImportsDone===true)")
            .unwrap()
            != "true"
        {
            assert!(
                std::time::Instant::now() < deadline,
                "integrity imports did not settle; diagnostics: {:?}",
                page.diagnostics
            );
            page.poll_context_events().unwrap();
            std::thread::yield_now();
        }
        assert!(page.diagnostics.is_empty(), "{:?}", page.diagnostics);
        let outcomes = page.evaluate("integrityImportOutcomes.join('|')").unwrap();
        let errors = page
            .evaluate("JSON.stringify(integrityImportErrors)")
            .unwrap();
        assert_eq!(
            outcomes, "fulfilled|fulfilled|rejected",
            "unexpected import outcomes; rejection details: {errors}"
        );
        assert_eq!(page.evaluate("[staticValue,dynamicValue,crossValue,badRejected,typeof badExecuted,typeof poisonedCache,integrityInitializations].join('|')").unwrap(),"42|42|42|true|undefined|undefined|2");
    }

    #[test]
    fn import_map_native_event_handler_resolution_and_typed_rejection() {
        use crate::network::{NetworkBroker, NetworkError, NetworkRequest, NetworkResponse};
        use base64::Engine;
        use std::sync::{Arc, Mutex};
        struct Scripts {
            sources: BTreeMap<String, String>,
            requested: Arc<Mutex<Vec<String>>>,
        }
        impl NetworkBroker for Scripts {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                self.requested.lock().unwrap().push(request.url.clone());
                let source = self
                    .sources
                    .get(&request.url)
                    .ok_or_else(|| NetworkError::Transport("unexpected module request".into()))?;
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![("content-type".into(), "text/javascript".into())],
                    body: source.as_bytes().to_vec(),
                })
            }
        }
        let resources = BTreeMap::from([
            (
                "https://example.test/assets/shared.js".into(),
                "export const value=42".into(),
            ),
            (
                "https://example.test/assets/protected.js".into(),
                "globalThis.integrityBypassed=true;export const value=1".into(),
            ),
        ]);
        let requested = Arc::new(Mutex::new(Vec::new()));
        let broker = SharedNetworkBroker::new(Scripts {
            sources: resources.clone(),
            requested: requested.clone(),
        });
        let wrong = format!(
            "sha256-{}",
            base64::engine::general_purpose::STANDARD.encode([0u8; 32])
        );
        let html = r#"<base href='/assets/'>
          <script type=importmap>{"imports":{"shared":"./shared.js"},"integrity":{"./protected.js":"sha256-required"}}</script>
          <button id=run onclick="Promise.allSettled([import('shared').then(m=>globalThis.answer=m.value),import('./protected.js').catch(e=>globalThis.blocked=e instanceof TypeError),import('unmapped').catch(e=>globalThis.typed=e instanceof TypeError)]).then(()=>globalThis.handlerImportsDone=true)">Run</button>"#.replace("sha256-required", &wrong);
        let mut page = RustExecutableDocument::load_with_environment(
            &html,
            &resources,
            Some(broker),
            Some(Url::parse("https://example.test/").unwrap()),
        )
        .unwrap();
        page.click("#run").unwrap();
        // click/checkpoint service ready work, but do not await IO-backed
        // dynamic imports. Read the exact rejection results after all three settle.
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while page
            .evaluate("String(globalThis.handlerImportsDone===true)")
            .unwrap()
            != "true"
        {
            assert!(
                std::time::Instant::now() < deadline,
                "event-handler imports did not settle"
            );
            page.poll_context_events().unwrap();
            std::thread::yield_now();
        }
        assert_eq!(
            page.evaluate("answer+'|'+blocked+'|'+typed+'|'+typeof integrityBypassed")
                .unwrap(),
            "42|true|true|undefined"
        );
        let mut requests = requested.lock().unwrap().clone();
        requests.sort();
        assert_eq!(
            requests,
            vec![
                "https://example.test/assets/protected.js".to_owned(),
                "https://example.test/assets/shared.js".to_owned(),
            ],
            "unmapped imports reject before fetching; each mapped response is fetched once"
        );
    }

