    #[test]
    fn oil_pointer_actions_use_trusted_native_sequence_and_obey_cancellation() {
        let mut page=RustExecutableDocument::load(r#"<!doctype html><input id=check type=checkbox style="width:40px;height:40px"><button id=button style="width:100px;height:40px">press</button>"#).unwrap();
        let check = page.agent.dom.borrow().find_by_id("check").unwrap();
        let button = page.agent.dom.borrow().find_by_id("button").unwrap();
        assert!(
            page.apply_action(button, SemanticAction::Uncheck, None)
                .is_err()
        );
        page.execute(r#"
            globalThis.pointerLog=[];globalThis.cancelClick=true;
            for(const type of ['pointerdown','mousedown','pointerup','mouseup','click','input','change'])
                document.getElementById('check').addEventListener(type,e=>{pointerLog.push([type,e.isTrusted]);if(type==='click'&&cancelClick)e.preventDefault()});
            for(const id of ['check','button']) {
                const node=document.getElementById(id);
                node.dispatchEvent=()=>{throw Error('author dispatch')};node.click=()=>{throw Error('author click')};
                node.getBoundingClientRect=()=>{throw Error('author geometry')};
            }
            globalThis.MouseEvent=function(){throw Error('author constructor')};
        "#).unwrap();
        page.apply_action(check, SemanticAction::Click, None)
            .unwrap();
        assert_eq!(
            page.evaluate("document.getElementById('check').checked")
                .unwrap(),
            "false"
        );
        assert_eq!(
            page.evaluate("JSON.stringify(pointerLog)").unwrap(),
            r#"[["pointerdown",true],["mousedown",true],["pointerup",true],["mouseup",true],["click",true]]"#
        );
        assert!(
            page.apply_action(check, SemanticAction::Check, None)
                .is_err(),
            "canceled activation must not report requested checked state as reached"
        );
        page.execute("cancelClick=false;pointerLog=[]").unwrap();
        page.apply_action(check, SemanticAction::Check, None)
            .unwrap();
        assert_eq!(
            page.evaluate("document.getElementById('check').checked")
                .unwrap(),
            "true"
        );
        let events = page.evaluate("JSON.stringify(pointerLog)").unwrap();
        page.apply_action(check, SemanticAction::Check, None)
            .unwrap();
        assert_eq!(page.evaluate("JSON.stringify(pointerLog)").unwrap(), events);
        page.apply_action(button, SemanticAction::Hover, None)
            .unwrap();
        page.execute("const cover=document.createElement('div');cover.style.cssText='position:fixed;inset:0;z-index:999;background:white';document.body.append(cover)").unwrap();
        assert!(
            page.apply_action(button, SemanticAction::Click, None)
                .is_err()
        );
    }

