    #[test]
    fn form_custom_element_selector_state_reaches_computed_style() {
        let mut page=RustExecutableDocument::load(r#"
            <style>x-field{width:10px;display:block}x-field:enabled{width:20px}
            x-field:disabled{width:30px}x-field:invalid{height:40px}x-field:valid{height:50px}</style>
            <fieldset id=group disabled><legend><x-field id=exempt></x-field></legend>
            <x-field id=control></x-field></fieldset><x-other id=ordinary></x-other>
            "#).unwrap();
        page.execute(r#"
            customElements.define('x-field',class extends HTMLElement {
                static formAssociated=true;
                constructor(){super();this.internals=this.attachInternals();}
            });
            globalThis.checkFormStyles=()=>{
                const group=document.getElementById('group'),control=document.getElementById('control');
                const exempt=document.getElementById('exempt'),ordinary=document.getElementById('ordinary');
                const check=(value,label)=>{if(!value)throw Error(label)};
                check(getComputedStyle(control).width==='30px'&&control.matches(':disabled'),'disabled style');
                check(getComputedStyle(exempt).width==='20px'&&exempt.matches(':enabled'),'legend exception');
                check(!ordinary.matches(':enabled,:disabled'),'ordinary custom element');
                control.internals.setValidity({customError:true},'invalid');
                check(!control.matches(':invalid'),'disabled validation');
                group.removeAttribute('disabled');
                check(getComputedStyle(control).width==='20px','re-enabled style');
                check(getComputedStyle(control).height==='40px'&&control.matches(':invalid'),'invalid style');
                control.internals.setValidity({});
                check(getComputedStyle(control).height==='50px'&&control.matches(':valid'),'valid style');
                return 'ok';
            };
        "#).unwrap();
        assert_eq!(page.evaluate("checkFormStyles()").unwrap(), "ok");
    }

    #[test]
    fn native_form_history_waits_for_late_upgrade_and_restores_duplicate_names_in_order() {
        const HTML: &str =
            "<form id=f><x-late name=entry></x-late><x-late name=entry></x-late></form>";
        const DEFINE: &str = "globalThis.restored=[];customElements.define('x-late',class extends HTMLElement{static formAssociated=true;constructor(){super();this.i=this.attachInternals()}formStateRestoreCallback(value,mode){restored.push(value+':'+mode)}})";
        let mut source = RustExecutableDocument::load(HTML).unwrap();
        source.execute(DEFINE).unwrap();
        source.execute("Array.from(document.querySelectorAll('x-late')).forEach((node,index)=>node.i.setFormValue('submit','state'+index))").unwrap();
        let saved = source.capture_form_history().unwrap();
        let mut destination = RustExecutableDocument::load(HTML).unwrap();
        destination.restore_form_history(&saved).unwrap();
        let retained = destination.capture_form_history().unwrap();
        assert_eq!(retained.len(), 2);
        assert_eq!(retained[0].state, saved[0].state);
        destination.execute(DEFINE).unwrap();
        assert_eq!(
            destination.evaluate("restored.join('|')").unwrap(),
            "state0:restore|state1:restore"
        );
        destination
            .execute("document.body.setAttribute('data-check','1')")
            .unwrap();
        assert_eq!(destination.evaluate("restored.length").unwrap(), "2");
    }

    #[test]
    fn native_form_history_restores_saved_state_into_new_control_instances() {
        const HTML: &str = r#"<form id=f><x-field name=entry></x-field></form>"#;
        const DEFINE: &str = r#"
            globalThis.restorations=[];
            customElements.define('x-field',class extends HTMLElement {
                static formAssociated=true;
                constructor(){super();this.internals=this.attachInternals();}
                formStateRestoreCallback(value,mode){restorations.push([value,mode]);this.internals.setFormValue('submission',value);}
            });
        "#;
        let mut source = RustExecutableDocument::load(HTML).unwrap();
        source.execute(DEFINE).unwrap();
        source.execute("document.querySelector('x-field').internals.setFormValue('different submission','private saved state')").unwrap();
        let saved = source.capture_form_history().unwrap();
        assert_eq!(saved.len(), 1);
        assert_eq!(
            saved[0].state,
            oryn_js::form_state::FormState::String("private saved state".into())
        );
        drop(source);
        let mut destination = RustExecutableDocument::load(HTML).unwrap();
        destination.execute(DEFINE).unwrap();
        destination.restore_form_history(&saved).unwrap();
        assert_eq!(
            destination
                .evaluate("JSON.stringify(restorations)")
                .unwrap(),
            r#"[["private saved state","restore"]]"#
        );
        assert_eq!(
            destination
                .evaluate("new FormData(document.getElementById('f')).get('entry')")
                .unwrap(),
            "submission"
        );
        destination
            .execute("document.getElementById('f').id='different-owner';restorations=[]")
            .unwrap();
        destination.restore_form_history(&saved).unwrap();
        assert_eq!(destination.evaluate("restorations.length").unwrap(), "0");
    }

    #[cfg(feature = "historical-test-input")]
    #[test]
    fn native_focus_automation_defers_dispatch_until_promise_return() {
        let mut page = RustExecutableDocument::load(
            "<body><button id='click'>Click</button><input id='keys'><button id='actions'>Actions</button></body>"
        ).unwrap();
        page.execute(r#"
            globalThis.automationResult='pending';
            (async()=>{
                const checks=[];
                for(const id of ['click','keys','actions']) {
                    const target=document.getElementById(id);
                    let promise;
                    target.addEventListener('focus',()=>checks.push(!!promise&&typeof promise.then==='function'),{once:true});
                    if(id==='click')promise=__oryn_testdriver_click(target);
                    else if(id==='keys')promise=__oryn_testdriver_send_keys(target,'x');
                    else promise=__oryn_testdriver_actions([{type:'pointer',id:'mouse',actions:[
                        {type:'pointerMove',origin:target,x:0,y:0},{type:'pointerDown',button:0},{type:'pointerUp',button:0}
                    ]}]);
                    checks.push(promise instanceof Promise&&document.activeElement!==target);
                    await promise;
                    checks.push(document.activeElement===target);
                }
                checks.push(document.getElementById('keys').value==='x');
                return checks.length===10&&checks.every(Boolean)?'ok':JSON.stringify(checks);
            })().then(value=>globalThis.automationResult=value,error=>globalThis.automationResult=String(error));
        "#).unwrap();
        assert_eq!(
            page.evaluate("__oryn_drain(true);automationResult")
                .unwrap(),
            "ok"
        );
    }

