    #[test]
    fn dynamic_script_completion_uses_native_trusted_events() {
        let resources = BTreeMap::from([("dynamic.js".into(), "globalThis.ran=true".into())]);
        let mut page = RustExecutableDocument::load_with_resources(
            r#"<body><script>
            globalThis.events=[];
            for(const src of ['dynamic.js','missing.js']) {
                const script=document.createElement('script');script.src=src;
                script.dispatchEvent=()=>{throw Error('author dispatch used')};
                for(const type of ['load','error']) script.addEventListener(type,event=>{
                    events.push([src,type,event.isTrusted,event.bubbles,event.cancelable,
                        event.target===script,event.currentTarget===script].join(':'));
                });
                document.body.appendChild(script);
            }
            globalThis.Event=function(){throw Error('author Event constructor used')};
        </script></body>"#,
            &resources,
        )
        .unwrap();
        assert_eq!(
            page.evaluate("events.sort().join(',')").unwrap(),
            "dynamic.js:load:true:false:false:true:true,missing.js:error:true:false:false:true:true"
        );
        assert_eq!(page.evaluate("String(ran)").unwrap(), "true");
    }

