    #[test]
    fn document_open_clears_tree_listeners_immediately_but_preserves_detached_targets() {
        let mut page = RustExecutableDocument::load("<body><div id=host></div></body>").unwrap();
        page.execute(
            r#"
            globalThis.events=[];
            const shadow=document.getElementById('host').attachShadow({mode:'closed'});
            const child=shadow.appendChild(document.createElement('div'));
            const nested=child.attachShadow({mode:'open'});
            globalThis.retained=[shadow,child,nested];
            retained.forEach(node=>node.addEventListener('x',()=>events.push('obsolete-shadow')));
            globalThis.detached=document.createElement('div');
            detached.addEventListener('x',()=>events.push('detached'));
            window.addEventListener('x',()=>events.push('obsolete-window'));
            document.addEventListener('x',()=>{events.push('first');document.open()});
            document.addEventListener('x',()=>events.push('obsolete-document'));
            document.dispatchEvent(new Event('x'));
            retained.forEach(node=>node.dispatchEvent(new Event('x')));
            window.dispatchEvent(new Event('x'));
            detached.dispatchEvent(new Event('x'));
            document.write('<body>replacement');document.close();
        "#,
        )
        .unwrap();
        assert_eq!(page.evaluate("events.join(',')").unwrap(), "first,detached");
    }

    #[test]
    fn document_open_preserves_queued_global_tasks_and_message_port_listeners() {
        let mut page = RustExecutableDocument::load("<body></body>").unwrap();
        page.agent
            .host
            .execute(
                r#"
            globalThis.events=[];
            globalThis.originalWindow=window;globalThis.originalDocument=document;
            const channel=new MessageChannel();globalThis.channel=channel;
            channel.port2.onmessage=event=>events.push('port:'+event.data);
            channel.port1.postMessage('retained');
            setTimeout(()=>events.push('timer'),0);
            const canvas=document.createElement('canvas');document.body.append(canvas);
            canvas.toBlob(()=>events.push('blob'));
            postMessage('before','*');
            document.open();
            onmessage=event=>events.push('window:'+event.data);
            postMessage('after','*');
            document.write('<body>replacement');document.close();
        "#,
            )
            .unwrap();
        for _ in 0..4 {
            page.drain_tasks().unwrap();
        }
        assert_eq!(
            page.evaluate("events.slice().sort().join(',')").unwrap(),
            "blob,port:retained,timer,window:after,window:before"
        );
        assert_eq!(
            page.evaluate("String(window===originalWindow&&document===originalDocument)")
                .unwrap(),
            "true"
        );
    }

