    #[test]
    fn native_loaded_url_seed_preserves_restored_history_and_blank_document_url() {
        use oryn_js::navigation_api::{NavigationHistorySnapshot, NavigationHistoryUpdate};
        let entries: Vec<_> = ["first", "second"]
            .into_iter()
            .map(|name| NavigationHistorySnapshot {
                scroll: Default::default(),
                key: format!("key-{name}"),
                id: format!("id-{name}"),
                url: format!("https://forms.test/{name}"),
                document_id: "restored-document".into(),
                state: None,
                history_state: None,
            })
            .collect();
        let history = NavigationHistoryUpdate {
            entries,
            current: 1,
            navigation_type: "traverse".into(),
            truncates_forward: false,
        };
        let mut resources = BTreeMap::new();
        resources.insert(
            "oryn:navigation-history".into(),
            serde_json::to_string(&history).unwrap(),
        );
        let mut page = RustExecutableDocument::load_with_environment(
            "<script>globalThis.initialHistory=navigation.entries().map(e=>[e.url,e.key,e.id].join('|')).join(',');globalThis.initialCurrent=navigation.currentEntry.id;globalThis.publications=0;navigation.oncurrententrychange=()=>publications++;</script>",
            &resources, None, Some(Url::parse("https://forms.test/second").unwrap()),
        ).unwrap();
        assert_eq!(
            page.evaluate("initialHistory").unwrap(),
            "https://forms.test/first|key-first|id-first,https://forms.test/second|key-second|id-second"
        );
        assert_eq!(page.evaluate("initialCurrent").unwrap(), "id-second");
        page.checkpoint().unwrap();
        assert_eq!(page.evaluate("String(navigation.currentEntry.id===initialCurrent&&navigation.entries().length===2&&publications===0&&document.URL==='https://forms.test/second')").unwrap(), "true");
        let mut blank = RustExecutableDocument::load_with_environment(
            "<body></body>",
            &BTreeMap::new(),
            None,
            None,
        )
        .unwrap();
        assert_eq!(
            blank
                .evaluate("String(document.URL==='about:blank'&&location.href==='about:blank')")
                .unwrap(),
            "true"
        );
    }

    #[test]
    fn native_default_navigation_dispatches_cancellable_captured_form_metadata() {
        let mut page=RustExecutableDocument::load_with_environment("<form id=f action=/send method=post><input name=x value=initial><button id=b name=submitter value=yes></button></form><a id=a href=/next>next</a>",&BTreeMap::new(),None,Some(Url::parse("https://forms.test/start").unwrap())).unwrap();
        page.execute("globalThis.seen=[];f.onformdata=e=>e.formData.append('added','captured');navigation.onnavigate=e=>{seen.push([e.sourceElement===b,e.formData.get('x'),e.formData.get('added'),e.formData.get('submitter')].join('|'));e.preventDefault();};f.requestSubmit(b)").unwrap();
        assert!(page.take_location_navigation().is_none());
        assert_eq!(
            page.evaluate("seen.join(',')").unwrap(),
            "true|initial|captured|yes"
        );
        page.agent.host.execute("globalThis.interceptError=null;globalThis.interceptStages=[];navigation.onnavigate=e=>{seen.push(e.sourceElement===a&&e.formData===null?'anchor':'wrong');interceptStages.push('enter');try{e.intercept();interceptStages.push('intercepted')}catch(error){interceptError=error.name;throw error}};a.click()").unwrap();
        let before_checkpoint = page.take_location_navigation();
        assert!(
            before_checkpoint.is_none(),
            "before native checkpoint: pending={before_checkpoint:?}; {}",
            page.agent
                .host
                .evaluate_string(
                    "JSON.stringify({seen,interceptError,interceptStages,path:location.pathname})"
                )
                .unwrap()
        );
        assert_eq!(
            page.agent
                .host
                .evaluate_string("interceptStages.join(',')")
                .unwrap(),
            "enter,intercepted",
            "{}",
            page.agent.host.evaluate_string("JSON.stringify({seen,interceptError,interceptStages,path:location.pathname,entry:navigation.currentEntry.url})").unwrap()
        );
        page.checkpoint().unwrap();
        let pending = page.take_location_navigation();
        assert!(
            pending.is_none(),
            "pending={pending:?}; {}",
            page.evaluate(
                "JSON.stringify({seen,interceptError,interceptStages,path:location.pathname})"
            )
            .unwrap()
        );
        assert_eq!(
            page.evaluate("seen.join(',')").unwrap(),
            "true|initial|captured|yes,anchor"
        );
        assert_eq!(page.evaluate("location.pathname").unwrap(), "/next");
    }

