    #[test]
    fn form_operation_guards_follow_adoption_and_release_after_callbacks() {
        let mut page = RustExecutableDocument::load_with_environment(
            r#"<form id=f><input name=x value=original></form><iframe id=frame srcdoc='<body></body>'></iframe>"#,
            &BTreeMap::new(), None, Some(Url::parse("https://forms.test/start").unwrap()),
        ).unwrap();
        page.execute(
            r#"
            globalThis.saved=f;globalThis.seen=[];
            saved.onsubmit=e=>{
                e.preventDefault();seen.push('submit');
                if(seen.length>1)throw Error('recursive submit');
                frame.contentDocument.body.append(frame.contentDocument.adoptNode(saved));
                saved.requestSubmit();
            };
            saved.requestSubmit();
            saved.onsubmit=e=>{e.preventDefault();seen.push('released');};
            saved.requestSubmit();
            saved.onformdata=()=>{
                seen.push('data');
                document.body.append(document.adoptNode(saved));
                try { new FormData(saved);seen.push('wrong'); }
                catch(e) { seen.push(e.name); }
                saved.submit();
            };
            new FormData(saved);
            saved.onformdata=null;
            seen.push(new FormData(saved).get('x'));
        "#,
        )
        .unwrap();
        assert_eq!(
            page.evaluate("seen.join(',')").unwrap(),
            "submit,released,data,InvalidStateError,original"
        );
        assert!(page.take_location_navigation().is_none());
    }

