    fn synchronous_link_navigation_cancellation_and_reentrancy_keep_latest_admission() {
        let mut page = RustExecutableDocument::load_with_environment(
            "<a id=first href=/first>first</a><a id=second href=/second>second</a>",
            &BTreeMap::new(),
            None,
            Some(Url::parse("https://links.test/start").unwrap()),
        )
        .unwrap();
        page.agent.host.execute("globalThis.seen=[];navigation.onnavigate=e=>{seen.push(e.sourceElement.id);if(e.sourceElement===first)second.click();};first.click()").unwrap();
        assert_eq!(
            page.agent.host.evaluate_string("seen.join(',')").unwrap(),
            "first,second"
        );
        page.drain_default_actions().unwrap();
        assert_eq!(
            page.take_location_navigation().unwrap().url,
            "https://links.test/second"
        );
        page.agent
            .host
            .execute("navigation.onnavigate=e=>e.preventDefault();first.click()")
            .unwrap();
        page.drain_default_actions().unwrap();
        assert!(page.take_location_navigation().is_none());
    }

