    #[test]
    fn accepted_link_captures_url_base_policy_and_source_before_later_mutations() {
        for element in ["a", "area"] {
            let mut page = RustExecutableDocument::load_with_environment(
                &format!("<base id=base href='https://links.test/original/'><{element} id=link href=initial rel=noreferrer referrerpolicy=unsafe-url></{element}><iframe id=child srcdoc='<body></body>'></iframe>"),
                &BTreeMap::new(), None, Some(Url::parse("https://links.test/start").unwrap()),
            ).unwrap();
            page.agent
                .host
                .execute(
                    r#"
                globalThis.saved = link;
                globalThis.sourceMatches = false;
                navigation.onnavigate = e => { sourceMatches = e.sourceElement === saved; };
                link.onclick = () => { link.href = 'accepted?q=é'; };
                link.click();
                link.href = 'too-late';
                base.href = 'https://other.test/';
                link.rel = '';
                link.referrerPolicy = 'unsafe-url';
                child.contentDocument.body.append(child.contentDocument.adoptNode(link));
            "#,
                )
                .unwrap();
            page.drain_default_actions().unwrap();
            let navigation = page.take_location_navigation().expect("accepted link");
            assert_eq!(
                navigation.url,
                "https://links.test/original/accepted?q=%C3%A9"
            );
            assert_eq!(navigation.referrer_policy.as_deref(), Some("no-referrer"));
            assert_eq!(
                page.agent
                    .host
                    .evaluate_string("String(sourceMatches)")
                    .unwrap(),
                "true"
            );
        }
    }

