    #[test]
    fn accepted_link_schedule_failure_retains_admission_and_original_parameters() {
        let mut page = RustExecutableDocument::load_with_environment(
            "<a id=link href=/next>go</a>",
            &BTreeMap::new(),
            None,
            Some(Url::parse("https://links.test/start").unwrap()),
        )
        .unwrap();
        page.agent
            .host
            .execute("globalThis.seen=0;navigation.onnavigate=()=>seen++;link.click()")
            .unwrap();
        assert_eq!(page.agent.host.next_timer_delay(), Some(Duration::ZERO));
        assert!(page.agent.host.has_runnable_page_work());
        ACCEPTED_LINK_SCHEDULE_FAILURE.with(|failure| failure.set(true));
        assert!(page.drain_default_actions().is_err());
        assert!(page.take_location_navigation().is_none());
        assert_eq!(page.retained_default_actions.len(), 1);
        assert!(page.default_action_retry.is_some());
        page.agent
            .host
            .execute("link.href='/changed';link.target='_blank'")
            .unwrap();
        page.default_action_retry = None;
        page.drain_default_actions().unwrap();
        let navigation = page
            .take_location_navigation()
            .expect("retained accepted navigation");
        assert_eq!(navigation.url, "https://links.test/next");
        assert_eq!(
            page.agent.host.evaluate_string("String(seen)").unwrap(),
            "1"
        );
        assert!(page.retained_default_actions.is_empty());
        page.drain_default_actions().unwrap();
        assert!(page.take_location_navigation().is_none());
    }

    #[test]
    fn default_action_failure_retains_suffix_before_new_callback_actions() {
        let mut page = RustExecutableDocument::load_with_environment(
            "<form id=a action=/a></form><form id=b action=/b></form><form id=c action=/c></form>",
            &BTreeMap::new(),
            None,
            Some(Url::parse("https://forms.test/start").unwrap()),
        )
        .unwrap();
        page.agent.host.execute("globalThis.seen=[];navigation.onnavigate=e=>{seen.push(e.sourceElement.id);e.preventDefault();if(e.sourceElement===a)c.submit();};a.submit();b.submit()").unwrap();
        DEFAULT_ACTION_FAILURE.with(|failure| failure.set(true));
        assert!(page.drain_default_actions().is_err());
        assert_eq!(
            page.agent.host.evaluate_string("seen.join(',')").unwrap(),
            "a"
        );
        assert_eq!(page.retained_default_actions.len(), 1);
        assert_eq!(page.agent.host.active_realm(), page.top_realm);
        assert!(page.default_action_retry.is_some());
        assert!(page.next_timer_delay().is_some());
        page.default_action_retry = None;
        page.drain_default_actions().unwrap();
        assert_eq!(
            page.agent.host.evaluate_string("seen.join(',')").unwrap(),
            "a,b,c"
        );
        assert!(page.retained_default_actions.is_empty());
        assert!(page.default_action_retry.is_none());
    }

