    #[test]
    fn callback_adoption_uses_current_navigable_and_original_source() {
        for callback in ["onsubmit", "onformdata"] {
            for activation in ["saved.submit()", "saved.requestSubmit()", "button.click()"] {
                let mut page = RustExecutableDocument::load_with_environment(
            r#"<form id=f action=/accepted><input name=x value=original><button id=b></button></form><iframe id=frame srcdoc='<body></body>'></iframe>"#,
            &BTreeMap::new(), None, Some(Url::parse("https://forms.test/start").unwrap()),
        ).unwrap();
                page.execute(&format!("globalThis.saved=f;globalThis.button=b;globalThis.seen='missing';navigation.onnavigate=e=>{{seen='top';e.preventDefault();}};frame.contentWindow.navigation.onnavigate=e=>{{seen=e.sourceElement===saved||e.sourceElement===button?'child':'wrong';e.preventDefault();}};saved.{callback}=()=>frame.contentDocument.body.append(frame.contentDocument.adoptNode(saved));{activation};globalThis.returned=true")).unwrap();
                let expected = if callback == "onsubmit" && activation == "saved.submit()" {
                    "top"
                } else {
                    "child"
                };
                assert_eq!(page.evaluate("seen").unwrap(), expected);
                assert_eq!(page.evaluate("returned").unwrap(), "true");
                assert!(page.take_location_navigation().is_none());
            }
        }
    }

