    #[test]
    fn recursive_dynamic_admission_keeps_predecessors_while_async_and_other_realms_progress() {
        let mut queue =
            DynamicScriptCompletions::new([(0, RealmId(0), false), (1, RealmId(0), true)]);
        let loaded = || {
            Ok((
                "https://example.test/a.js".into(),
                String::new(),
                false,
                "no-referrer".into(),
            ))
        };
        assert_eq!(queue.complete(1, RealmId(0), true, loaded()).len(), 1);
        // Script 1 inserts successors while the original ordered fetch is pending.
        queue.admit([
            (2, RealmId(0), false),
            (3, RealmId(0), true),
            (4, RealmId(1), false),
        ]);
        assert!(queue.complete(2, RealmId(0), false, loaded()).is_empty());
        assert_eq!(queue.complete(3, RealmId(0), true, loaded())[0].0, 3);
        assert_eq!(queue.complete(4, RealmId(1), false, loaded())[0].0, 4);
        assert_eq!(
            queue
                .complete(0, RealmId(0), false, loaded())
                .into_iter()
                .map(|(index, _)| index)
                .collect::<Vec<_>>(),
            vec![0, 2]
        );
        assert!(queue.ready.is_empty());
    }

