    #[test]
    fn opaque_redirect_home_keeps_parser_and_dynamic_script_errors_muted() {
        use crate::network::{NetworkBroker, NetworkError, NetworkRequest, NetworkResponse};
        struct Scripts;
        impl NetworkBroker for Scripts {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                let redirect = request.url.starts_with("https://remote.test/");
                let headers = if redirect {
                    vec![("location".into(), "https://example.test/fail.js".into())]
                } else {
                    vec![("content-type".into(), "text/javascript".into())]
                };
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: if redirect { 302 } else { 200 },
                    headers,
                    body: b"throw {secret:42}".to_vec(),
                })
            }
        }
        let mut page = RustExecutableDocument::load_with_environment(
            r#"<script>globalThis.seen=[];onerror=(...args)=>{seen.push(args);return true}</script>
            <script src='https://remote.test/parser.js'></script>"#,
            &BTreeMap::new(),
            Some(SharedNetworkBroker::new(Scripts)),
            Some(Url::parse("https://example.test/page").unwrap()),
        )
        .unwrap();
        page.evaluate("const script=document.createElement('script');script.src='https://remote.test/dynamic.js';document.head.appendChild(script);").unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while page
            .agent
            .host
            .evaluate_string("String(seen.length===2)")
            .unwrap()
            != "true"
        {
            page.poll_context_events().unwrap();
            assert!(
                std::time::Instant::now() < deadline,
                "asynchronous loading completion: {:?}",
                page.diagnostics
            );
            std::thread::yield_now();
        }
        assert_eq!(
            page.evaluate("JSON.stringify(seen)").unwrap(),
            r#"[["Script error.","",0,0,null],["Script error.","",0,0,null]]"#
        );
    }

    #[test]
    fn cors_classic_parser_and_dynamic_errors_preserve_exception_details() {
        use crate::network::{NetworkBroker, NetworkError, NetworkRequest, NetworkResponse};
        struct Scripts;
        impl NetworkBroker for Scripts {
            fn send(&self, request: NetworkRequest) -> Result<NetworkResponse, NetworkError> {
                Ok(NetworkResponse {
                    response_policy: None,
                    timing: None,
                    request_id: request.request_id,
                    status: 200,
                    headers: vec![
                        ("content-type".into(), "text/javascript".into()),
                        ("access-control-allow-origin".into(), "*".into()),
                    ],
                    body: b"throw {secret:42}".to_vec(),
                })
            }
        }
        let mut page = RustExecutableDocument::load_with_environment(
            r#"<script>globalThis.seen=[];onerror=(m,f,l,c,e)=>{seen.push([f,e.secret]);return true}</script>
            <script crossorigin=anonymous src='https://remote.test/parser.js'></script>"#,
            &BTreeMap::new(), Some(SharedNetworkBroker::new(Scripts)),
            Some(Url::parse("https://example.test/page").unwrap())).unwrap();
        page.evaluate("const script=document.createElement('script');script.crossOrigin='anonymous';script.src='https://remote.test/dynamic.js';document.head.appendChild(script);").unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(1);
        while page
            .agent
            .host
            .evaluate_string("String(seen.length)")
            .unwrap()
            != "2"
            && std::time::Instant::now() < deadline
        {
            page.checkpoint().unwrap();
            std::thread::yield_now();
        }
        assert_eq!(
            page.evaluate("JSON.stringify(seen)").unwrap(),
            r#"[["https://remote.test/parser.js",42],["https://remote.test/dynamic.js",42]]"#
        );
        assert!(page.diagnostics.is_empty(), "{:?}", page.diagnostics);
    }

