    #[test]
    fn css_script_registration_updates_live_computed_style_and_is_document_owned() {
        let mut page=RustExecutableDocument::load("<!doctype html><style>@property --size{syntax:'<length>';inherits:true;initial-value:2px}#parent{--size:40px}#child{width:var(--size);height:10px}</style><div id=parent><div id=child></div></div>").unwrap();
        assert_eq!(page.evaluate(r#"(()=>{
            const child=document.getElementById('child'),live=getComputedStyle(child);const before=live.width;
            CSS.registerProperty({name:'--size',syntax:'<length>',inherits:false,initialValue:'13px'});
            const changed=live.width==='13px'&&live.getPropertyValue('--size')==='13px'&&Array.from(live).includes('--size');
            let duplicate;try{CSS.registerProperty({name:'--size',syntax:'invalid',inherits:true})}catch(e){duplicate=e.name}
            let syntax;try{CSS.registerProperty({name:'--bad',syntax:'<length>',inherits:false,initialValue:'1em'})}catch(e){syntax=e.name}
            const clone=document.cloneNode(true);const separate=clone.defaultView===null;
            document.querySelector('style').textContent='@property --size{syntax:"<length>";inherits:true;initial-value:99px}#child{width:var(--size)}';
            return [before==='40px',changed,duplicate==='InvalidModificationError',syntax==='SyntaxError',live.width==='13px',separate].join('|');
        })()"#).unwrap(),"true|true|true|true|true|true");
    }

