    #[test]
    fn refresh_header_uses_native_timer_owner_charset_and_policy() {
        let mut page = RustExecutableDocument::load_with_environment(
            "<p>loaded</p>",
            &BTreeMap::new(),
            None,
            Some(Url::parse("https://refresh.test/page").unwrap()),
        )
        .unwrap();
        let dom = page.agent.host.automation_dom(page.top_realm).unwrap();
        let document = page
            .agent
            .host
            .automation_realm_identity(page.top_realm)
            .unwrap()
            .0;
        dom.borrow_mut()
            .arena_mut()
            .get_mut(document)
            .unwrap()
            .document_metadata
            .as_mut()
            .unwrap()
            .encoding = "windows-1251".into();
        page.agent
            .host
            .execute("globalThis.setTimeout=()=>{throw Error('authored timer called')}")
            .unwrap();
        page.agent
            .host
            .prepare_refresh_headers(&[("refresh".into(), "0, URL='?ÿ'".into())])
            .unwrap();
        page.agent.host.execute("true").unwrap();
        page.agent.host.drain_scheduled_timers(false).unwrap();
        page.agent.host.execute("true").unwrap();
        // The first drain arms a native timer after this turn advances the timer heap.
        // The second drain runs expiry; the third admits owner-document navigation.
        assert!(page.agent.host.take_location_navigation().is_none());
        page.agent.host.drain_scheduled_timers(false).unwrap();
        assert!(page.agent.host.take_location_navigation().is_none());
        page.agent.host.drain_scheduled_timers(false).unwrap();
        assert_eq!(
            page.agent.host.take_location_navigation().unwrap().url,
            "https://refresh.test/page?%26%23255%3B"
        );
        let mut denied = RustExecutableDocument::load_with_environment(
            "<p>loaded</p>",
            &BTreeMap::new(),
            None,
            Some(Url::parse("https://refresh.test/page").unwrap()),
        )
        .unwrap();
        denied
            .agent
            .host
            .constrain_automatic_features_allowed(false)
            .unwrap();
        denied
            .agent
            .host
            .prepare_refresh_headers(&[("Refresh".into(), "0;url=/denied".into())])
            .unwrap();
        denied.agent.host.execute("true").unwrap();
        denied.agent.host.drain_scheduled_timers(false).unwrap();
        assert!(denied.agent.host.take_location_navigation().is_none());
        denied.agent.host.drain_scheduled_timers(false).unwrap();
        assert!(denied.agent.host.take_location_navigation().is_none());
        denied.agent.host.drain_scheduled_timers(false).unwrap();
        assert!(denied.agent.host.take_location_navigation().is_none());
    }

    #[test]
    fn borrowed_meta_refresh_schedules_owner_document_navigation() {
        let mut page = RustExecutableDocument::load_with_environment(
            "<iframe id=frame src='https://frame.example.test/child/page'></iframe>",
            &BTreeMap::from([(
                "https://frame.example.test/child/page".into(),
                "<meta http-equiv=refresh><p>child</p>".into(),
            )]),
            None,
            Some(Url::parse("https://frame.example.test/parent/page").unwrap()),
        )
        .unwrap();
        let child = *page.frame_realms.keys().next().unwrap();
        page.agent
            .host
            .execute(
                r#"
            const child=document.getElementById('frame').contentWindow;
            Object.getOwnPropertyDescriptor(HTMLMetaElement.prototype,'content').set.call(
                child.document.querySelector('meta'),'0; url=next');
        "#,
            )
            .unwrap();
        page.agent.host.drain_scheduled_timers(false).unwrap();
        assert!(page.agent.host.take_location_navigation().is_none());
        page.agent.host.activate_realm(child).unwrap();
        assert!(page.agent.host.take_location_navigation().is_none());
        page.agent.host.activate_realm(page.top_realm).unwrap();
        page.agent.host.drain_scheduled_timers(false).unwrap();
        assert!(page.agent.host.take_location_navigation().is_none());
        page.agent.host.activate_realm(child).unwrap();
        assert!(page.agent.host.take_location_navigation().is_none());
        // Expiry has marked the retained navigation due in its native owner.
        page.agent.host.activate_realm(page.top_realm).unwrap();
        page.agent.host.drain_scheduled_timers(false).unwrap();
        assert!(page.agent.host.take_location_navigation().is_none());
        page.agent.host.activate_realm(child).unwrap();
        let navigation = page.agent.host.take_location_navigation().unwrap();
        assert_eq!(navigation.url, "https://frame.example.test/child/next");
    }

