    #[test]
    fn frame_location_scheduler_consumes_native_requests_without_author_flags() {
        let mut page = RustExecutableDocument::load_with_environment(
            "<iframe src='https://frame.example.test/child'></iframe>",
            &BTreeMap::from([(
                "https://frame.example.test/child".into(),
                "<p>child</p>".into(),
            )]),
            None,
            Some(Url::parse("https://frame.example.test/root").unwrap()),
        )
        .unwrap();
        let realm = *page.frame_realms.keys().next().unwrap();
        let owner = page.frame_realms.get(&realm).unwrap().clone();
        page.agent.host.activate_realm(realm).unwrap();
        page.agent.host.execute(r#"
            Object.defineProperty(globalThis,'__oryn_opaque_origin',{
                configurable:true,get(){throw new Error('author flag consulted by native scheduler')}
            });
            location.href='https://frame.example.test/next';
        "#).unwrap();
        assert_eq!(
            page.agent.host.location_url().unwrap(),
            "https://frame.example.test/next"
        );
        page.drain_frame_location_navigations().unwrap();
        let pending = page
            .pending_frame_navigations
            .remove(&(owner.parent_realm, owner.frame))
            .unwrap();
        assert_eq!(
            pending.initiator_url.as_deref(),
            Some("https://frame.example.test/child")
        );
        assert_eq!(page.agent.host.active_realm(), page.top_realm);
        // A speculative Location URL different from the committed document is
        // not a second navigation once the owned request has been consumed.
        page.drain_frame_location_navigations().unwrap();
        assert!(page.pending_frame_navigations.is_empty());
    }

