    #[test]
    fn load_barrier_waits_for_stylesheet_task_then_releases_child_and_parent() {
        let mut page = RustExecutableDocument::load(
            "<iframe id=child srcdoc=\"&lt;style id=sheet>p{color:green}&lt;/style>\"></iframe>",
        )
        .unwrap();
        page.evaluate(
            r#"
            globalThis.order=[];
            const child=document.getElementById('child').contentWindow;
            child.document.getElementById('sheet').addEventListener('load',()=>order.push('sheet'));
            child.addEventListener('load',()=>order.push('child'));
            window.addEventListener('load',()=>order.push('parent'));
        "#,
        )
        .unwrap();
        let parent = page.top_realm;
        let child = *page
            .frame_realms
            .iter()
            .find(|(_, owner)| owner.parent_realm == parent)
            .unwrap()
            .0;
        page.agent.host.activate_realm(child).unwrap();
        let dom = page.agent.host.active_dom().unwrap();
        let node = dom
            .borrow()
            .arena()
            .iter()
            .find_map(|(id, node)| {
                (node.attributes.get_null("id").map(String::as_str) == Some("sheet")).then_some(id)
            })
            .unwrap();
        let revision = dom.borrow().arena().stylesheet_revision(node).unwrap();
        page.agent
            .host
            .queue_stylesheet_event(node, revision, true)
            .unwrap();
        for realm in [parent, child] {
            let generation = page
                .agent
                .host
                .realm_descriptor(realm)
                .unwrap()
                .document_generation;
            page.pending_document_loads.insert(
                realm,
                (
                    generation,
                    page.agent.host.document_stream_epoch(realm).unwrap(),
                ),
            );
        }
        page.flush_document_loads().unwrap();
        assert!(page.pending_document_loads.contains_key(&parent));
        assert!(page.pending_document_loads.contains_key(&child));
        page.agent.host.drain_scheduled_timers(false).unwrap();
        page.flush_document_loads().unwrap();
        assert!(page.pending_document_loads.is_empty());
        page.agent.host.activate_realm(parent).unwrap();
        assert_eq!(
            page.agent.host.evaluate_string("order.join(',')").unwrap(),
            "sheet,child,parent"
        );
    }

    #[test]
    fn invalid_image_urls_queue_errors_without_throwing_from_insertion() {
        let mut page = RustExecutableDocument::load("<body></body>").unwrap();
        page.evaluate(r#"
            globalThis.order=[];
            for(const src of ['', 'http://[']) {
                const img=document.createElement('img');img.setAttribute('src',src);
                img.addEventListener('error',event=>order.push(
                    [event.isTrusted,event.bubbles,event.cancelable,event.target===img].join(':')));
                const returned=document.body.appendChild(img);order.push(returned===img?'returned':'wrong');
            }
            const canceled=document.createElement('img');canceled.src='http://[';
            canceled.addEventListener('error',()=>order.push('stale-error'));
            document.body.appendChild(canceled);canceled.removeAttribute('src');
            order.push('synchronous-end');
        "#).unwrap();
        assert_eq!(
            page.evaluate("order.join(',')").unwrap(),
            "returned,returned,synchronous-end,true:false:false:true,true:false:false:true"
        );
    }

