    #[test]
    #[cfg(unix)]
    fn parser_frame_response_rejects_stale_stream_and_disconnected_owner() {
        let mut page = RustExecutableDocument::load("<iframe id=frame></iframe>").unwrap();
        let node = page.node_by_id("frame").unwrap();
        let dom = page.agent.dom.clone();
        let identity = ParserFetchContext::capture(&page.agent.host, &dom, node)
            .unwrap()
            .identity();
        let mut resources = BTreeMap::new();
        let mut deferred = BTreeMap::new();
        let mut diagnostics = Vec::new();
        let accepted_owner = ParserFrameOwner::capture(&page.agent.host, &dom, node).unwrap();
        for stale_stream in [true, false] {
            let mut captured = identity;
            if stale_stream {
                captured.stream_epoch += 1;
            } else {
                page.agent
                    .host
                    .execute(
                        "globalThis.detached=document.getElementById('frame');detached.remove()",
                    )
                    .unwrap();
            }
            let completion = ParserResourceCompletion::Frame {
                identity: captured,
                owner: accepted_owner.clone(),
                node,
                requested_url: "https://example.test/child".into(),
                result: Ok(LoadedFrameResource {
                    timing: None,
                    inherited_encoding: None,
                    response_headers: Vec::new(),
                    request_state: None,
                    document_referrer: String::new(),
                    raw_body_base64: None,
                    content_language: None,
                    body: None,
                    native_origin: None,
                    no_commit: false,
                    embedded_unavailable: false,
                    owner: accepted_owner.clone(),
                    _bytes: None,
                    terminal_error: None,
                    worker_policy_token: None,
                    url: "https://example.test/child".into(),
                    source: "<p>stale</p>".into(),
                    encoding: "UTF-8".into(),
                    content_type: Some("text/html".into()),
                    referrer_policy: String::new(),
                    modals_allowed: true,
                })
                .into(),
            };
            assert!(
                apply_parser_resource_completion(
                    completion,
                    &dom,
                    &mut page.agent.host,
                    &mut resources,
                    &mut deferred,
                    &mut diagnostics,
                    None
                )
                .unwrap()
                .is_none()
            );
        }
        assert!(resources.is_empty());
        assert!(diagnostics.is_empty());
    }

