    #[test]
    fn replacing_pending_parser_stream_discards_input_without_failing_new_document() {
        struct Input {
            polls: Rc<Cell<usize>>,
            dropped: Rc<Cell<bool>>,
        }
        impl crate::host::DocumentInput for Input {
            fn poll_next(&mut self) -> std::task::Poll<Option<Result<String, HostError>>> {
                self.polls.set(self.polls.get() + 1);
                std::task::Poll::Pending
            }
        }
        impl Drop for Input {
            fn drop(&mut self) {
                self.dropped.set(true);
            }
        }
        for close in [false, true] {
            let polls = Rc::new(Cell::new(0));
            let dropped = Rc::new(Cell::new(false));
            let input = crate::host::DocumentStream {
                content_language: None,
                chunks: Box::new(Input {
                    polls: polls.clone(),
                    dropped: dropped.clone(),
                }),
                content_type: Some("text/html".into()),
                encoding: Default::default(),
            };
            let mut page = RustExecutableDocument::load_stream_with_limits(
                input,
                &BTreeMap::new(),
                None,
                Some(Url::parse("https://example.test/").unwrap()),
                256 * 1024 * 1024,
                true,
            )
            .unwrap();
            page.execute("document.open();globalThis.loads=0;addEventListener('load',()=>loads++);document.write('<body><p id=fresh>replacement</p>')").unwrap();
            if close {
                page.execute("document.close()").unwrap();
            }
            page.resume_pending_parser().unwrap();
            assert_eq!(polls.get(), 0);
            assert!(dropped.get());
            // The canceled network input is gone, while an unclosed written
            // replacement legitimately owns its new pending parser.
            assert!(page.pending_parser.is_none() && page.pending_buffered.is_none());
            assert_eq!(page.parser_pending(), !close);
            let epoch = page
                .agent
                .host
                .document_stream_epoch(page.top_realm)
                .unwrap();
            assert!(
                page.frame_script_preparations
                    .iter()
                    .filter(|owner| owner.load.realm == page.top_realm)
                    .all(|owner| owner.load.identity.2 == epoch)
            );
            assert!(!page.document_load_stopped);
            assert_eq!(
                page.evaluate("document.getElementById('fresh').textContent")
                    .unwrap(),
                "replacement"
            );
            assert_eq!(page.document_load_complete(), close);
            assert_eq!(
                page.evaluate("String(loads)").unwrap(),
                if close { "1" } else { "0" }
            );
            if !close {
                page.execute("document.close()").unwrap();
            }
            assert!(page.document_load_complete());
            assert_eq!(page.evaluate("String(loads)").unwrap(), "1");
        }
    }

    #[test]
    #[cfg(all(unix, feature = "in-process-probe"))]
    fn snapshot_async_module_retains_graph_without_delaying_dom_content_loaded() {
        let context = crate::Browser::in_process_probe().new_context();
        let handle = context.new_page();
        let id = handle.page_id();
        context
            .install_document_security(id, "https://example.test/".into(), &[])
            .unwrap();
        let client = crate::context_service::SharedContextClient::direct(context, id);
        let source = r#"<body><script>globalThis.order=[]</script><script async type=module>await new Promise(resolve=>globalThis.releaseModule=resolve);order.push('module')</script>
            <script>order.push('classic');document.addEventListener('DOMContentLoaded',()=>order.push('dom'));</script>"#;
        let mut page = RustExecutableDocument::load_parsed_with_context_and_limits(
            html::parse(source),
            &BTreeMap::new(),
            None,
            Some(Url::parse("https://example.test/").unwrap()),
            256 * 1024 * 1024,
            (client, id, None),
        )
        .unwrap();
        assert!(page.document_interactive());
        assert!(page.document_load_complete());
        assert!(!page.frame_scripts_pending(Some(page.top_realm)));
        // Suspended module evaluation survives after document load completes.
        assert_eq!(
            page.agent.host.evaluate_string("order.join(',')").unwrap(),
            "classic,dom"
        );
        for _ in 0..16 {
            page.checkpoint().unwrap();
            if page
                .agent
                .host
                .evaluate_string("typeof releaseModule")
                .unwrap()
                == "function"
            {
                break;
            }
        }
        page.agent.host.execute("releaseModule()").unwrap();
        for _ in 0..16 {
            page.checkpoint().unwrap();
            if page.agent.host.evaluate_string("order.join(',')").unwrap() == "classic,dom,module" {
                break;
            }
        }
        assert_eq!(
            page.agent.host.evaluate_string("order.join(',')").unwrap(),
            "classic,dom,module"
        );
        assert!(!page.frame_scripts_pending(Some(page.top_realm)));
    }

