    #[test]
    fn compatibility_constructor_deadline_releases_pending_input() {
        struct PendingInput(Rc<Cell<bool>>);
        impl crate::host::DocumentInput for PendingInput {
            fn poll_next(&mut self) -> std::task::Poll<Option<Result<String, HostError>>> {
                std::task::Poll::Pending
            }
        }
        impl Drop for PendingInput {
            fn drop(&mut self) {
                self.0.set(true);
            }
        }
        let dropped = Rc::new(Cell::new(false));
        let input = crate::host::DocumentStream {
            content_language: None,
            chunks: Box::new(PendingInput(dropped.clone())),
            content_type: Some("text/html".into()),
            encoding: Default::default(),
        };
        let resources = BTreeMap::from([("oryn:execution-wall-ms".into(), "0".into())]);
        let result = RustExecutableDocument::load_stream_with_limits(
            input,
            &resources,
            None,
            None,
            256 * 1024 * 1024,
            false,
        );
        assert!(
            matches!(result,Err(HostError::Execution(message)) if message.contains("construction deadline exceeded"))
        );
        assert!(dropped.get());
    }

