    #[test]
    fn stopping_unclosed_child_releases_parent_without_completing_child() {
        let mut page = RustExecutableDocument::load(
            r#"
            <iframe id=child srcdoc="<body>initial"></iframe>
            <script>
                globalThis.loads=0;globalThis.childLoads=0;
                addEventListener('load',()=>loads++);
                const child=document.getElementById('child').contentWindow;
                child.document.open();child.document.write('<body>unclosed');
                child.addEventListener('load',()=>childLoads++);
            </script>
        "#,
        )
        .unwrap();
        assert!(!page.document_load_complete());
        let child = *page.frame_realms.keys().next().unwrap();
        page.execute("document.getElementById('child').contentWindow.stop()")
            .unwrap();
        assert!(page.agent.host.realm_document_load_stopped(child));
        page.flush_document_loads().unwrap();
        assert!(page.document_load_complete());
        page.queue_document_load(child).unwrap();
        assert_eq!(page.evaluate("loads+':'+childLoads+':'+document.getElementById('child').contentDocument.readyState").unwrap(),"1:0:loading");
        page.execute("const doc=document.getElementById('child').contentDocument;doc.open();doc.write('<body>new');doc.close()").unwrap();
        assert!(!page.agent.host.realm_document_load_stopped(child));
        assert_eq!(
            page.evaluate("document.getElementById('child').contentDocument.readyState")
                .unwrap(),
            "complete"
        );
        assert_eq!(page.evaluate("String(loads)").unwrap(), "1");
    }

