    #[test]
    fn stale_document_load_generation_is_discarded_and_releases_parent_barrier() {
        let mut page =
            RustExecutableDocument::load("<iframe srcdoc='<p>child</p>'></iframe>").unwrap();
        page.evaluate(
            r#"
            globalThis.order=[];
            const frame=document.querySelector('iframe');
            frame.contentWindow.addEventListener('load',()=>order.push('child'));
            frame.addEventListener('load',()=>order.push('frame'));
            window.addEventListener('load',()=>order.push('parent'));
        "#,
        )
        .unwrap();
        let parent = page.top_realm;
        let child = *page
            .frame_realms
            .iter()
            .find(|(_, owner)| owner.parent_realm == parent)
            .unwrap()
            .0;
        let parent_generation = page
            .agent
            .host
            .realm_descriptor(parent)
            .unwrap()
            .document_generation;
        let child_generation = page
            .agent
            .host
            .realm_descriptor(child)
            .unwrap()
            .document_generation;
        page.pending_document_loads.insert(
            parent,
            (
                parent_generation,
                page.agent.host.document_stream_epoch(parent).unwrap(),
            ),
        );
        page.pending_document_loads.insert(
            child,
            (
                child_generation.wrapping_sub(1),
                page.agent.host.document_stream_epoch(child).unwrap(),
            ),
        );
        page.agent.host.activate_realm(parent).unwrap();
        page.flush_document_loads().unwrap();
        assert!(page.pending_document_loads.is_empty());
        assert_eq!(page.agent.host.active_realm(), parent);
        assert_eq!(
            page.agent.host.evaluate_string("order.join(',')").unwrap(),
            "parent"
        );
    }

