            assert!((dx - 2.).abs() < 0.01 && (dy - 3.).abs() < 0.01);
            page.execute("document.elementFromPoint=()=>{throw Error('author hit')};Element.prototype.getBoundingClientRect=()=>{throw Error('author geometry')}").unwrap();
