#[cfg(test)]
mod navigation_timing_document_admission_tests {
    use super::*;
    use std::{
        sync::{Arc, atomic::Ordering},
        time::Instant,
    };
    #[test]
    fn root_child_and_stopped_document_share_native_timing_source_owner() {
        let mut page =
            RustExecutableDocument::load("<body><iframe srcdoc='<p>child</p>'></iframe>").unwrap();
        let budget = page.dynamic_scripts.source_bytes.clone();
        assert!(Arc::ptr_eq(
            &budget,
            &page.agent.host.source_allocation_budget()
        ));
        let retained = budget.load(Ordering::Acquire);
        assert!(retained > 0);
        page.stop_pending_document_load().unwrap();
        assert!(Arc::ptr_eq(&budget, &page.dynamic_scripts.source_bytes));
        assert_eq!(budget.load(Ordering::Acquire), retained);
        drop(page);
        assert_eq!(budget.load(Ordering::Acquire), 0);
    }
    #[test]
    fn timing_seed_capacity_rejection_preserves_incumbent_document() {
        let mut page = RustExecutableDocument::load("<body><p id=incumbent>original</p>").unwrap();
        let budget = page.dynamic_scripts.source_bytes.clone();
        let retained = budget.load(Ordering::Acquire);
        let occupied =
            ScriptSourceReservation::reserve(&budget, MAX_QUEUED_SCRIPT_SOURCE_BYTES - retained)
                .unwrap();
        let record = oryn_js::navigation_timing::NavigationTiming::new(
            Instant::now(),
            oryn_js::navigation_timing::Kind::Navigate,
        );
        assert!(
            page.agent
                .host
                .seed_navigation_timing(record, "https://example.test/rejected".into())
                .is_err()
        );
        assert_eq!(
            page.evaluate("document.getElementById('incumbent').textContent")
                .unwrap(),
            "original"
        );
        assert_eq!(
            budget.load(Ordering::Acquire),
            MAX_QUEUED_SCRIPT_SOURCE_BYTES
        );
        drop(occupied);
        assert_eq!(budget.load(Ordering::Acquire), retained);
    }
}

